package com.example

import com.example.ExamQuestionHelper.QSpec

/**
 * Curated Geography Live Exam Hall Bank — Domain 7:
 * ආර්ථික භූගෝල විද්‍යාව, කෘෂිකර්මය හා කර්මාන්ත (Economic Geography, Agriculture & Industry)
 */
internal object GeographyLiveExamEconomicBank {
  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun economicGeographyQuestions(): List<QSpec> {
    val t = "ආර්ථික භූගෝල විද්‍යාව, කෘෂිකර්මය හා කර්මාන්ත"
    return listOf(
      q(t, "ආර්ථික ක්‍රියාකාරකම් වර්ගීකරණයේදී 'ප්‍රාථමික අංශයට' (Primary Economic Activities) අයත් වන්නේ කුමන කටයුතුද?",
        "කෘෂිකර්මාන්තය, ධීවර කර්මාන්තය, වන කර්මාන්තය සහ පතල් කැණීම වැනි සෘජුවම ස්වාභාවික සම්පත් ලබා ගැනීම",
        "අමුද්‍රව්‍ය යන්ත්‍රසූත්‍ර මගින් පිරිපහදු කර කර්මාන්තශාලා තුළ නිමි භාණ්ඩ නිෂ්පාදනය කිරීම",
        "බැංකු සේවා, රක්ෂණ කටයුතු, ප්‍රවාහනය හා තොග හා සිල්ලර වෙළඳාම් සේවා සැපයීම",
        "පරිගණක මෘදුකාංග නිර්මාණය, විද්‍යාත්මක පර්යේෂණ හා තොරතුරු තාක්ෂණ උපදේශන සේවා සැපයීම",
        "ආර්ථික අංශ ප්‍රාථමික, ද්විතීයික, තෘතීයික සහ චතුර්ථක ලෙස වර්ග කෙරේ."),
      q(t, "ආර්ථිකයේ 'ද්විතීයික අංශයේ' (Secondary Sector) ප්‍රධාන කාර්යභාරය කුමක්ද?",
        "ප්‍රාථමික අංශයෙන් ලබාගත් අමුද්‍රව්‍ය කර්මාන්තශාලාවලදී වඩා වටිනා නිමි භාණ්ඩ බවට පරිවර්තනය කිරීම",
        "කුඹුරු හා ගොඩ ඉඩම් සකස් කර වී, එළවළු හා පලතුරු වැනි ආහාර බෝග වගා කර අස්වැන්න නෙළීම",
        "මගීන් හා භාණ්ඩ ප්‍රවාහනය, රෝහල් සෞඛ්‍ය සේවා, පාසල් අධ්‍යාපනය හා බැංකු සේවා පවත්වාගෙන යාම",
        "ගැඹුරු මුහුදේ ධීවර කටයුතු, භූගත ඛනිජ පතල් කැණීම හා ස්වාභාවික වනාන්තරවලින් දැව ලබා ගැනීම",
        "යපස් වානේ බවටද, කපු නූල් හා ඇඳුම් බවටද පත් කිරීම ද්විතීයික ක්‍රියාකාරකම් වේ."),
      q(t, "ආර්ථික ක්‍රියාකාරකම් අතර 'තෘතීයික අංශය' සහ 'චතුර්ථක අංශය' අතර ප්‍රධාන වෙනස කුමක්ද?",
        "තෘතීයික අංශය ප්‍රවාහන, වෙළඳ හා සෞඛ්‍ය සේවා සපයන අතර චතුර්ථක අංශය තොරතුරු තාක්ෂණ හා පර්යේෂණ සේවා සපයයි",
        "තෘතීයික අංශය කෘෂි බෝග වගාවෙන් සමන්විත වන අතර චතුර්ථක අංශය ඛනිජ හා ගල් අඟුරු පතල් කැණීමෙන් සමන්විත වේ",
        "තෘතීයික අංශය යකඩ හා වානේ නිෂ්පාදනය කරන අතර චතුර්ථක අංශය මෝටර් රථ හා නැව් එකලස් කිරීම සිදු කරයි",
        "තෘතීයික අංශය ග්‍රාමීය යැපුම් ගොවිතැනට පමණක් සීමා වන අතර චතුර්ථක අංශය ධීවර කර්මාන්තයට සීමා වේ",
        "සේවා අංශය තුළ දැනුම හා තාක්ෂණය මත පදනම් වූ විශේෂිත සේවා චතුර්ථක අංශය ලෙස වෙන් කෙරේ."),
      q(t, "යැපුම් කෘෂිකර්මය (Subsistence Agriculture) සහ වාණිජ කෘෂිකර්මය (Commercial Agriculture) අතර ප්‍රධාන වෙනස කුමක්ද?",
        "යැපුම් කෘෂිකර්මය පවුලේ පරිභෝජනය සඳහා සිදු කරන අතර වාණිජ කෘෂිකර්මය වෙළඳපොළට විකුණා ලාභ ලැබීමට සිදු කරයි",
        "යැපුම් කෘෂිකර්මයේදී ආහාර බෝග වගා නොකරන අතර වාණිජ කෘෂිකර්මයේදී ගොවි පවුලේ ආහාර සඳහා පමණක් වගා කරයි",
        "යැපුම් කෘෂිකර්මයේදී සියලු කටයුතු නවීන යන්ත්‍රසූත්‍රවලින් කරන අතර වාණිජ කෘෂිකර්මයේදී සාම්ප්‍රදායික අත් ආයුධ ගනී",
        "යැපුම් කෘෂිකර්මය මහා පරිමාණ වතු ආශ්‍රිතව කෙරෙන අතර වාණිජ කෘෂිකර්මය කුඩා ගෙවතුවලට පමණක් සීමා වේ",
        "හේන් ගොවිතැන යැපුම් කෘෂිකර්මයටත් වතු තේ වගාව වාණිජ කෘෂිකර්මයටත් නිදසුන් වේ."),
      q(t, "නිවර්තන ප්‍රදේශවල සාම්ප්‍රදායිකව සිදු කරන හේන් ගොවිතැන (Shifting Cultivation) ක්‍රියාත්මක වන්නේ කෙසේද?",
        "වනාන්තර කොටසක් හෙළි කර පුළුස්සා අළු මත කන්න කිහිපයක් වගා කර පස නිසරු වූ පසු අලුත් බිමකට මාරු වීම",
        "එකම ස්ථිර කුඹුරු ඉඩමක වසර සියයක් පුරාම රසායනික පොහොර යොදා අඛණ්ඩව වී වගා කිරීම",
        "මහා පරිමාණ ට්‍රැක්ටර් හා කම්බයින් යන්ත්‍ර යොදා ගනිමින් අපනයනය සඳහා තිරිඟු හා බඩ ඉරිඟු වගා කිරීම",
        "කඳුකර බෑවුම්වල ස්ථිර හෙල්මළු සකස් කර ජල සම්පාදන ඇළ මාර්ග ඔස්සේ වසර පුරාම එළවළු වගා කිරීම",
        "ශ්‍රී ලංකාවේ හේන් ලෙසද ඉන්දුනීසියාවේ ලඩාං ලෙසද මෙම සාම්ප්‍රදායික ක්‍රමය හැඳින්වේ."),
      q(t, "තීව්‍ර යැපුම් කෘෂිකර්මය (Intensive Subsistence Agriculture) දකුණු හා අග්නිදිග ආසියාවේ බහුල වීමට ප්‍රධාන හේතුව කුමක්ද?",
        "අධික ජන ඝනත්වය නිසා කුඩා බිමකින් උපරිම අස්වැන්නක් ගැනීමට විශාල මිනිස් ශ්‍රමයක් යොදා වගා කිරීම",
        "ගොවිතැන් කිරීමට සුදුසු වගා බිම් ප්‍රමාණය අසීමිත ලෙස වැඩි වී ජනගහනය ඉතා අඩු මට්ටමක පැවතීම",
        "වසර පුරාම කිසිදු වර්ෂාපතනයක් නොලැබෙන වියළි කාන්තාර දේශගුණයක් මෙම කලාපවල පැවතීම",
        "සියලුම ගොවීන් කෘෂිකර්මය අතහැර මහා පරිමාණ බර කර්මාන්තශාලාවල රැකියා සඳහා යොමු වී තිබීම",
        "නිසි ජල සම්පාදනයෙන් වසරකට කන්න දෙකක් හෝ තුනක් වී අස්වැන්න නෙළා ගැනේ."),
      q(t, "නිවර්තන රටවල දක්නට ලැබෙන වතු කෘෂිකර්මයේ (Plantation Agriculture) ප්‍රධාන ලක්ෂණය කුමක්ද?",
        "විශාල ඉඩම්වල අපනයන වෙළඳපොළ ඉලක්ක කර තේ, රබර්, පොල් හෝ කෝපි වැනි ඒක බෝග වගා කිරීම",
        "ගොවි පවුලේ දෛනික ආහාර අවශ්‍යතාව පමණක් සපුරාලීම සඳහා කුඩා බිම් කැබලිවල විවිධ එළවළු වැවීම",
        "කිසිදු ප්‍රාග්ධනයක් හෝ කම්කරු ශ්‍රමයක් භාවිත නොකර වනාන්තරවල ස්වාභාවිකව වැඩෙන පලතුරු එකතු කිරීම",
        "ශීත ධ්‍රැව කලාපයේ තුන්ද්‍රා බිම්වල ග්‍රීෂ්ම ඍතුවේදී පමණක් කෙටි කාලීන ධාන්‍ය බෝග වගා කිරීම",
        "වතු වගාවන්හි නිෂ්පාදන සැකසීමේ කර්මාන්තශාලාද බොහෝ විට වත්ත ඇතුළතම පිහිටා ඇත."),
      q(t, "විස්තීරණ වාණිජ ධාන්‍ය වගාව (Extensive Commercial Grain Farming) ප්‍රධාන වශයෙන් සිදු කරන භූගෝලීය කලාප මොනවාද?",
        "උතුරු ඇමරිකාවේ ප්‍රේරි, යුරේසියානු ස්ටෙප්ස්, ආර්ජන්ටිනාවේ පැම්පාස් සහ ඕස්ට්‍රේලියානු ඩවුන්ස් තණබිම්",
        "ඇමසන් ද්‍රෝණියේ සහ කොංගෝ ද්‍රෝණියේ ඝන නිවර්තන සමක වැසි වනාන්තර කලාප",
        "හිමාලය හා ඇන්ඩීස් කඳු වැටිවල මීටර් පන්දහසට වඩා උස් හිම වැසුණු කඳු මුදුන්",
        "ඉන්දියානු හා පැසිෆික් සාගරයේ කුඩා කොරල්පර දූපත් හා ලවණ කලපු ආශ්‍රිත වෙරළ තීර",
        "විශාල පැතලි ගොවිපළවල නවීන යන්ත්‍රසූත්‍ර යොදා ගනිමින් වාණිජ තිරිඟු වගාව සිදු කෙරේ."),
      q(t, "මිශ්‍ර ගොවිතැන (Mixed Farming) ගොවීන්ට ආර්ථික හා පාරිසරික ආරක්ෂාවක් සපයන්නේ කෙසේද?",
        "එකම ගොවිපළේ බෝග වගාව හා සත්ත්ව පාලනය එකට කර ආදායම් විවිධාංගීකරණය කිරීමෙන් හා ස්වාභාවික පොහොර ලැබීමෙන්",
        "වසර පුරාම කිසිදු වෙනසකින් තොරව තනි බෝගයක් පමණක් වගා කර රසායනික පොහොර අධිකව යෙදීමෙන්",
        "නිෂ්පාදන වෙළඳපොළේ විකිණීම සම්පූර්ණයෙන් තහනම් කර සියලු අස්වැන්න ගබඩා තුළ තබා ගැනීමෙන්",
        "සත්ත්ව පාලනය කාර්මික කලාපවලටත් බෝග වගාව කාන්තාරවලටත් වෙන් කර ප්‍රවාහනය වැඩි කිරීමෙන්",
        "බෝග අස්වැන්න අඩු වූවත් කිරි හා බිත්තර අලෙවියෙන් ගොවියාට ස්ථාවර ආදායමක් ලැබේ."),
      q(t, "වාණිජ කිරි ගොවිපළ කර්මාන්තය ප්‍රධාන නාගරික මධ්‍යස්ථාන ආසන්නයේ හෝ සෞම්‍ය තෙත් තෘණ භූමිවල පිහිටන්නේ ඇයි?",
        "නැවුම් කිරි ඉක්මනින් නරක් වන බැවින් වෙළඳපොළට ආසන්න වීමත් සෞම්‍ය දේශගුණය තණකොළ වගාවට සුදුසු වීමත්",
        "කාන්තාර වැලි කඳු මත ජලය නොමැතිව ගවයන් ඇති කිරීමෙන් කිරි නිෂ්පාදනය කිහිප ගුණයකින් ඉහළ යන බැවින්",
        "අධික සමක උෂ්ණත්වය නිසා ශීතාගාර පහසුකම් නොමැතිවම නැවුම් කිරි සති ගණනක් කල් තබා ගත හැකි බැවින්",
        "ඝන වැසි වනාන්තර කපා ඉවත් කර නාගරික වායු දූෂණය වැඩි කිරීමේ කාර්මික අරමුණක් පවතින බැවින්",
        "ශීතකරණ පහසුකම් හා කිරිපිටි තාක්ෂණය නිසා නවසීලන්තය වැනි රටවල් ලොව පුරා කිරි නිෂ්පාදන අපනයනය කරයි."),
      q(t, "මධ්‍යධරණී කෘෂිකර්මය (Mediterranean Agriculture) ලොව පුරා විශේෂිත වී ඇත්තේ කුමන ඉහළ වටිනාකමකින් යුත් බෝග සඳහාද?",
        "මිදි, ඔලිව්, දොඩම් හා ලෙමන් වැනි පැඟිරි පලතුරු, අත්තික්කා සහ මල් වගාව",
        "තෙත් වී, ජූට් කෙඳි, උණ බම්බු සහ කඩොලාන ආශ්‍රිත කලපු බෝග",
        "නිවර්තන රබර්, තෙල් පොල්, කොකෝවා සහ කුරුඳු වැනි වැවිලි බෝග",
        "ධ්‍රැවීය කේතුධර පයින් දැව, ස්පෘස් ගස් සහ ලයිකන තෘණ වර්ග",
        "ශීත ඍතු වැසි හා උණුසුම් වියළි ගිම්හානය මෙම පලතුරු බෝගවල සීනි සාන්ද්‍රණය වැඩි කිරීමට උපකාරී වේ."),
      q(t, "නාගරික ප්‍රදේශ ආසන්නයේ එළවළු හා මල් වගාව (Market Gardening & Horticulture) ස්ථානගත වීමට ප්‍රධාන හේතුව කුමක්ද?",
        "නැවුම් එළවළු හා කැපූ මල් ඉක්මනින් මැලවෙන බැවින් පාරිභෝගිකයන්ට දිනපතා සැපයීමට ප්‍රවාහන දුර අවම විය යුතු නිසා",
        "නාගරික ප්‍රදේශවල වසර පුරාම අධික හිම පතනයක් පවතින බැවින් එළවළු වගාවට සුදුසුම පස එහි ඇති නිසා",
        "ග්‍රාමීය ප්‍රදේශවල කිසිදු ගොවියෙකු හෝ ජල සැපයුමක් නොමැති වීම නිසා නගර මධ්‍යයේ වගා කිරීමට සිදු වන නිසා",
        "කර්මාන්තශාලා දුමාරයෙන් හා වාහන දුමෙන් කැපූ මල්වල වර්ණය හා සුවඳ ස්වාභාවිකව ඉහළ යන නිසා",
        "ශ්‍රී ලංකාවේ නුවරඑළිය, වැලිමඩ හා කල්පිටිය කොළඹ නාගරික වෙළඳපොළට එළවළු සපයන ප්‍රධාන කලාප වේ."),
      q(t, "කෘෂිකර්මාන්තයේදී 'බෝග මාරුව' (Crop Rotation) අනුගමනය කිරීම පසට හා ගොවියාට ප්‍රයෝජනවත් වන්නේ කෙසේද?",
        "එකම පසේ රනිල කුලයේ හා වෙනත් බෝග මාරුවෙන් මාරුවට වැවීමෙන් පෝෂක සමබර වී පළිබෝධ හානි අඩු වීම",
        "එකම බෝගය වසර ගණනාවක් නොකඩවා වැවීමෙන් පසෙහි ඇති සියලුම නයිට්‍රජන් ඉක්මනින් ඉවත් කර ගැනීම",
        "වගා බිමේ සියලුම ගස් හා පස් තට්ටු ඉවත් කර රසායනික වල්නාශක පමණක් යොදා පස වියළි කිරීම",
        "වැසි සමයේදී කුඹුරු හිස්ව තබා පාංශු ඛාදනය වේගවත් කිරීමෙන් නව පස් තට්ටු නිර්මාණය කර ගැනීම",
        "වී වගාවෙන් පසු මුං ඇට, කව්පි හෝ සෝයා බෝංචි වගා කිරීම නයිට්‍රජන් තිර කිරීමට උපකාරී වේ."),
      q(t, "1960 ගණන්වල ආසියාවේ හා ලතින් ඇමරිකාවේ ක්‍රියාත්මක කළ 'හරිත විප්ලවය' මගින් ආහාර නිෂ්පාදනය ඉහළ නැංවූයේ කෙසේද?",
        "වැඩි අස්වනු දෙන වැඩිදියුණු කළ බීජ, රසායනික පොහොර, පළිබෝධනාශක හා පුළුල් වාරි ජල සම්පාදනය යොදා ගැනීමෙන්",
        "සියලුම කෘෂිකාර්මික ඉඩම් වනාන්තර බවට පත් කර ස්වාභාවික පලතුරු පමණක් ආහාරයට ලබා ගැනීමෙන්",
        "ට්‍රැක්ටර් හා ජල සම්පාදන පද්ධති ඉවත් කර සාම්ප්‍රදායික හේන් ගොවිතැනට පමණක් රටවල් යොමු කිරීමෙන්",
        "ගොවි බිම් අතහැර දමා විදේශීය රටවලින් ගුවන් යානා මගින් සියලු ධාන්‍ය ආහාර ආනයනය කිරීමෙන්",
        "ඉන්දියාවේ හා පිලිපීනයේ ධාන්‍ය අස්වැන්න විශාල ලෙස ඉහළ ගියද අධික රසායනික භාවිතය නිසා පාරිසරික ගැටලුද මතු විය."),
      q(t, "නූතන කෘෂිකර්මයේදී ජලය හා පොහොර කාර්යක්ෂමව භාවිත කිරීමට නවීන තාක්ෂණය උපකාරී වන්නේ කෙසේද?",
        "පාංශු තෙතමන මාන, කාලගුණ දත්ත හා බිංදු ජල සම්පාදනය යොදා ගෙන අවශ්‍ය ප්‍රමාණයට පමණක් ජලය හා පොහොර යෙදීමෙන්",
        "මුළු වගා බිම පුරාම අධික ලෙස රසායනික පොහොර හා ජලය ගලා යාමට සලස්වා අපතේ යාම වැඩි කිරීමෙන්",
        "සියලුම කෘෂිකාර්මික යන්ත්‍රසූත්‍ර හා කාලගුණ වාර්තා ප්‍රතික්ෂේප කර අහඹු ලෙස බීජ වැපිරීමෙන්",
        "වගාවට අවශ්‍ය හිරු එළිය සම්පූර්ණයෙන් වසා දමා කෘත්‍රිම ගිනි මැල මගින් බෝග උණුසුම් කිරීමෙන්",
        "නිවැරදි තාක්ෂණික භාවිතය මගින් නිෂ්පාදන වියදම අඩු වී අස්වැන්න ඉහළ යයි."),
      q(t, "කාබනික ගොවිතැන (Organic Farming) සාම්ප්‍රදායික රසායනික ගොවිතැනින් වෙනස් වන්නේ කුමන පිළිවෙත් නිසාද?",
        "කෘත්‍රිම රසායනික පොහොර හා පළිබෝධනාශක වෙනුවට කොම්පෝස්ට්, කොළ පොහොර හා ජීව විද්‍යාත්මක පාලනය යොදා ගැනීම",
        "අස්වැන්න දෙගුණ කිරීම සඳහා රසායනික යූරියා පොහොර හා කෘත්‍රිම වල්නාශක දෙගුණයකින් වැඩිපුර යෙදීම",
        "වගා බිම සම්පූර්ණයෙන් කොන්ක්‍රීට් හෝ ප්ලාස්ටික් වලින් ආවරණය කර පසෙහි ක්ෂුද්‍ර ජීවීන් විනාශ කිරීම",
        "බෝග වර්ධනය වීම සඳහා සූර්යාලෝකය හා වැසි ජලය ලැබීම සම්පූර්ණයෙන්ම වළක්වා අඳුරේ වගා කිරීම",
        "කාබනික කෘෂි නිෂ්පාදන සඳහා ජාත්‍යන්තර වෙළඳපොළේ ඉහළ ඉල්ලුමක් හා මිලක් පවතී."),
      q(t, "කර්මාන්තශාලාවක් ස්ථානගත කිරීමේදී ආර්ථික භූගෝල විද්‍යාවේ සලකා බලන ප්‍රධාන භෞතික හා මානව සාධක මොනවාද?",
        "අමුද්‍රව්‍ය සැපයුම, බලශක්තිය, ජලය, ප්‍රවාහන පහසුකම්, පුහුණු ශ්‍රමය, ප්‍රාග්ධනය සහ වෙළඳපොළ සමීපතාව",
        "කම්කරුවන්ගේ වාර්ෂික නිවාඩු දින සංඛ්‍යාව, ක්‍රීඩා පිටි ගණන හා සිනමාහල් වල පිහිටීම",
        "ප්‍රදේශයේ මාසික වර්ෂාපතන විචලනය, වලාකුළු වර්ග හා සාගර උදම් රළවල උස පමණක් සැලකීම",
        "කර්මාන්තශාලා ගොඩනැගිලිවල බිත්ති වර්ණය, වහලයේ හැඩය සහ අවට පිහිටි පාසල් සංඛ්‍යාව",
        "ප්‍රවාහන හා නිෂ්පාදන පිරිවැය අවම වන ස්ථාන කර්මාන්ත සඳහා වඩාත් ලාභදායී වේ."),
      q(t, "බීම බෝතල් කිරීම හා බේකරි නිෂ්පාදන වැනි කර්මාන්ත බොහෝ විට පාරිභෝගික වෙළඳපොළ ආසන්නයේ පිහිටුවන්නේ ඇයි?",
        "නිමි භාණ්ඩ බරින් හා පරිමාවෙන් වැඩි වීමත් ඉක්මනින් පාරිභෝගිකයාට ලබා දිය යුතු වීමත් නිසා",
        "ඒවාට අවශ්‍ය සියලුම අමුද්‍රව්‍ය ගැඹුරු භූගත පතල් පතුලේම පිහිටා තිබීම හේතුවෙන්",
        "නගර මධ්‍යයෙන් ඈත් වූ දුරස්ථ කඳු මුදුන්වල ප්‍රවාහන පිරිවැය ශූන්‍ය වන නිසා",
        "මෙම නිෂ්පාදන වසර ගණනාවක් ගබඩා කර තැබිය හැකි බැවින් වෙළඳපොළ අවශ්‍ය නොවන නිසා",
        "සිසිල් බීම සෑදීමේදී සාන්ද්‍රණයට ජලය එකතු කර බර වැඩි කරන බැවින් නගර අසල බෝතල් කිරීම ලාභදායී වේ."),
      q(t, "ඉලෙක්ට්‍රොනික උපාංග, මෘදුකාංග හා ඖෂධ වැනි කර්මාන්ත නිශ්චිත අමුද්‍රව්‍ය ප්‍රභවයක් අසලම පිහිටීම අනිවාර්ය නොවන්නේ ඇයි?",
        "අමුද්‍රව්‍ය හා නිමි භාණ්ඩ බරින් ඉතා අඩු හා ඉහළ වටිනාකමකින් යුක්ත බැවින් ප්‍රවාහන පිරිවැය අල්ප වීම",
        "මෙම කර්මාන්තශාලා ක්‍රියාත්මක කිරීම සඳහා කිසිදු සේවකයෙකු හෝ විදුලි බලයක් අවශ්‍ය නොවන බැවින්",
        "නිපදවන භාණ්ඩ කිසිදු වෙළඳපොළකට ප්‍රවාහනය නොකර එම ස්ථානයේම ගබඩා කර තබන බැවින්",
        "ඒවා සාගර ජලය මත පාවෙන යාත්‍රා තුළ පමණක් නිපදවීමට ජාත්‍යන්තර නීතියෙන් නියම කර ඇති බැවින්",
        "මේවා 'පාදනිදහස් කර්මාන්ත' ලෙස හැඳින්වෙන අතර පුහුණු ශ්‍රමය හා හොඳ ප්‍රවාහන ජාල ඇති තැන්වල පිහිටුවයි."),
      q(t, "එකම ක්ෂේත්‍රයේ කර්මාන්තශාලා කිහිපයක් එකම කලාපයක පොකුරු ගැසී පිහිටීමෙන් (Industrial Agglomeration) ලැබෙන වාසිය කුමක්ද?",
        "පොදු ප්‍රවාහන හා විදුලි පහසුකම්, පුහුණු ශ්‍රමය හා සැපයුම් ජාල බෙදා ගැනීමෙන් නිෂ්පාදන පිරිවැය අඩු වීම",
        "කම්හල් අතර අමුද්‍රව්‍ය හා නිමි භාණ්ඩ ප්‍රවාහන වියදම දස ගුණයකින් ඉහළ ගොස් ලාභය අඩු වීම",
        "ප්‍රදේශයේ සිටින සියලුම පුහුණු ශ්‍රමිකයන් රැකියා අතහැර කෘෂිකර්මයට පමණක් යොමු වීම",
        "නිෂ්පාදන සඳහා පවතින දේශීය හා විදේශීය වෙළඳපොළ ඉල්ලුම සම්පූර්ණයෙන්ම අහිමි වී යාම",
        "කැලිෆෝනියාවේ සිලිකන් නිම්නය හා ඉන්දියාවේ බැංගලෝර් තාක්ෂණික පොකුරුවලට උදාහරණ වේ."),
      q(t, "යකඩ හා වානේ කර්මාන්තය සියලුම කර්මාන්තවල මූලික කර්මාන්තය ලෙස හඳුන්වනු ලබන්නේ ඇයි?",
        "මෝටර් රථ, නැව්, දුම්රිය, පාලම්, ගොඩනැගිලි හා යන්ත්‍රෝපකරණ නිපදවීමට අත්‍යවශ්‍ය මූලික ලෝහය වානේ බැවින්",
        "වානේ යනු ලෝකයේ සියලුම ලෝහ වර්ග අතරින් ඉතාම සැහැල්ලු හා ජලයේ පාවෙන ලෝහය වන බැවින්",
        "වානේ කෙලින්ම මිනිසුන්ගේ හා සතුන්ගේ දෛනික පෝෂණ අවශ්‍යතා සඳහා ආහාරයක් ලෙස ගන්නා බැවින්",
        "වානේ නිෂ්පාදනය කිරීම සඳහා කිසිදු ඛනිජ සම්පතක් හෝ තාප ශක්තියක් අවශ්‍ය නොවන බැවින්",
        "වානේ නිපදවීමට යපස්, කෝකිං ගල් අඟුරු සහ හුණුගල් ප්‍රධාන අමුද්‍රව්‍ය ලෙස අවශ්‍ය වේ."),
      q(t, "නූතන යකඩ හා වානේ කම්හල් පැරණි ගල් අඟුරු පතල් අසල සිට වෙරළබඩ වරායන් වෙත මාරු වූයේ ඇයි?",
        "දේශීය නිධි ක්ෂය වීමත් නැව් මගින් ආනයනය කරන යපස් හා ගල් අඟුරු වරායේදීම පහසුවෙන් බා ගැනීමත්",
        "විශාල භාණ්ඩ ප්‍රවාහන නැව් කඳු මුදුන් දක්වා ගමන් කරවා අමුද්‍රව්‍ය ගොඩබෑම පහසු වූ නිසා",
        "ගල් අඟුරු හා යකඩ ලෝපස් මුහුදු ජලයේ දිය කර පහසුවෙන් වානේ බවට පත් කළ හැකි නිසා",
        "වෙරළ තීරයේ ඇති සාමාන්‍ය මුහුදු වැලි පමණක් භාවිත කරමින් උසස් තත්ත්වයේ වානේ නිපදවිය හැකි නිසා",
        "ජපානයේ ස්වාභාවික යපස් ඉතා අඩු වුවද වෙරළාශ්‍රිත වානේ කර්මාන්තයෙන් ලොව ප්‍රමුඛයෙකු බවට පත් විය."),
      q(t, "බහුජාතික සමාගම් සිය නිෂ්පාදන කර්මාන්තශාලා බොහොමයක් ආසියානු රටවල පිහිටුවීමට බලපෑ ප්‍රධාන සාධක මොනවාද?",
        "තරඟකාරී ශ්‍රම පිරිවැය, පුළුල් කම්කරු සැපයුම, ආයෝජන සහන හා වර්ධනය වන ආසියානු වෙළඳපොළ",
        "නිෂ්පාදිත භාණ්ඩ වෙළඳපොළට යැවීමේ ප්‍රවාහන වියදම හිතාමතාම වැඩි කර ගැනීමේ අරමුණ",
        "නිමි භාණ්ඩවල අලෙවි මිල දස ගුණයකින් ඉහළ දමා පාරිභෝගික ඉල්ලුම අඩු කර ගැනීම",
        "කර්මාන්තශාලාවල සේවය කරන කම්කරු සංඛ්‍යාව සම්පූර්ණයෙන් ඉවත් කර වසා දැමීමේ සැලැස්ම",
        "ඇඟලුම්, පාවහන් හා ඉලෙක්ට්‍රොනික එකලස් කිරීමේ කර්මාන්ත ආසියානු රටවල් වෙත ව්‍යාප්ත වූයේ මේ අනුවය."),
      q(t, "ශ්‍රී ලංකාවේ කටුනායක, බියගම හා කොග්ගල වැනි අපනයන සැකසුම් කලාප (EPZs) රටේ ආර්ථිකයට දායක වන්නේ කෙසේද?",
        "විදේශ ආයෝජන ආකර්ෂණය කරමින් රැකියා උත්පාදනය කිරීම සහ කාර්මික අපනයන ආදායම ඉහළ නැංවීම",
        "ආනයන වියදම පමණක් අසීමිතව වැඩි කර රටේ විදේශ විනිමය සංචිත හිස් කිරීම මගින්",
        "කොළඹ හා ගාල්ල ප්‍රධාන වරායන් වසා දමා ජාත්‍යන්තර නාවික වෙළඳාම නතර කිරීම මගින්",
        "දිවයිනේ සාම්ප්‍රදායික වී හා එළවළු කෘෂිකර්මය නීතියෙන් සම්පූර්ණයෙන් තහනම් කිරීම මගින්",
        "කටුනායක අපනයන සැකසුම් කලාපය ගුවන්තොටුපළට හා කොළඹ වරායට ආසන්නව පිහිටීම විශාල වාසියකි."),
      q(t, "ශ්‍රී ලංකාවේ ප්‍රධාන කාර්මික අපනයන අංශය වන ඇඟලුම් කර්මාන්තය ජාත්‍යන්තර වෙළඳපොළේ තරඟකාරීව රැඳී සිටින්නේ කෙසේද?",
        "සදාචාරාත්මක කම්කරු ප්‍රමිතීන්, හරිත කර්මාන්තශාලා සහ ඉහළ අගය එකතු කළ විශේෂිත ඇඟලුම් නිපදවීමෙන්",
        "ළමා ශ්‍රමය බහුලව භාවිත කරමින් අඩු ගුණාත්මකභාවයෙන් යුත් ඇඳුම් පමණක් නිපදවීමෙන්",
        "පාරිසරික අපද්‍රව්‍ය නීති සම්පූර්ණයෙන් නොසලකා හරිමින් කර්මාන්තශාලා අපජලය ගංගාවලට මුදා හැරීමෙන්",
        "වෙනත් කිසිදු රෙදි වර්ගයක් නොගෙන ශ්‍රී ලංකාවේ වගා කරන කපු පමණක් සියයට සියයක් යොදා ගැනීමෙන්",
        "ශ්‍රී ලංකාවේ හරිත ඇඟලුම් කර්මාන්තශාලා ලොව ප්‍රමුඛ ගෝලීය සන්නාම සඳහා සැපයුම් සිදු කරයි."),
      q(t, "ශ්‍රී ලංකාවේ තේ කර්මාන්තය ජාත්‍යන්තර වෙළඳපොළේ සුවිශේෂී ස්ථානයක් හිමි කර ගැනීමට හේතු වූ භූගෝලීය සාධකය කුමක්ද?",
        "උඩරට, මැදරට හා පහතරට යන උන්නතාංශ කලාප තුනෙන් විවිධ රස හා සුවඳැති තේ නිපදවීමට හැකි වීම",
        "මුහුදු වෙරළේ ලවණ සහිත වැලි තට්ටු මත පමණක් තේ පැළ වගා කිරීමට හැකි වීම",
        "වසරකට එක් මාසයකදී පමණක් ඉතා කෙටි කාලයක් තුළ දළු කැඩීමේ හැකියාව පැවතීම",
        "නිපදවන තේ සම්පූර්ණයෙන්ම විදේශයන්ට නොයවා දේශීය වෙළඳපොළේ පමණක් පරිභෝජනය කිරීම",
        "පහතරට තේ රසයෙන් හා කහට ගතියෙන්ද, උඩරට තේ සුවඳින්ද ලෝක ප්‍රසිද්ධය."),
      q(t, "ජාත්‍යන්තර භාණ්ඩ ප්‍රවාහනයෙන් වැඩිම පරිමාවක් සාගර නාවික ප්‍රවාහනය මගින් සිදු කරන්නේ ඇයි?",
        "බහාලුම් නැව් හා තොග නැව් මගින් අතිවිශාල බර භාණ්ඩ අවම පිරිවැයකින් දිගු දුර ගෙන යා හැකි බැවින්",
        "භාණ්ඩ ප්‍රවාහන නැව් ජෙට් ගුවන් යානාවලට වඩා කිහිප ගුණයකින් වැඩි වේගයකින් ගමන් කරන බැවින්",
        "ලෝකයේ සෑම නගරයකටම හා නිවසකටම සෘජුවම මුහුදු නැව් මගින් භාණ්ඩ බෙදා හැරිය හැකි බැවින්",
        "විශාල සාගර නැව් ක්‍රියාත්මක කිරීම සඳහා කිසිදු ඉන්ධන හෝ බලශක්ති පිරිවැයක් වැය නොවන බැවින්",
        "ඉක්මනින් නරක් වන මල් හා ඖෂධ සඳහා වේගවත් ගුවන් ප්‍රවාහනය යොදා ගැනේ."),
      q(t, "ප්‍රමිතිගත වානේ බහාලුම් (Containers) භාවිතය ගෝලීය වෙළඳාමේ විප්ලවයක් ඇති කළේ කෙසේද?",
        "බහාලුම් විවෘත නොකරම දොඹකර මගින් නැවෙන් දුම්රියට හා ලොරියට මාරු කිරීමෙන් කාලය හා හානි අඩු වීම",
        "සෑම වරායකදීම භාණ්ඩ පෙට්ටි කඩා අතින් ඇද වෙනත් වාහනවලට පැටවීමේ පැරණි ක්‍රමය දියුණු කිරීම",
        "බහාලුම් නැව්වල ප්‍රමාණය ඉතා කුඩා කර ගංගා ඔස්සේ පමණක් ජාත්‍යන්තර වෙළඳාම සිදු කිරීම",
        "ගොඩබිම් දුම්රිය මාර්ග හා මහාමාර්ග සම්පූර්ණයෙන් ඉවත් කර ගුවන් ප්‍රවාහනයට පමණක් මාරු වීම",
        "බහාලුම්කරණය නූතන ගෝලීය සැපයුම් දාමයන් කාර්යක්ෂම කිරීමට ප්‍රධාන හේතුවක් විය."),
      q(t, "ලෝක නාවික ගමනාගමනයේ කාලය හා දුර සැතපුම් දහස් ගණනක් ඉතිරි කරන ප්‍රධාන කෘත්‍රිම නාවික ඇළ මාර්ග දෙක මොනවාද?",
        "සූවස් ඇළ (මධ්‍යධරණී-රතු මුහුද) සහ පැනමා ඇළ (අත්ලාන්තික්-පැසිෆික්)",
        "නයිල් ගංගා නාවික ඇළ මාර්ගය සහ ඇමසන් වනාන්තර අභ්‍යන්තර ඇළ මාර්ගය",
        "ශ්‍රී ලංකාවේ පුරාණ යෝධ ඇළ මාර්ගය සහ කලා වැව ජය ගඟ වාරි ඇළ මාර්ගය",
        "කැස්පියන් මුහුදු ඇළ මාර්ගය සහ නැගෙනහිර අප්‍රිකා වික්ටෝරියා විල් ඇළ",
        "සූවස් ඇළ නොමැති නම් යුරෝපයේ සිට ආසියාවට යන නැව්වලට අප්‍රිකාව වටා දින ගණනක් වැඩිපුර යාමට සිදුවේ."),
      q(t, "රටවල් අතර ජාත්‍යන්තර වෙළඳාම (International Trade) ඇති වීමට මූලික භූගෝලීය හේතුව කුමක්ද?",
        "සම්පත්, දේශගුණය හා තාක්ෂණය අසමාන බැවින් සෑම රටක්ම තමන්ට වාසිදායක භාණ්ඩ නිපදවා හුවමාරු කර ගැනීම",
        "සෑම රටක්ම තමන්ට අවශ්‍ය සියලුම භාණ්ඩ හා ඛනිජ දේශීයවම සියයට සියයක් නිපදවා ගන්නා බැවින්",
        "ලෝකයේ සෑම රටකම කෘෂි බෝග, කාර්මික පහසුකම් හා ඛනිජ සංචිත සමානව පිහිටා ඇති බැවින්",
        "දේශීය වෙළඳපොළ තුළ මුදල් භාවිතය සම්පූර්ණයෙන් තහනම් කර භාණ්ඩ ඉවත දැමීමට සිදු වන බැවින්",
        "ශ්‍රී ලංකාව තේ හා ඇඟලුම් අපනයනය කර බොරතෙල්, ඖෂධ හා යන්ත්‍රෝපකරණ ආනයනය කිරීම මීට නිදසුනකි."),
      q(t, "රටක 'වෙළඳ ශේෂය' (Balance of Trade) අහිතකර හෙවත් 'වෙළඳ හිඟයක්' ඇතිවන්නේ කුමන අවස්ථාවේදීද?",
        "රටක ආනයන වියදම එහි අපනයන ආදායමට වඩා වැඩි වන විට",
        "රටක අපනයන ආදායම එහි ආනයන වියදමට වඩා බෙහෙවින් වැඩි වන විට",
        "රටක ආනයන හා අපනයන වටිනාකම සම්පූර්ණයෙන්ම ශූන්‍ය මට්ටමේ පවතින විට",
        "විදේශීය සංචාරකයන් පැමිණීමෙන් රටට ලැබෙන විදේශ විනිමය ආදායම වැඩි වන විට",
        "අගය එකතු කළ අපනයන වැඩි කිරීම හා අත්‍යවශ්‍ය නොවන ආනයන සීමා කිරීම වෙළඳ හිඟය අඩු කිරීමට උපකාරී වේ."),
      q(t, "ජාත්‍යන්තර වෙළඳාමේදී තීරුබදු (Tariffs) සහ ආනයන කෝටා (Quotas) රජයන් විසින් යොදා ගන්නේ ඇයි?",
        "විදේශීය ලාභ ආනයනවලින් දේශීය ගොවීන් හා කර්මාන්ත ආරක්ෂා කර ගැනීමට හා රාජ්‍ය ආදායම වැඩි කිරීමට",
        "රටේ පවතින දේශීය කර්මාන්තශාලා සියල්ල වසා දමා සම්පූර්ණයෙන් ආනයන මත පමණක් යැපීමට",
        "විදේශීය රටවල නිෂ්පාදනය කරන සුඛෝපභෝගී භාණ්ඩ ජනතාව අතර නොමිලේ බෙදා හැරීම සඳහා",
        "රටේ අපනයන භාණ්ඩ විදේශ වෙළඳපොළට යැවීම සම්පූර්ණයෙන් තහනම් කර ආදායම නැවැත්වීමට",
        "ලෝක වෙළඳ සංවිධානය රටවල් අතර සාධාරණ වෙළඳ රාමුවක් තුළ වෙළඳ බාධක අඩු කිරීමට කටයුතු කරයි."),
      q(t, "සංචාරක ව්‍යාපාරය ආර්ථික විද්‍යාවේදී 'අදෘශ්‍යමාන අපනයනයක්' ලෙස හඳුන්වනු ලබන්නේ ඇයි?",
        "භෞතික භාණ්ඩ රටින් පිටතට නොයවා, සංචාරකයන්ට රට තුළදී සේවා සපයා විදේශ විනිමය උපයන බැවින්",
        "සංචාරකයන් ගුවන් තොටුපළෙන් පැමිණෙන විට රේගු නිලධාරීන්ට නොපෙනෙන ආකාරයෙන් ගමන් කරන බැවින්",
        "සංචාරක ව්‍යාපාරය ජාත්‍යන්තර නීතිය යටතේ නීතිවිරෝධී වෙළඳ කටයුත්තක් ලෙස සලකනු ලබන බැවින්",
        "විදේශීය සංචාරකයන්ගෙන් හෝටල් හා ප්‍රවාහන සේවා සඳහා කිසිදු මුදලක් අය නොකරන බැවින්",
        "පාරිසරික සංචාරක ව්‍යාපාරය ස්වාභාවික පරිසරයට හානි නොකර දේශීය ප්‍රජාවට ප්‍රතිලාභ සලසයි."),
      q(t, "ප්‍රාථමික කෘෂි නිෂ්පාදන අමුවෙන් අපනයනය කිරීම වෙනුවට 'අගය එකතු කිරීම' (Value Addition) සිදු කිරීමෙන් රටට ලැබෙන ප්‍රධාන ආර්ථික වාසිය කුමක්ද?",
        "සැකසූ තේ පැකට් හා කුරුඳු තෙල් ලෙස අපනයනය කිරීමෙන් ඉහළ විදේශ විනිමය හා රැකියා ලැබීම",
        "නිෂ්පාදන පිරිවැය අඩු කිරීමට සියලු දේශීය කර්මාන්තශාලා හා ඇසුරුම් ආයතන වසා දැමීම",
        "අමුද්‍රව්‍ය විදේශ රටවලට නොයවා ගබඩා තුළ තබා දේශීය පරිභෝජනය සඳහා පමණක් භාවිත කිරීම",
        "කෘෂි නිෂ්පාදනවල බර වැඩි කර ප්‍රවාහන ගාස්තු ඉහළ දැමීමෙන් වෙළඳපොළ ඉල්ලුම අඩු කර ගැනීම",
        "සැකසූ හා සන්නාමගත නිෂ්පාදන සඳහා අමු කෘෂි භාණ්ඩවලට වඩා ඉහළ මිලක් ලෝක වෙළඳපොළේ හිමි වේ."),
      q(t, "යුරෝපා සංගමය (EU) සහ ආසියාන් (ASEAN) වැනි කලාපීය වෙළඳ සංවිධාන පිහිටුවීමේ ප්‍රධාන ආර්ථික අරමුණ කුමක්ද?",
        "සාමාජික රටවල් අතර තීරු බදු අඩු කර භාණ්ඩ හා සේවා හුවමාරුව පහසු කිරීම",
        "සාමාජික රටවල් අතර සියලු ගොඩබිම් හා සාගර වෙළඳ ගනුදෙනු සම්පූර්ණයෙන්ම තහනම් කර දැමීම",
        "ලෝකයේ සෙසු රටවලට ආහාර හා ඖෂධ අපනයනය කිරීම නීති මගින් සම්පූර්ණයෙන්ම නතර කිරීම",
        "එක් සාමාජික රටක කර්මාන්තශාලා සියල්ල වසා දමා අනෙක් රටවලින් පමණක් භාණ්ඩ ආනයනය කිරීම",
        "දකුණු ආසියානු රටවල් අතර වෙළඳ සහයෝගීතාව වර්ධනය කිරීමට SAARC හා SAFTA ගිවිසුම් ඇති කර ඇත."),
      q(t, "බහුජාතික සමාගම් (MNCs) ලෝකයේ විවිධ රටවල ආර්ථික කටයුතු සංවිධානය කරන ආකාරය කුමක්ද?",
        "මූලස්ථානය එක් රටක තබාගෙන වෙනත් රටවලින් අමුද්‍රව්‍ය, නිෂ්පාදනය හා අලෙවිය මෙහෙයවීම",
        "තම මව් රටේ ගමකට පමණක් සීමා වී කිසිදු විදේශීය ගනුදෙනුවක් නොකර පවත්වාගෙන යාම",
        "විදේශීය රටවලින් කිසිදු අමුද්‍රව්‍යයක් හෝ ශ්‍රමයක් ලබා නොගෙන සියල්ල හුදකලාව නිපදවීම",
        "සෑම රටකම කර්මාන්තශාලා වසා දමා භාණ්ඩ හුවමාරු ක්‍රමයෙන් තොරව දේශීයව පමණක් ක්‍රියාත්මක වීම",
        "බහුජාතික සමාගම් සංවර්ධනය වෙමින් පවතින රටවලට ප්‍රාග්ධනය, නව තාක්ෂණය හා රැකියා රැගෙන එයි."),
      q(t, "විදුලි වාණිජ්‍යය (E-Commerce) ග්‍රාමීය කුඩා ව්‍යවසායකයින්ගේ වෙළඳපොළ ප්‍රවේශය පුළුල් කර ඇත්තේ කෙසේද?",
        "අන්තර්ජාලය හරහා දුරස්ථ පාරිභෝගිකයන්ට සෘජුවම භාණ්ඩ හා සේවා අලෙවි කිරීමට හැකි වීම",
        "භාණ්ඩ නිෂ්පාදනය නතර කර සියලු දෙනාම නගරයේ විශාල සුපිරි වෙළඳසැල් තුළ පමණක් විකිණීම",
        "ප්‍රවාහන හා තැපැල් සේවා අවශ්‍යතාව සම්පූර්ණයෙන් ඉවත් කර භාණ්ඩ නිවසේම තබා ගැනීම",
        "විදේශීය ගනුදෙනුකරුවන්ට භාණ්ඩ අලෙවි කිරීම තහනම් කර ගම ඇතුළත පමණක් වෙළඳාම් කිරීම",
        "අන්තර්ජාල වෙළඳාම සාර්ථක වීමට කාර්යක්ෂම තැපැල් හා පාර්සල් බෙදා හැරීමේ ජාලයක් අවශ්‍ය වේ."),
      q(t, "ශ්‍රී ලංකාවේ තොරතුරු තාක්ෂණ සේවා හා මෘදුකාංග අපනයන අංශය වේගයෙන් වර්ධනය වීමට බලපෑ ප්‍රධාන සාධක මොනවාද?",
        "ඉහළ අධ්‍යාපන මට්ටම, ඉංග්‍රීසි දැනුම, පරිගණක නිපුණතාව සහ තරඟකාරී සේවා පිරිවැය",
        "විශාල ගල් අඟුරු පතල්, බොරතෙල් නිධි සහ අධික ජල සම්පාදන වාරි පද්ධති පැවතීම",
        "සාගරයේ ගැඹුරු ධීවර වරායන් හා විශාල යකඩ උණු කිරීමේ කර්මාන්තශාලා බහුලව පිහිටීම",
        "වසර පුරා ලැබෙන නිරිතදිග හා ඊසානදිග මෝසම් වර්ෂාපතනය සහ සාරවත් රොන්මඩ පස පැවතීම",
        "තොරතුරු තාක්ෂණ අංශය පරිසර දූෂණයකින් තොරව ඉහළ විදේශ විනිමයක් උපයන සේවා කර්මාන්තයකි."),
      q(t, "මොරටුව (ලී බඩු), අම්බලන්ගොඩ (වෙස් මුහුණු), පිළිමතලාව (පිත්තල) හා රත්නපුර (මැණික්) යන කර්මාන්ත එම නගරවල ඒකරාශී වී ඇත්තේ ඇයි?",
        "පාරම්පරික ශිල්පීය කුසලතා පරම්පරාවෙන් පැවතීම, අමුද්‍රව්‍ය සමීපතාව සහ ස්ථාපිත කීර්තිය නිසා",
        "වෙනත් දිස්ත්‍රික්කවල මෙම අත්කම් නිෂ්පාදනය කිරීම රජයේ නීතියෙන් සම්පූර්ණයෙන් තහනම් කර ඇති නිසා",
        "එම නගර සියල්ලම ස්වාභාවික මුහුදු වරායන් හා ජාත්‍යන්තර ගුවන් තොටුපළවල් අසල පිහිටි නිසා",
        "වසරේ සෑම මාසයකම එම ප්‍රදේශවල පවතින අධික ශීතල හා හිම පතනය නිෂ්පාදනයට උපකාරී වන නිසා",
        "සාම්ප්‍රදායික කර්මාන්ත මුල් හේතුව වෙනස් වුවද එම ස්ථානයේම රැඳී පැවතීම කාර්මික අවස්ථිතිභාවය ලෙස හැඳින්වේ."),
      q(t, "නූතන ලෝකයේ අර්ධ සන්නායක හා ඉලෙක්ට්‍රොනික උපාංග නිෂ්පාදනය ඉතා වැදගත් කර්මාන්තයක් බවට පත්ව ඇත්තේ ඇයි?",
        "පරිගණක, ජංගම දුරකථන, වෛද්‍ය උපකරණ හා නවීන වාහන ක්‍රියාත්මක වීමට මයික්‍රොචිප් අත්‍යවශ්‍ය වීම",
        "ඒවා කෙලින්ම මිනිසුන්ගේ දෛනික පෝෂණය සඳහා ආහාර බෝග ලෙස වගා කර අස්වනු නෙළන බැවින්",
        "ඒවා සාම්ප්‍රදායික ගෘහ කර්මාන්තයක් ලෙස දැව හා මැටි පමණක් යොදා අතින් සාදන බැවින්",
        "ලෝකයේ සෑම කර්මාන්තශාලාවක්ම විදුලි බලය නොමැතිව ගල් අඟුරු වාෂ්පයෙන් පමණක් ක්‍රියා කරන බැවින්",
        "තායිවානය, දකුණු කොරියාව, ජපානය හා ඇමෙරිකා එක්සත් ජනපදය අර්ධ සන්නායක නිෂ්පාදනයේ ප්‍රමුඛයෝ වෙති."),
      q(t, "කැනඩාව, ස්වීඩනය හා ෆින්ලන්තය වැනි රටවල කඩදාසි හා පල්ප් කර්මාන්තය බහුලව ස්ථානගත වී ඇත්තේ ඇයි?",
        "කේතුධර වනාන්තරවල මෘදු දැව සැපයුම, දැව ප්‍රවාහනයට ගංගා සහ ලාභදායී ජල විදුලි බලය පැවතීම",
        "වසර පුරා පවතින වියළි කාන්තාර වැලි තට්ටු සහ කිසිදු ගංගාවක් නොමැති තැනිතලා පැවතීම",
        "උණුසුම් සමක වැසි වනාන්තරවල වැඩෙන තද කළුවර හා බුරුත වැනි දැඩි දැව බහුලව පැවතීම",
        "සාගර පතුලෙන් ලබාගන්නා ලවණ මිශ්‍ර කොරල් පර හා මුහුදු වැලි කඩදාසි සෑදීමට යොදා ගැනීම",
        "කේතුධර වනාන්තරවල පයින් හා ස්පෘස් දැව පල්ප් නිෂ්පාදනයට ඉතා යෝග්‍ය වේ."),
      q(t, "සංවර්ධනය වෙමින් පවතින රටවල දක්නට ලැබෙන 'ද්විත්ව ආර්ථික ලක්ෂණය' (Dual Economy) යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "නවීන නාගරික කාර්මික-සේවා අංශයත් සාම්ප්‍රදායික ග්‍රාමීය යැපුම් කෘෂි අංශයත් එකවර පැවතීම",
        "රටේ සියලුම පුරවැසියන් එකම ආකාරයේ තොරතුරු තාක්ෂණ රැකියාවල පමණක් නිරත වී සිටීම",
        "මුදල් භාවිතය සම්පූර්ණයෙන්ම ඉවත් කර භාණ්ඩ හුවමාරු ක්‍රමයෙන් පමණක් ගනුදෙනු සිදු කිරීම",
        "ග්‍රාමීය හා නාගරික සෑම ප්‍රදේශයකම ආදායම් මට්ටම හා යටිතල පහසුකම් සියයට සියයක් සමාන වීම",
        "ග්‍රාමීය ප්‍රදේශවලට නවීන තාක්ෂණය හා වෙළඳපොළ පහසුකම් ලබා දීමෙන් මෙම පරතරය අඩු කළ හැකිය."),
      q(t, "යාපනය හා කල්පිටිය වැනි ප්‍රදේශවල නළ ළිං ජලයෙන් කෙරෙන වාණිජ වගාවන් මුහුණ දෙන ප්‍රධාන පාරිසරික අවදානම කුමක්ද?",
        "අධික රසායනික පොහොර භූගත ජලයට මිශ්‍ර වීමත් ජලය වැඩිපුර ඇදීමෙන් ලවණ වීමත්",
        "වසර පුරාම කිසිදු බාධාවකින් තොරව අධික මෝසම් ගංවතුර නිසා වගා බිම් සම්පූර්ණයෙන් යට වීම",
        "පසෙහි ඇති සියලුම වැලි තට්ටු එක්වරම ඝන ගිනිකඳු පාෂාණ බවට පරිවර්තනය වී පැලෑටි වැසී යාම",
        "භූගත ජල උල්පත් ඉතා සීතල වී වගා බිම් මත අයිස් තට්ටු බැඳීමෙන් අස්වැන්න අඩු වීම",
        "බිංදු ජල සම්පාදනය හා කාබනික පොහොර භාවිතය භූගත ජල සම්පත සුරැකීමට උපකාරී වේ."),
      q(t, "ශ්‍රී ලංකාවේ වයඹදිග වෙරළ තීරයේ කලපු ආශ්‍රිත ඉස්සන් වගාව පසුබෑමකට ලක්වීමට බලපෑ ප්‍රධාන හේතුව කුමක්ද?",
        "අධික ඝනත්වයකින් වගා කිරීම නිසා වෛරස් රෝග පැතිරීම, ජල දූෂණය හා කඩොලාන විනාශ වීම",
        "ඉස්සන්ට ලවණ මිශ්‍ර කලපු ජලය කිසිසේත්ම ඔරොත්තු නොදීම නිසා පැටවුන් වර්ධනය නොවීම",
        "ජාත්‍යන්තර වෙළඳපොළේ මුහුදු ආහාර පරිභෝජනය සම්පූර්ණයෙන් තහනම් කර ඉල්ලුම නැති වීම",
        "වෙරළබඩ තීරයේ වසර පුරා පවතින අධික හිම පතනය නිසා ඉස්සන් පොකුණු සම්පූර්ණයෙන් මිදී යාම",
        "තිරසාර ජලජීවී වගාව සඳහා පොකුණු ජල පිරිපහදුව හා කඩොලාන පරිසර පද්ධති ආරක්ෂා කිරීම අත්‍යවශ්‍ය වේ."),
      q(t, "බණ්ඩාරවෙල, වැලිමඩ හා නුවරඑළිය වැනි ප්‍රදේශවල පොලිටනල් (Polytunnels) හෙවත් ආරක්ෂිත ගෘහ වගාව ප්‍රචලිත වන්නේ ඇයි?",
        "උෂ්ණත්වය හා ජලය පාලනය කර කෘමි හානි අවමව වසර පුරාම උසස් තත්ත්වයේ අස්වනු ලැබීම",
        "බෝගවලට අවශ්‍ය සූර්යාලෝකය සම්පූර්ණයෙන්ම වළක්වා අඳුරේ තබා එළවළු වර්ධනය වේගවත් කිරීම",
        "වී වගාව සඳහා විශාල ජලාශ ඉදි කිරීමට අවශ්‍ය නොවන පරිදි ගොවි බිම් වියළි කර තැබීම",
        "වැඩි වර්ෂාපතනයක් ඇති කාලයේදී පවා පොලිටනල් ඇතුළත කෘත්‍රිම හිම කැට ඇති කර ගැනීම",
        "ආරක්ෂිත ගෘහ තුළ බෙල් පෙපර්, තක්කාලි, සලාද කොළ හා කැපූ මල් ඉහළ ගුණාත්මකභාවයෙන් වගා කෙරේ."),
      q(t, "18 වන සියවසේ එංගලන්තයේ ආරම්භ වූ කාර්මික විප්ලවය නිෂ්පාදන රටාව වෙනස් කළේ කෙසේද?",
        "මිනිස් ශ්‍රමය වෙනුවට ගල් අඟුරු බලයෙන් ක්‍රියා කරන වාෂ්ප යන්ත්‍ර හා කම්හල් ක්‍රමය බිහි වීම",
        "සියලුම නාගරික කර්මාන්තශාලා වසා දමා සම්පූර්ණයෙන්ම හේන් ගොවිතැන වෙත ජනතාව මාරු වීම",
        "විදුලි බලය හා අන්තර්ජාලය යොදා ගනිමින් ලෝකයේ සෑම නිවසකම මෝටර් රථ නිපදවීම ආරම්භ කිරීම",
        "ගල් අඟුරු හා යකඩ භාවිතය තහනම් කර මැටි හා දැව ආයුධ පමණක් නිපදවීමට යොමු වීම",
        "කාර්මික විප්ලවයත් සමඟ ගෘහ කර්මාන්ත ක්‍රමයෙන් අඩු වී නාගරික කර්මාන්තශාලා බිහි විය."),
      q(t, "කර්මාන්ත ක්ෂේත්‍රයේ නවීන ස්වයංක්‍රීයකරණය හා රොබෝ තාක්ෂණය භාවිතය නිසා සිදුවන ප්‍රධාන වෙනස කුමක්ද?",
        "නිෂ්පාදන වේගය හා නිරවද්‍යතාව ඉහළ ගියද සාම්ප්‍රදායික නුපුහුණු කම්කරු රැකියා අඩු වීම",
        "සෑම කර්මාන්තශාලාවක්ම වාෂ්ප එන්ජින් වෙත ආපසු ගොස් විදුලි බලය භාවිතය නතර කිරීම",
        "නිෂ්පාදන කටයුතු අතින්ම සිදු කිරීම නිසා එක් භාණ්ඩයක් සෑදීමට ගතවන කාලය දෙගුණ වීම",
        "සියලුම තාක්ෂණික ඉංජිනේරුවන් කර්මාන්තශාලාවලින් ඉවත් කර කෘෂි කම්කරුවන් පමණක් බඳවා ගැනීම",
        "නවීන කර්මාන්තවලට ගැළපෙන පරිදි තරුණ පරපුරට තාක්ෂණික හා ඩිජිටල් නිපුණතා ලබා දීම වැදගත් වේ."),
      q(t, "'ආර්ථික වර්ධනය' (Economic Growth) සහ 'ආර්ථික සංවර්ධනය' (Economic Development) අතර ප්‍රධාන වෙනස කුමක්ද?",
        "ආර්ථික වර්ධනය නිෂ්පාදන ආදායම වැඩිවීම මනින අතර සංවර්ධනයට සෞඛ්‍ය, අධ්‍යාපන හා ජීවන තත්ත්වය ඇතුළත් වේ",
        "ආර්ථික වර්ධනය යනු රටේ මුද්‍රණය කරන කඩදාසි මුදල් නෝට්ටු ප්‍රමාණය පමණක් ගණනය කිරීමයි",
        "ආර්ථික සංවර්ධනය මැනීමේදී රෝහල්, පාසල් හා පානීය ජල පහසුකම් කිසිසේත් සලකා නොබලයි",
        "මෙම සංකල්ප දෙක අතර කිසිදු වෙනසක් නොමැති අතර දෙකම භූමි ප්‍රමාණය මැනීමට යොදා ගනී",
        "මානව සංවර්ධන දර්ශකය (HDI) මගින් ආදායමට අමතරව ආයු අපේක්ෂාව හා අධ්‍යාපනයද මනිනු ලැබේ."),
      q(t, "ගොවි හා ධීවර සමුපකාර සමිති කුඩා නිෂ්පාදකයින්ට ආර්ථික ශක්තියක් ලබා දෙන්නේ කෙසේද?",
        "තොග මිලට යෙදවුම් ගෙන අතරමැදියන් නොමැතිව අස්වනු සාධාරණ මිලකට අලෙවි කිරීමට උපකාර කිරීම",
        "කුඩා ගොවීන් අතර තරඟය වැඩි කර සියලු දෙනාගේම අස්වනු මිල ඉතා පහළ මට්ටමකට දැමීම",
        "ගොවීන්ගේ නිෂ්පාදන මහා පරිමාණ විදේශීය සමාගම්වලට නොමිලේ ලබා දීමට කටයුතු සැලසීම",
        "සාමාජිකයන්ට කෘෂි ණය ලබා ගැනීම සම්පූර්ණයෙන් තහනම් කර වගා බිම් අත්හැර දැමීමට සැලැස්වීම",
        "සමුපකාර ක්‍රමය මගින් කුඩා නිෂ්පාදකයින්ගේ කේවල් කිරීමේ ශක්තිය ඉහළ යයි."),
      q(t, "තනි බෝග වගාව (Monoculture) වෙනුවට අතුරු හා බහු බෝග වගාව (Intercropping) සිදු කිරීමේ වාසිය කුමක්ද?",
        "පසෙහි පෝෂක සමබර වී රෝග අඩු වන අතර ගොවියාට වසර පුරා විවිධ ආදායම් ලැබීම",
        "එකම බෝගය පමණක් වැවීමෙන් පසෙහි ඇති සියලු පෝෂ්‍ය පදාර්ථ වසරකින්ම ඉවර වී යාම",
        "පළිබෝධ හානි දස ගුණයකින් ඉහළ ගොස් මුළු ගොවිපළම එකවර විනාශ වී යාමට සැලැස්වීම",
        "එක් කන්නයකදී පමණක් සුළු අස්වැන්නක් ලැබී වසරේ ඉතිරි කාලය පුරාම ආදායම නතර වීම",
        "ශ්‍රී ලංකාවේ පොල් වගාව යට ගම්මිරිස්, කෝපි, කෙසෙල් හා අන්නාසි වගා කිරීම සාර්ථක නිදසුනකි."),
      q(t, "ලෝකයේ මහා පරිමාණ තණබිම් සත්ත්ව පාලනය (Extensive Ranching) ප්‍රධාන වශයෙන් සිදු කරන කලාප මොනවාද?",
        "උතුරු ඇමරිකාවේ බටහිර තැනිතලා, දකුණු ඇමරිකාවේ පැම්පාස් සහ ඕස්ට්‍රේලියාවේ අභ්‍යන්තර තණබිම්",
        "හිමාලය හා ඇල්ප්ස් කඳු වැටිවල සදාකාලික හිමෙන් වැසී පවතින උස් කඳු මුදුන් ප්‍රදේශ",
        "ග්‍රීන්ලන්තයේ හා ඇන්ටාක්ටිකාවේ ඝන අයිස් තට්ටු මත පිහිටි ජනශූන්‍ය ධ්‍රැවීය කලාප",
        "ඉන්දියානු හා අත්ලාන්තික් සාගරයේ කුඩා කොරල්පර දූපත් හා ලවණ මඩ වගුරු ආශ්‍රිත වෙරළ",
        "වර්ෂාපතනය අඩු පුළුල් තෘණ භූමිවල අඩු ශ්‍රමයකින් විශාල ගව හා බැටළු පට්ටි පාලනය කෙරේ."),
      q(t, "ජානමය වශයෙන් වැඩිදියුණු කළ බෝග (GM Crops) භාවිතයේදී ඇති වාසි සහ විවාද මොනවාද?",
        "නියඟයට හා කෘමීන්ට ඔරොත්තු දී අස්වැන්න වැඩි වුවද දේශීය බීජ විවිධත්වයට අවදානම් ඇති වීම",
        "එම බෝගවලට වර්ධනය වීම සඳහා කිසිදු ජලයක් හෝ සූර්යාලෝකයක් අවශ්‍ය නොවී අඳුරේම වැඩීම",
        "සියලුම ජානමය බෝග ප්ලාස්ටික් හා රසායනික තෙල් වලින් පමණක් කම්හල් තුළ නිපදවීම",
        "ඒවා වගා කිරීමෙන් කිසිදු අස්වැන්නක් නොලැබෙන අතර පස සම්පූර්ණයෙන් ගල් බවට පත් වීම",
        "ශ්‍රී ලංකාවේ සුවඳැල් හා කළු හීනැටි වැනි පාරම්පරික වී ප්‍රභේද රැක ගැනීමද ජාන සම්පතට වැදගත් වේ."),
      q(t, "ශ්‍රී ලංකාවේ 'පොල් ත්‍රිකෝණය' (Coconut Triangle) ලෙස හඳුන්වන ප්‍රධාන පොල් වගා කලාපයට අයත් දිස්ත්‍රික්ක තුන මොනවාද?",
        "කුරුණෑගල, පුත්තලම සහ ගම්පහ යන දිස්ත්‍රික්ක (කොළඹ උතුරු ප්‍රදේශයද ඇතුළුව)",
        "මහනුවර, නුවරඑළිය සහ බදුල්ල යන මධ්‍යම කඳුකර දිස්ත්‍රික්ක තුන",
        "යාපනය, මුලතිව් සහ කිලිනොච්චි යන උතුරු පළාතේ වෙරළබඩ දිස්ත්‍රික්ක තුන",
        "අනුරාධපුරය, පොළොන්නරුව සහ වවුනියාව යන උතුරු මැද වියළි දිස්ත්‍රික්ක තුන",
        "දිවයිනේ මුළු පොල් නිෂ්පාදනයෙන් වැඩිම කොටසක් මෙම කලාපයෙන් ලැබෙන අතර ගාල්ල-මාතර-හම්බන්තොට කුඩා පොල් ත්‍රිකෝණය ලෙස හැඳින්වේ."),
      q(t, "ශ්‍රී ලංකාව ලෝක වෙළඳපොළට සපයන 'සත්‍ය සිලෝන් කුරුඳු' (Ceylon Cinnamon) ප්‍රධාන වශයෙන් වගා කෙරෙන දිස්ත්‍රික්ක මොනවාද?",
        "ගාල්ල, මාතර, කළුතර, රත්නපුර සහ හම්බන්තොට යන දකුණු හා නිරිතදිග දිස්ත්‍රික්ක",
        "යාපනය, මන්නාරම සහ මුලතිව් යන වියළි උතුරුදිග වෙරළබඩ දිස්ත්‍රික්ක",
        "අනුරාධපුරය, පොළොන්නරුව සහ ත්‍රිකුණාමලය යන නැගෙනහිර හා උතුරු මැද දිස්ත්‍රික්ක",
        "නුවරඑළිය, බදුල්ල සහ මාතලේ යන අධික උන්නතාංශයක් සහිත උඩරට දිස්ත්‍රික්ක",
        "ලෝකයේ සත්‍ය කුරුඳු සැපයුමෙන් විශාලතම කොටස ශ්‍රී ලංකාවෙන් අපනයනය කෙරේ."),
      q(t, "ශ්‍රී ලංකාවේ සුළු අපනයන කුළුබඩු බෝග (ගම්මිරිස්, කරාබුනැටි, සාදික්කා, එනසාල්) බහුලව වගා කරනු ලබන්නේ කොතැනද?",
        "මහනුවර, මාතලේ, කෑගල්ල හා බදුල්ල දිස්ත්‍රික්කවල සෙවණ සහිත උඩරට ගෙවතුවල",
        "මන්නාරම හා පුත්තලම ප්‍රදේශවල අර්ධ ශුෂ්ක ලවණ වැලි කඳු ආශ්‍රිත වෙරළ තීරවල",
        "හම්බන්තොට හා අලිමංකඩ ප්‍රදේශවල ලුණු ලේවායන් වටා පිහිටි තැනිතලා බිම්වල",
        "යාපනය අර්ධද්වීපයේ හුණුගල් කලපු මායිම්වල පිහිටි ලවණ මඩ වගුරු බිම්වල",
        "මධ්‍යම කඳුකරයේ හා අතරමැදි කලාපයේ බහු-ස්තර ගෙවතු වගා ක්‍රමය මෙම බෝගවලට ඉතා සුදුසුය."),
      q(t, "උතුරු ඇමෙරිකාවේ 'මහා විල් කලාපය' (Great Lakes Region) ඓතිහාසිකව ප්‍රධාන වානේ හා මෝටර් රථ කාර්මික කලාපයක් වූයේ ඇයි?",
        "සුපීරියර් විල අවට යපස්, ඇපලේචියන් ගල් අඟුරු හා මහා විල් ඔස්සේ ලාභදායී ජල ප්‍රවාහනය තිබීම",
        "ප්‍රදේශයේ පවතින අධික ශීතල නිසා කිසිදු බලශක්තියක් නොමැතිව යකඩ ලෝපස් ඉබේ උණු වීම",
        "වෙනත් කිසිදු ඛනිජයක් නොමැතිව ස්වාභාවික වායු ළිං පමණක් එම ප්‍රදේශයේ පිහිටා තිබීම",
        "සියලු වනාන්තර හා කඳු ඉවත් කර තේ හා රබර් වැනි නිවර්තන වැවිලි බෝග වගා කර තිබීම",
        "ඩෙට්‍රොයිට්, චිකාගෝ, පිට්ස්බර්ග් හා ක්ලීව්ලන්ඩ් නගර මෙම කාර්මික කලාපයේ ප්‍රධාන මධ්‍යස්ථාන විය."),
      q(t, "ජපානයේ ප්‍රධානම කාර්මික තීරය වන 'ටෝකයිඩෝ කාර්මික කලාපය' (Tokaido Corridor) පිහිටා ඇත්තේ කුමන භූගෝලීය පිහිටීම ඔස්සේද?",
        "ටෝකියෝ සිට ඔසාකා දක්වා පැසිෆික් වෙරළබඩ තැනිතලා වරායන් හා අධිවේගී දුම්රිය මාර්ගය ඔස්සේ",
        "රට මධ්‍යයේ පිහිටි ජපන් ඇල්ප්ස් කඳු වැටියේ උස් ගිනිකඳු මුදුන් ආශ්‍රිත ප්‍රදේශයේ",
        "උතුරුදිග හොක්කයිඩෝ දූපතේ ශීතල හිම වැසුණු කෘෂිකාර්මික ගම්මාන තුළ පමණක්",
        "ජපන් මුහුද දෙසට වන්නට පිහිටි ජනශූන්‍ය කුඩා පාෂාණමය දූපත් කිහිපයක් මත පමණක්",
        "කඳුකර භූමිය වැඩි ජපානයේ ගොඩකළ වෙරළ තීර හා ගැඹුරු වරායන් කර්මාන්ත ස්ථානගත කිරීමට යොදාගෙන ඇත."),
      q(t, "හොංකොං, සිංගප්පූරුව, දකුණු කොරියාව හා තායිවානය වේගවත් ආර්ථික දියුණුවක් ලැබුවේ කුමන ප්‍රතිපත්තිය නිසාද?",
        "අධ්‍යාපනය හා තාක්ෂණයට ආයෝජනය කරමින් අපනයන-අභිමුඛ කාර්මිකරණය ක්‍රියාත්මක කිරීමෙන්",
        "සියලු විදේශීය වෙළඳ ගනුදෙනු නතර කර රට තුළ හුදකලා යැපුම් කෘෂිකර්මය පමණක් පවත්වා ගැනීමෙන්",
        "ජාත්‍යන්තර නාවික වරායන් හා ගුවන් තොටුපළවල් වසා දමා විදේශ ආයෝජන ප්‍රතික්ෂේප කිරීමෙන්",
        "විශාල ගල් අඟුරු හා බොරතෙල් පතල් පමණක් කැණ අමුද්‍රව්‍ය ලෙස විකුණා ආදායම් ඉපැයීමෙන්",
        "මෙම රටවල් කලාපීය ආර්ථික ඉතිහාසයේ නැගෙනහිර ආසියානු ආර්ථික ව්‍යාඝ්‍රයන් ලෙස හැඳින්වේ."),
      q(t, "පෙට්‍රෝ-රසායනික කර්මාන්තය (Petrochemical Industry) මගින් බොරතෙල් හා ස්වාභාවික වායුවලින් නිපදවන භාණ්ඩ මොනවාද?",
        "ප්ලාස්ටික්, කෘත්‍රිම රෙදිපිළි, රසායනික පොහොර, ඖෂධ, තීන්ත සහ කෘත්‍රිම රබර්",
        "සාම්ප්‍රදායික තේක්ක ලී ගෘහ භාණ්ඩ, මැටි වළං සහ වේවැල් කූඩ වැනි අත්කම් භාණ්ඩ",
        "ස්වාභාවික මී පැණි, පොල් හකුරු, කිතුල් පැණි සහ වියළි පලතුරු වර්ග",
        "රත්නපුර පතල්වලින් ලබාගන්නා ස්වාභාවික නිල් මැණික්, පද්මරාග හා රතු කැට වර්ග",
        "ප්‍රවාහන පිරිවැය අඩු කිරීම සඳහා පෙට්‍රෝ-රසායනික කම්හල් බොහෝ විට තෙල් පිරිපහදු අසල පිහිටුවයි."),
      q(t, "මහාමාර්ග ට්‍රක් රථවලට වඩා දුම්රිය ප්‍රවාහනය ආර්ථික හා පාරිසරිකව වාසිදායක වන්නේ කුමන කාර්යයේදීද?",
        "ගල් අඟුරු, ධාන්‍ය, තෙල් හා බහාලුම් වැනි බර තොග භාණ්ඩ දිගු දුර ගොඩබිම් මාර්ගවල ගෙන යාමේදී",
        "නගරයේ සුපිරි වෙළඳසැලක සිට සෑම පාරිභෝගික නිවසකටම කුඩා පාර්සල් බෙදා හැරීමේදී",
        "කිලෝමීටරයකට වඩා අඩු ඉතා කෙටි දුරක් තුළ දෛනික එළවළු කූඩ කිහිපයක් ප්‍රවාහනය කිරීමේදී",
        "මහාද්වීප දෙකක් අතර පිහිටි ගැඹුරු සාගර තරණය කරමින් භාණ්ඩ හුවමාරු කිරීමේදී",
        "නිවසින් නිවසට පහසුවෙන් ළඟා විය හැකි වීම මහාමාර්ග ප්‍රවාහනයේ ප්‍රධාන වාසියයි."),
      q(t, "භූගෝලීය ප්‍රවාහන මාධ්‍ය අතර නළ මාර්ග (Pipelines) විශේෂයෙන් යොදා ගනු ලබන්නේ කුමක් ප්‍රවාහනය කිරීමටද?",
        "බොරතෙල්, ස්වාභාවික වායු, පිරිපහදු කළ ඉන්ධන සහ ජලය අඛණ්ඩව දිගු දුර ගෙන යාමට",
        "දෛනික රැකියා සඳහා කාර්යාල වෙත ගමන් කරන දහස් ගණන් මගීන් ආරක්ෂිතව ගෙන යාමට",
        "ගල් අඟුරු කුට්ටි, වී ගෝනි, යකඩ පොලු සහ කැපූ දැව කඳන් කර්මාන්තශාලා වෙත යැවීමට",
        "මෝටර් රථ, යන්ත්‍රෝපකරණ සහ විශාල වානේ බහාලුම් පෙට්ටි වරායේ සිට නගරයට ගෙන යාමට",
        "නළ මාර්ග ඉදිකිරීමේ මූලික වියදම වැඩි වුවද කාලගුණික බාධාවකින් තොරව අඩු වියදමින් ක්‍රියාත්මක වේ."),
      q(t, "පිරිවැය අධික වුවද ගුවන් ප්‍රවාහනය (Air Transport) ශ්‍රී ලංකාවේ කුමන අපනයන සඳහා ඉතා වැදගත් වේද?",
        "නැවුම් මසුන්, කැපූ මල්, විසිතුරු පැළ, හදිසි ඇඟලුම් ඇණවුම් හා මැණික් වැනි ඉහළ වටිනාකමැති භාණ්ඩ",
        "ටොන් දහස් ගණනක බරැති සිමෙන්ති කොට්ට, ගඩොල්, කළුගල් සහ ගංගා වැලි තොග ප්‍රවාහනයට",
        "බොරතෙල් බැරල් ලක්ෂ ගණනක් හා ගල් අඟුරු තොග දිගු දුර මහාද්වීප අතර ගෙන යාමට",
        "වරායන්හි ගොඩගැසූ ලුණු ගෝනි හා පොල් ලෙලි කෙඳි අඩු මුදලකට විදේශ වෙළඳපොළට යැවීමට",
        "කටුනායක හා මත්තල ජාත්‍යන්තර ගුවන් තොටුපළ සංචාරකයන් ගෙන ඒමටත් ඉක්මන් භාණ්ඩ ප්‍රවාහනයටත් දායක වේ."),
      q(t, "කොළඹ වරාය දකුණු ආසියාවේ ප්‍රධාන 'ප්‍රති-නැව්ගත කිරීමේ මධ්‍යස්ථානයක්' (Transshipment Hub) ලෙස දියුණු වී ඇත්තේ ඇයි?",
        "ප්‍රධාන නැගෙනහිර–බටහිර සාගර මාර්ගය අසල පිහිටීම නිසා විශාල නැව්වල බහාලුම් කලාපීය වරායන්ට මාරු කිරීමට හැකි වීම",
        "කොළඹ වරාය රට මැද මිරිදිය ගංගාවක ඉහළ නිම්නයේ කඳු අතර ආරක්ෂිතව පිහිටා ඇති නිසා",
        "වෙනත් කිසිදු දකුණු ආසියානු රටක මුහුදු වෙරළ තීරයක් හෝ වරායක් ස්වාභාවිකව පිහිටා නොමැති නිසා",
        "විශාල භාණ්ඩ ප්‍රවාහන නැව්වලට කොළඹ වරායේදී රේගු නීති කිසිවක් නොමැතිව ගමන් කළ හැකි නිසා",
        "කොළඹ දකුණු වරායේ ගැඹුරු පර්යන්ත ලොව විශාලතම බහාලුම් නැව්වලට සේවා සැපයීමේ හැකියාවෙන් යුක්තය."),
      q(t, "සංචාරක ආදායම ප්‍රදේශයේ සාමාන්‍ය ජනතාවට ලැබෙන 'ප්‍රජා පාදක සංචාරක ව්‍යාපාරය' ක්‍රියාත්මක වන්නේ කෙසේද?",
        "ග්‍රාමීය නිවාස නවාතැන්, දේශීය ආහාර, අත්කම් හා ප්‍රාදේශීය මගපෙන්වීම් හරහා ගැමි ආර්ථිකය ශක්තිමත් කිරීම",
        "ගම්වැසියන් සියලු දෙනාම ප්‍රදේශයෙන් ඉවත් කර විදේශීය සමාගම් හෝටල් පමණක් ඉදිකර පවත්වාගෙන යාම",
        "සංචාරක කලාපවල ප්ලාස්ටික් අපද්‍රව්‍ය ගොඩගසා ස්වාභාවික වනාන්තර හා දිය ඇලි විනාශ කර දැමීම",
        "දේශීය සංස්කෘතිය හා සාම්ප්‍රදායික ජීවන රටාව සම්පූර්ණයෙන් තහනම් කර නාගරික සමාජශාලා පමණක් පිහිටුවීම",
        "මීමුරේ, සීගිරිය හා හබරණ අවට ග්‍රාමීය සංචාරක ආකෘති ප්‍රජා ආදායම වැඩි කිරීමට උපකාරී වේ."),
      q(t, "ජාත්‍යන්තර වෙළඳපොළේ 'සාධාරණ වෙළඳාම' (Fair Trade) ලේබලය කුඩා ගොවීන්ට උපකාරී වන්නේ කෙසේද?",
        "නිෂ්පාදන සඳහා ස්ථාවර අවම මිලක්, ආරක්ෂිත සේවා කොන්දේසි සහ ප්‍රජා සංවර්ධන ප්‍රසාද මුදලක් සහතික කිරීම",
        "ගොවීන්ගේ අස්වැන්නට කිසිදු මුදලක් නොගෙවා අතරමැදියන්ට සියලු ලාභය ලබා ගැනීමට ඉඩ සලසා දීම",
        "කෘෂි භාණ්ඩවල අලෙවි මිල ශූන්‍ය මට්ටමට පහත දමා සියලු වතු වගාවන් වසා දැමීමට සැලැස්වීම",
        "ගොවිපළවල ළමා ශ්‍රමය බහුලව භාවිත කිරීමටත් පරිසර නීති නොසලකා හැරීමටත් අවසර ලබා දීම",
        "සාධාරණ වෙළඳ සහතිකය සහිත තේ, කෝපි හා කොකෝවා සඳහා සංවර්ධිත රටවල ඉහළ ඉල්ලුමක් පවතී."),
      q(t, "ලන්ඩන්, නිව්යෝක් සහ ටෝකියෝ වැනි ප්‍රධාන ජාත්‍යන්තර මූල්‍ය මධ්‍යස්ථාන වෙනස් වේලා කලාප තුනක පිහිටීමේ ආර්ථික වැදගත්කම කුමක්ද?",
        "එක් නගරයක වෙළඳපොළ වැසෙන විට අනෙක විවෘත වීම නිසා පැය 24 පුරා ගනුදෙනු සිදු වීම",
        "ලෝකයේ සියලුම රටවල එකම වේලා කලාපයක් පවතින බැවින් සියලු බැංකු එකවර වසා තැබීමට හැකි වීම",
        "රාත්‍රී කාලයේදී ජාත්‍යන්තර මුදල් හුවමාරු හා කොටස් වෙළඳපොළ කටයුතු සම්පූර්ණයෙන්ම අත්හිටුවීම",
        "එම නගර තුනම කෘෂිකාර්මික බෝග වගාවෙන් පමණක් ජාතික ආදායම උපයා ගැනීමට කටයුතු කිරීම",
        "මූල්‍ය හා බැංකු සේවා ආර්ථිකයේ තෘතීයික අංශයට අයත් ප්‍රධාන සේවා කර්මාන්තයක් වේ."),
      q(t, "නිවර්තන මෝසම් කලාපයේ වී වගාවත් සෞම්‍ය තෘණ භූමිවල තිරිඟු වගාවත් ප්‍රමුඛ වීමට බලපෑ දේශගුණික හේතුව කුමක්ද?",
        "වී වගාවට ඉහළ උෂ්ණත්වය හා වැඩි ජලයද තිරිඟු වගාවට සිසිල් උෂ්ණත්වය හා මධ්‍යස්ථ වැසිද අවශ්‍ය වීම",
        "තිරිඟු වගාව සම්පූර්ණයෙන්ම ගැඹුරු ජලය යට වැඩෙන අතර වී වගාව වියළි වැලි කඳු මත වැඩීම",
        "වී වගාව හිම පතනය සහිත ධ්‍රැවීය ප්‍රදේශවලත් තිරිඟු වගාව සමක වැසි වනාන්තරවලත් පමණක් වැවීම",
        "බෝග වගාව සඳහා කිසිදු රටක උෂ්ණත්වය හෝ වාර්ෂික වර්ෂාපතනය බලපෑමක් සිදු නොකරන බැවින්",
        "බඩ ඉරිඟු වී හා තිරිඟු අතර අතරමැදි දේශගුණික තත්ත්වවලදී මිනිස් හා සත්ත්ව ආහාර ලෙස වගා කෙරේ."),
      q(t, "ශ්‍රී ලංකාව යුරෝපා සංගමය වැනි විදේශ වෙළඳපොළවලට මත්ස්‍ය නිෂ්පාදන අපනයනය කිරීමේදී අනුගමනය කළ යුතු ප්‍රධාන නියාමන මොනවාද?",
        "නීති විරෝධී මසුන් ඇල්ලීම වැළැක්වීම, යාත්‍රා චන්ද්‍රිකා නිරීක්ෂණය සහ සෞඛ්‍යාරක්ෂිත සීතල දාම ප්‍රමිතීන්",
        "අල්ලා ගන්නා මසුන් ශීතකරණවල නොදමා දින ගණනක් හිරු එළියේ වියළා අමුවෙන් නැව්ගත කිරීම",
        "ධීවර බලපත්‍ර කිසිවක් නොමැතිව විදේශීය මුහුදු සීමාවලට ඇතුළු වී මසුන් අල්ලා අපනයනය කිරීම",
        "මසුන්ගේ පැහැය වෙනස් කිරීම සඳහා අහිතකර කෘත්‍රිම රසායනික වර්ණක හා කල් තබා ගැනීමේ ද්‍රව්‍ය යෙදීම",
        "ජාත්‍යන්තර ධීවර ප්‍රමිතීන් රැකීම නිසා ශ්‍රී ලංකාවේ මත්ස්‍ය අපනයන ආදායම ස්ථාවරව පවත්වා ගත හැකිය."),
      q(t, "කෘෂි හා ධීවර නිෂ්පාදන බෙදා හැරීමේදී 'සීතල දාම ප්‍රවාහනය' (Cold Chain) භාවිත කිරීම වැදගත් වන්නේ ඇයි?",
        "අස්වැන්න නෙළූ තැන සිට වෙළඳපොළ දක්වා නියමිත සිසිල් උෂ්ණත්වයේ තබා පසු-අස්වනු නාස්තිය අවම කිරීම",
        "එළවළු හා පලතුරු ප්‍රවාහනයේදී වැඩි වේගයකින් ඉදී යාම සඳහා ට්‍රක් රථ ඇතුළත උණුසුම් කර තැබීම",
        "ආහාර ද්‍රව්‍යවල බර වැඩි කර පාරිභෝගිකයන්ට වැඩි මිලකට අලෙවි කිරීමේ වෙළඳ උපක්‍රමයක් ලෙස",
        "නැවුම් මසුන් හා කිරි නිෂ්පාදන සම්පූර්ණයෙන් වියළා කුඩු බවට පත් කර ප්‍රවාහනය පහසු කිරීම",
        "ශීතාගාර පහසුකම් හා ප්ලාස්ටික් කූඩ භාවිතය මගින් ආහාර නරක් වීම සැලකිය යුතු ලෙස අඩු කළ හැකිය."),
      q(t, "කර්මාන්තශාලා මගින් සිදුවන පරිසර දූෂණය අවම කිරීමට 'පිරිසිදු නිෂ්පාදන ක්‍රම' (Cleaner Production) දායක වන්නේ කෙසේද?",
        "නිෂ්පාදන ආරම්භයේදීම අඩු ජලය, අඩු ශක්තිය හා විෂ රහිත ද්‍රව්‍ය යොදා අපද්‍රව්‍ය ජනනය අවම කිරීම",
        "කර්මාන්තශාලාවලින් පිටවන රසායනික අපජලය පිරිපහදු නොකර රාත්‍රී කාලයේ ගංගාවලට මුදා හැරීම",
        "දුම් නළවල උස පමණක් වැඩි කර වායු දූෂක ද්‍රව්‍ය දිගටම වායුගෝලයට නිකුත් කරමින් පවත්වාගෙන යාම",
        "නිෂ්පාදන ක්‍රියාවලියේදී භාවිත කරන රසායනික සායම් හා ජල ප්‍රමාණය දෙගුණයකින් ඉහළ දැමීම",
        "අපද්‍රව්‍ය අවම කිරීම මගින් පරිසරය ආරක්ෂා වන අතරම කර්මාන්තශාලාවේ නිෂ්පාදන වියදමද අඩු වේ."),
      q(t, "රජයන් විසින් ගොවීන් සඳහා වී හා අනෙකුත් බෝගවලට 'සහතික මිලක්' (Guaranteed Price) නියම කිරීමේ අරමුණ කුමක්ද?",
        "අස්වනු නෙළන කාලයේ මිල පහත වැටීමෙන් ගොවීන් රැකගෙන ජාතික ආහාර නිෂ්පාදනය ස්ථාවර කිරීම",
        "සියලුම ගොවීන් කෘෂිකර්මයෙන් ඉවත් කර නාගරික ඇඟලුම් කර්මාන්තශාලා රැකියා වෙත යොමු කිරීම",
        "වෙළඳපොළේ ආහාර ද්‍රව්‍යවල මිල අසීමිත ලෙස ඉහළ දමා පාරිභෝගිකයන්ට ආහාර මිලදී ගැනීම අසීරු කිරීම",
        "දේශීය ගොවිතැන අධෛර්යමත් කර විදේශ රටවලින් සහල් හා එළවළු ආනයනය කිරීම වැඩි කර ගැනීම",
        "සහතික මිල ක්‍රමය මගින් ගොවියාට නිෂ්පාදන වියදම පියවා ගෙන සාධාරණ ලාභයක් ලබා ගැනීමට හැකි වේ."),
      q(t, "සංස්කෘතික හා නිර්මාණශීලී කර්මාන්ත (සිනමාව, සංගීතය, ඩිජිටල් නිර්මාණ හා විලාසිතා) නූතන ආර්ථිකයේ වැදගත් වන්නේ ඇයි?",
        "ඩිජිටල් මාධ්‍ය ඔස්සේ ගෝලීය පාරිභෝගිකයන්ට නිර්මාණ සපයා ඉහළ සේවා ආදායම් හා රැකියා බිහි කිරීම",
        "භෞතික අමුද්‍රව්‍ය ලෙස යකඩ ලෝපස් හා ගල් අඟුරු අතිවිශාල ප්‍රමාණයක් භාවිත කර පරිසරය වෙනස් කිරීම",
        "සාම්ප්‍රදායික කලා හා සංස්කෘතික උරුමයන් සම්පූර්ණයෙන්ම ඉවත් කර කාර්මික කලාප පමණක් ඉදි කිරීම",
        "මෙම ක්ෂේත්‍රය සඳහා කිසිදු මානව නිර්මාණශීලීත්වයක් හෝ තාක්ෂණික දැනුමක් අවශ්‍ය නොවී පැවතීම",
        "විනෝදාස්වාද හා මාධ්‍ය සේවා කර්මාන්ත වර්තමානයේ විශාල විදේශ විනිමය උපයන සේවා අංශයකි."),
      q(t, "චීනයේ ෂෙන්ෂෙන් වැනි 'විශේෂ ආර්ථික කලාප' (SEZs) කෙටි කලකින් විශාල කාර්මික මධ්‍යස්ථාන බවට පත්වූයේ කෙසේද?",
        "බදු සහන, පහසු රේගු නීති හා නවීන යටිතල පහසුකම් සපයා විදේශ ආයෝජන හා තාක්ෂණය ආකර්ෂණය කිරීමෙන්",
        "එම කලාප තුළ කෘෂිකර්මය හා ධීවර කර්මාන්තය පමණක් නීතිගත කර කර්මාන්තශාලා ඉදි කිරීම තහනම් කිරීමෙන්",
        "විදේශීය සමාගම්වලට හා ආයෝජකයන්ට ඇතුළු වීම සම්පූර්ණයෙන් තහනම් කර හුදකලා ආර්ථිකයක් පවත්වා ගැනීමෙන්",
        "නාවික වරායන් හා දුම්රිය මාර්ග සියල්ල වසා දමා දේශීය ගමනාගමනය පමණක් සීමා කර තැබීමෙන්",
        "විශේෂ ආර්ථික කලාප ආසියානු රටවල කාර්මිකරණය හා අපනයන ආදායම වේගවත් කිරීමට ඉවහල් විය."),
      q(t, "සිලෝන් තේ හා සිලෝන් කුරුඳු සඳහා 'භූගෝලීය දර්ශක' (Geographical Indications) ලබා ගැනීම අපනයනකරුවන්ට වැදගත් වන්නේ ඇයි?",
        "නිශ්චිත ප්‍රදේශයේ පස හා දේශගුණය නිසා ලැබෙන ගුණාත්මකභාවය රැක ගනිමින් ව්‍යාජ අනුකරණ වැළැක්වීම",
        "එම නිෂ්පාදනවල ගුණාත්මකභාවය අඩු කර ලෝක වෙළඳපොළේ අඩුම මිලට භාණ්ඩ අලෙවි කිරීමට හැකි වීම",
        "ලෝකයේ ඕනෑම රටක නිපදවන බාල භාණ්ඩ සඳහා ශ්‍රී ලංකාවේ නාමය නිදහසේ භාවිත කිරීමට ඉඩ සලසා දීම",
        "විදේශීය රටවලට කුළුබඩු හා තේ අපනයනය කිරීම නීත්‍යානුකූලව සම්පූර්ණයෙන්ම නතර කර දැමීම",
        "භූගෝලීය දර්ශක මගින් දේශීය නිෂ්පාදනවල අනන්‍යතාව සුරැකී ඉහළ වෙළඳපොළ වටිනාකමක් හිමි වේ."),
      q(t, "මෝටර් රථ එකලස් කිරීමේ කර්මාන්තශාලා අවට උප-කොටස් නිපදවන කුඩා කම්හල් පිහිටුවීමේ ප්‍රධාන වාසිය කුමක්ද?",
        "ටයර්, වීදුරු, බැටරි හා ආසන වැනි කොටස් ප්‍රමාදයකින් තොරව අඩු ප්‍රවාහන වියදමින් සපයා ගැනීම",
        "වෙනත් ප්‍රදේශවල වාහන අමතර කොටස් නිෂ්පාදනය කිරීම නීතියෙන් සම්පූර්ණයෙන් තහනම් කර ඇති බැවින්",
        "සියලු අමතර කොටස් ගුවන් යානා මගින් දිනපතා විදේශ රටවලින් ගෙන්වා ගැනීමට වඩා පහසු නොවන බැවින්",
        "කම්හල් අවට සේවකයන් සංඛ්‍යාව අඩු කර සියලුම යන්ත්‍රසූත්‍ර නගරයෙන් පිටතට ඉවත් කර ගැනීමට",
        "නවීන කර්මාන්ත එකිනෙකා මත යැපෙන සැපයුම් ජාල හරහා කාර්යක්ෂමතාව ඉහළ නංවා ගනී."),
      q(t, "ශ්‍රී ලංකාවේ එප්පාවල පොස්පේට්, බෝගල මිනිරන් හා පුල්මුඩේ ඛනිජ වැලි ආශ්‍රිත කර්මාන්ත දියුණු කිරීමේදී ප්‍රමුඛ විය යුත්තේ කුමක්ද?",
        "අමු ඛනිජ ලෙස අපනයනය නොකර දේශීයවම පොහොර, බැටරි හා කාර්මික ද්‍රව්‍ය ලෙස අගය එකතු කිරීම",
        "පොළොව යට ඇති සියලුම ඛනිජ සම්පත් ඉවතට නොගෙන භාවිතයෙන් තොරව සම්පූර්ණයෙන් වසා දැමීම",
        "එම ඛනිජ නිධි සියල්ල පිරිපහදු නොකර අඩුම මිලට අමු පස් ලෙස විදේශ වරායන් වෙත පටවා යැවීම",
        "රට තුළ කිසිදු ඛනිජ පර්යේෂණ ආයතනයක් හෝ කර්මාන්තශාලාවක් ඉදි නොකර ආනයන මත පමණක් යැපීම",
        "උසස් තාක්ෂණය හා ප්‍රාග්ධනය යෙදවීමෙන් දේශීය ඛනිජ සම්පත්වලින් කිහිප ගුණයක විදේශ විනිමය ඉපැයිය හැකිය."),
      q(t, "කෘෂිකාර්මික කටයුතුවලදී ගොවීන් සඳහා කෘෂි රක්ෂණ ක්‍රම (Crop Insurance) හඳුන්වා දීමෙන් ලැබෙන ආර්ථික ආරක්ෂාව කුමක්ද?",
        "නියඟය හෝ ගංවතුර නිසා වගාව විනාශ වූ විට වන්දි ලැබී ඊළඟ කන්නයේ යළි වගා කිරීමට හැකි වීම",
        "රක්ෂණ ක්‍රම මගින් ප්‍රදේශයේ ඇති වන අධික වර්ෂාපතනය හා සුළි සුළං ස්වාභාවිකව නතර කර දැමීම",
        "ගොවීන් කෘෂිකර්මාන්තයෙන් සම්පූර්ණයෙන් ඉවත් කර කුඹුරු ඉඩම් වෙළඳ සංකීර්ණ සඳහා විකුණා දැමීම",
        "සෑම කන්නයකම ලැබෙන වී හා එළවළු අස්වැන්න ප්‍රමාණය කෘත්‍රිමව අඩු කර මිල පහත හෙළීම",
        "කෘෂි රක්ෂණය කාලගුණික ආපදා හමුවේ ගොවීන් ණය උගුලට හසු වීම වළක්වා ගැනීමට උපකාරී වේ."),
      q(t, "ගෝලීය ආහාර නාස්තිය (Food Loss and Waste) ලෝක ආර්ථිකයට හා පරිසරයට බරපතල ගැටලුවක් වන්නේ ඇයි?",
        "නිපදවන ආහාරවලින් විශාල කොටසක් අපතේ යද්දී කුසගින්න පැවතීමත් කුණු වන ආහාර හරිතාගාර වායු පිට කිරීමත්",
        "අපතේ යන ආහාර ප්‍රමාණය වැඩි වන තරමට ලෝකයේ සියලු දෙනාගේම පෝෂණ මට්ටම ඉහළ යන බැවින්",
        "වගා කරන ධාන්‍ය හා එළවළු ඉවත දැමූ විට කිසිදු පිරිවැයකින් තොරව ඉබේම නැවත පැළ වන බැවින්",
        "ආහාර නාස්තිය නිසා ගොවීන්ට භාවිත කළ ජලය, පොහොර හා ශ්‍රමය සම්පූර්ණයෙන්ම ආපසු ලැබෙන බැවින්",
        "සුරක්ෂිත ගබඩා පහසුකම් හා වගකීම්සහගත පරිභෝජන රටා මගින් ආහාර නාස්තිය අවම කළ හැකිය."),
      q(t, "නේපාලය, භූතානය, ලාවෝසය හා ස්විට්සර්ලන්තය වැනි මුහුදු වෙරළක් නොමැති රටවල් (Landlocked Countries) මුහුණ දෙන ප්‍රධාන වෙළඳ ගැටලුව කුමක්ද?",
        "සෘජු මුහුදු වරායන් නොමැති වීම නිසා අසල්වැසි රටවල වරායන් මත යැපී ප්‍රවාහන පිරිවැය ඉහළ යාම",
        "තම රට තුළ කිසිදු ගොඩබිම් මාර්ගයක් හෝ ගංගාවක් නොමැති වීම නිසා අභ්‍යන්තර වෙළඳාම නොතිබීම",
        "වෙරළ ඛාදනය හා සුනාමි රළ පහරවල් නිරන්තරයෙන් ඇති වී වගා බිම් සම්පූර්ණයෙන් විනාශ වී යාම",
        "සාගර මත්ස්‍ය සම්පත අධික වීම නිසා ගොවිතැන් කිරීමට කිසිදු ඉඩමක් රට තුළ ඉතිරි නොවීම",
        "දියුණු දුම්රිය හා අභ්‍යන්තර ජල මාර්ග හරහා මෙම රටවල් අන්තර්ජාතික වෙළඳාම සමඟ සම්බන්ධ වේ."),
      q(t, "ශ්‍රී ලංකාවේ උක් වගාව (සෙවණගල, පැල්වත්ත) හා රබර් වගාව පිහිටා ඇති දේශගුණික කලාප වෙනස් වන්නේ කෙසේද?",
        "රබර් තෙත් කලාපයේ වැඩෙන අතර උක් වගාවට වර්ධනයට තෙතමනයත් සීනි වැඩි වීමට වියළි අස්වනු සමයකුත් අවශ්‍ය වේ",
        "රබර් හා උක් යන බෝග දෙකම වර්ෂාපතනය අඩු යාපනය හා මන්නාරම වියළි වැලි කඳු මත පමණක් වගා කෙරේ",
        "උක් වගාව මධ්‍යම කඳුකරයේ අධික ශීතල කඳු මුදුන්වලත් රබර් වගාව ලුණු කලපු අසලත් පමණක් සිදු වේ",
        "දෙකම ජලය යට වැඩෙන බෝග වන බැවින් කළුතර හා කෑගල්ල දිස්ත්‍රික්කවල කුඹුරු ඉඩම්වල පමණක් වගා කෙරේ",
        "කෑගල්ල හා කළුතර ප්‍රධාන රබර් දිස්ත්‍රික්ක වන අතර මොණරාගල හා අම්පාර ප්‍රධාන උක් වගා කලාප වේ."),
      q(t, "සීතාවක, පල්ලෙකැලේ, හම්බන්තොට හා ත්‍රිකුණාමලය වැනි ප්‍රදේශවල නව කර්මාන්ත පුර පිහිටුවීමේ ප්‍රධාන අරමුණ කුමක්ද?",
        "කර්මාන්ත කොළඹට පමණක් සීමා නොකර ප්‍රාදේශීය රැකියා හා සමතුලිත ආර්ථික වර්ධනය ඇති කිරීම",
        "කොළඹ නගරයේ පවතින මාර්ග තදබදය හා ජනගහන ඝනත්වය තවදුරටත් ඉහළ නැංවීමට කටයුතු කිරීම",
        "ග්‍රාමීය ප්‍රදේශවල සිටින තරුණ පිරිසගේ රැකියා අවස්ථා නතර කර කෘෂිකර්මය පමණක් ඉතිරි කිරීම",
        "දිවයිනේ සියලුම වරායන් හා මහාමාර්ග භාවිතයෙන් ඉවත් කර කර්මාන්ත අපනයන සම්පූර්ණයෙන් නැවැත්වීම",
        "ප්‍රාදේශීය කර්මාන්ත සංවර්ධනය මගින් නාගරික හා ග්‍රාමීය ආදායම් විෂමතාව අවම කර ගත හැකිය."),
      q(t, "ග්‍රාමීය සංවර්ධන බැංකු හා සමුපකාර ණය ක්‍රම දුරස්ථ ගම්මානවල ගොවීන්ට හා සුළු ව්‍යාපාරිකයන්ට වැදගත් වන්නේ ඇයි?",
        "සාධාරණ පොලියකට කෘෂි ණය, ඉතිරි කිරීමේ පහසුකම් හා රක්ෂණ සේවා පහසුවෙන් ලබා ගත හැකි වීම",
        "ගොවීන්ගෙන් අධික පොලී අය කර ගමේ සියලුම වගා ඉඩම් බැංකු සතු කර ගැනීමේ අරමුණ ඇති බැවින්",
        "ග්‍රාමීය ජනතාවට මුදල් ඉතිරි කිරීම තහනම් කර නගරයේ පෞද්ගලික ව්‍යාපාරවලට පමණක් ණය දෙන බැවින්",
        "බැංකු සේවා ලබා ගැනීම සඳහා ගොවීන්ට සැමවිටම කොළඹ අගනුවරට ගමන් කිරීමට සිදුවන බැවින්",
        "පහසු මූල්‍ය ප්‍රවේශය ග්‍රාමීය කුඩා ව්‍යවසායන් ආරම්භ කිරීමට හා දිළිඳුකම අඩු කිරීමට උපකාරී වේ."),
      q(t, "ඇලුමිනියම් උණු කිරීමේ කර්මාන්තශාලා බොහෝ විට නෝර්වේ හා කැනඩාව වැනි ජල විදුලිය බහුල රටවල පිහිටුවන්නේ ඇයි?",
        "බොක්සයිට් වලින් ඇලුමිනියම් වෙන් කිරීමට අතිවිශාල ලාභදායී විදුලි බලයක් අත්‍යවශ්‍ය වන බැවින්",
        "ඇලුමිනියම් නිෂ්පාදනය සඳහා ධ්‍රැවීය කලාපයේ අධික හිම හා අයිස් කැට අමුද්‍රව්‍ය ලෙස යොදා ගන්නා බැවින්",
        "මෙම කර්මාන්තශාලා ක්‍රියාත්මක කිරීමට කිසිදු විදුලි බලයක් හෝ තාප ශක්තියක් අවශ්‍ය නොවන බැවින්",
        "ලෝකයේ සියලුම බොක්සයිට් පතල් ඇත්තේ උතුරු යුරෝපයේ අයිස් කඳු මුදුන්වල පමණක් වන බැවින්",
        "බලශක්ති පිරිවැය අධික කර්මාන්ත බොහෝ විට ලාභදායී බලශක්ති ප්‍රභවයන් අසල ස්ථානගත කෙරේ."),
      q(t, "ඉන්දියාව, චීනය හා ඇමෙරිකා එක්සත් ජනපදය වැනි රටවල කපු වගාව සාර්ථක වීමට බලපාන දේශගුණික සාධක මොනවාද?",
        "වර්ධන සමයේ ප්‍රමාණවත් තෙතමනය හා උණුසුමත්, කපු නෙළන කාලයේදී වියළි හා හිරු එළිය සහිත කාලගුණයත්",
        "වසර පුරාම කිසිදු වෙනසකින් තොරව පවතින අධික හිම පතනය සහ ඍණ උෂ්ණත්වය සහිත කාලගුණය",
        "කපු කරල් විවෘත වන අවස්ථාවේදී දිනපතා ඇද හැලෙන ධාරානිපාත මෝසම් වැසි හා ගංවතුර තත්ත්වය",
        "වගුරු බිම් තුළ ජලය යට පමණක් වැඩෙන මුල් පද්ධතියක් හා සෙවණ සහිත ඝන වනාන්තර පරිසරය",
        "අස්වනු නෙළන කාලයේ වැසි ඇති වුවහොත් කපු කෙඳිවල පැහැය හා ගුණාත්මකභාවය නරක් වේ."),
      q(t, "ලෝක ජූට් (Jute) නිෂ්පාදනයේදී බංග්ලාදේශය හා ඉන්දියාවේ බටහිර බෙංගාලය ප්‍රමුඛ වීමට හේතුව කුමක්ද?",
        "උණුසුම් තෙත් මෝසම් දේශගුණය, සාරවත් ගංගා රොන්මඩ පස හා කෙඳි පොඟවා ගැනීමට බහුල ජලය තිබීම",
        "වසර පුරා පවතින වියළි වැලි කාන්තාර පරිසරය හා කිසිදු ගංගා ජලයක් නොමැති වීම",
        "සාගර මට්ටමෙන් මීටර් හාරදහසකට වඩා උස් හිම වැසුණු කඳු බෑවුම්වල පමණක් මෙම ශාකය වැවීම",
        "ජූට් කෙඳි වෙන් කිරීම සඳහා රසායනික තෙල් නිධි සහ ගල් අඟුරු පතල් විශාල වශයෙන් පැවතීම",
        "පරිසර හිතකාමී ගෝනි, බෑග් හා ලණු නිෂ්පාදනය සඳහා ජූට් 'රන් කෙඳි' ලෙසද හඳුන්වයි."),
      q(t, "ලෝක කෝපි වගාවේ ප්‍රධාන ප්‍රභේද වන 'අරාබිකා' හා 'රොබස්ටා' වගා කරන භූගෝලීය පරිසරයන් වෙනස් වන්නේ කෙසේද?",
        "අරාබිකා සිසිල් නිවර්තන කඳුකර බෑවුම්වල වැඩෙන අතර රොබස්ටා උණුසුම් පහත් බිම්වල රෝගවලට ඔරොත්තු දී වැඩේ",
        "රොබස්ටා ශාකය ධ්‍රැවීය අයිස් තට්ටු මත වැඩෙන අතර අරාබිකා ශාකය සමුද්‍ර පතුලේ ලවණ ජලයේ වැඩේ",
        "කෝපි ප්‍රභේද දෙකම සමාන වන අතර ඒවා වගා කිරීම සඳහා හිම කාලගුණය හා වැලි කාන්තාර අවශ්‍ය වේ",
        "අරාබිකා කෝපි වී කුඹුරු මෙන් ගැඹුරු මඩ ජලයේ වගා කරන අතර රොබස්ටා කොරල්පර මත වගා කෙරේ",
        "බ්‍රසීලය, වියට්නාමය, කොලොම්බියාව හා ඉතියෝපියාව ලොව ප්‍රධාන කෝපි නිපදවන රටවල් වේ."),
      q(t, "චොකලට් නිෂ්පාදනයට අවශ්‍ය කොකෝවා වගාව අයිවරි කෝස්ට් හා ඝානාව වැනි බටහිර අප්‍රිකානු රටවල බහුල වී ඇත්තේ ඇයි?",
        "සමකාසන්න අධික උෂ්ණත්වය, වසර පුරා ඉහළ ආර්ද්‍රතාව, සෙවණ සහිත පරිසරය සහ ගැඹුරු පස පැවතීම",
        "අධික ශීතල හිම කාලගුණය සහ වසරේ මාස හයක්ම පවතින ඍණ උෂ්ණත්ව තත්ත්වයන් පැවතීම",
        "සහරා කාන්තාරයේ වියළි වැලි කඳු මත ජලය කිසිවක් නොමැතිව මෙම ශාකය ස්වාභාවිකව වැඩෙන බැවින්",
        "මීටර් පන්දහසකට වඩා උස් හිමාලයානු කඳු මුදුන්වල පවතින සුළං සහිත දේශගුණය හිතකර බැවින්",
        "අප්‍රිකාවෙන් අපනයනය කෙරෙන කොකෝවා ඇට යුරෝපයේ හා උතුරු ඇමෙරිකාවේ චොකලට් බවට සැකසේ."),
      q(t, "ඇමෙරිකා එක්සත් ජනපදයේ මැද-බටහිර තැනිතලාව (Corn Belt) බඩ ඉරිඟු හා සෝයා බෝංචි නිෂ්පාදනයේදී වැදගත් වන්නේ ඇයි?",
        "මහා පරිමාණ යාන්ත්‍රික වගාවෙන් මිනිස් ආහාර, සත්ත්ව ආහාර හා ජෛව ඉන්ධන සඳහා විශාල සැපයුමක් ලබා දීම",
        "මෙම බෝග වර්ග දෙක කෘත්‍රිම මල් සැරසිලි හා කඩදාසි නිෂ්පාදනය සඳහා පමණක් ලොව පුරා භාවිත කිරීම",
        "කිසිදු ගොවිපළ යන්ත්‍රයක් භාවිත නොකර කුඩා ගෙවතුවල අතින් පමණක් වගා කර දේශීයව පරිභෝජනය කිරීම",
        "සෝයා බෝංචි හා බඩ ඉරිඟු මුහුදු පැළෑටි විශේෂයක් ලෙස වෙරළ තීරයේ ලවණ ජලයේ වගා කර ගැනීම",
        "සාරවත් තැනිතලා පස හා ග්‍රීෂ්ම ඍතු වැසි මෙම වාණිජ ධාන්‍ය තීරයේ අස්වැන්න ඉහළ නැංවීමට උපකාරී වේ."),
      q(t, "ජර්මනියේ රූර් නිම්නය (Ruhr Valley) යුරෝපයේ ප්‍රධාන සාම්ප්‍රදායික බර කාර්මික කලාපයක් ලෙස දියුණු වූයේ කෙසේද?",
        "උසස් ගල් අඟුරු නිධිත් රයින් ගංගාව ඔස්සේ යපස් හා භාණ්ඩ ප්‍රවාහනය කිරීමේ පහසුවත් එකවර තිබීම",
        "එම නිම්නයේ ලෝකයේ විශාලතම රන්, දියමන්ති සහ නිල් මැණික් පතල් පමණක් ස්වාභාවිකව පිහිටා තිබීම",
        "වසර පුරා පවතින නිවර්තන දේශගුණය නිසා තේ, රබර් හා පොල් වැවිලි කර්මාන්ත එහි දියුණු වී තිබීම",
        "කාන්තාර වැලි තට්ටු මත සූර්ය බලාගාර පමණක් ඉදි කර වෙනත් කිසිදු කර්මාන්තයක් නොපැවතීම",
        "පසුකාලීනව ගල් අඟුරු පරිභෝජනය අඩු වූ විට රූර් කලාපය නවීන ඉංජිනේරු හා තාක්ෂණික කලාපයක් බවට පත් විය."),
      q(t, "ඉන්දියාවේ චෝටා නාග්පූර් සානුව 'ඉන්දියාවේ රූර් කලාපය' ලෙස හැඳින්වීමට බලපෑ ප්‍රධාන භූගෝලීය සාධකය කුමක්ද?",
        "ගල් අඟුරු හා යකඩ ලෝපස් නිධි ආසන්නව පිහිටීම නිසා යකඩ හා වානේ කම්හල් එහි සංකේන්ද්‍රණය වීම",
        "එම කලාපය සම්පූර්ණයෙන්ම කපු රෙදිපිළි අලෙවි කරන වෙරළබඩ සංචාරක නගර කිහිපයකින් සමන්විත වීම",
        "ඉන්දියානු සාගරයේ ගැඹුරු ධීවර වරායන් හා නැව් තටාකාංගණ පමණක් එම සානුව මත පිහිටා තිබීම",
        "හිමාලය කඳු වැටියේ සදාකාලික හිම කඳු ආශ්‍රිත ශීතල සංචාරක හෝටල් පමණක් එහි ව්‍යාප්ත වී තිබීම",
        "ජම්ෂෙඩ්පූර්, බොකාරෝ හා රූර්කෙලා යන ප්‍රධාන වානේ නගර මෙම ඛනිජ සම්පන්න සානුවේ පිහිටා ඇත."),
      q(t, "ඉන්දියාවේ මුම්බායි-පූනේ කාර්මික කලාපය රෙදිපිළි, ඖෂධ හා තොරතුරු තාක්ෂණ මධ්‍යස්ථානයක් ලෙස වර්ධනය වූයේ ඇයි?",
        "ඩෙකෑන් කළු කපු පස, මුම්බායි වරාය, බටහිර ඝාට් ජල විදුලිය, ප්‍රාග්ධනය හා පූනේ පුහුණු ශ්‍රමය නිසා",
        "ප්‍රදේශයේ පවතින වියළි කාන්තාර පරිසරය සහ කිසිදු මාර්ග හෝ දුම්රිය ජාලයක් නොමැති වීම නිසා",
        "වසර පුරාම පවතින ශීතල හිම කාලගුණය නිසා ලොම් රෙදි හා හිම ක්‍රීඩා උපකරණ පමණක් සෑදීම නිසා",
        "ගල් අඟුරු පතල් පමණක් පැවතී වෙනත් කිසිදු බලශක්ති ප්‍රභවයක් හෝ අධ්‍යාපන ආයතනයක් නොතිබීම නිසා",
        "වෙරළබඩ වාණිජ වරාය අභ්‍යන්තර අධ්‍යාපන නගරය සමඟ අධිවේගී මාර්ගයෙන් සම්බන්ධ වීම කලාපය ශක්තිමත් කළේය."),
      q(t, "චීනයේ ෂැංහයි හා නිංබෝ ඇතුළු යැංසි ගංගා ඩෙල්ටාව ලෝකයේ ප්‍රධාන කාර්මික කේන්ද්‍රයක් වී ඇත්තේ ඇයි?",
        "කාර්යබහුල බහාලුම් වරායන්, ගංගා ජල මාර්ග, අධිවේගී දුම්රිය හා උසස් තාක්ෂණික නිෂ්පාදන සංකේන්ද්‍රණය වීම",
        "එම කලාපය තුළ කිසිදු කර්මාන්තශාලාවක් නොමැතිව සාම්ප්‍රදායික යැපුම් කෘෂිකර්මය පමණක් සිදු වීම",
        "ප්‍රදේශයේ ජනගහනය ඉතාම අල්ප වීම සහ මුහුදු වෙළඳාම සඳහා කිසිදු වරායක් පිහිටා නොතිබීම",
        "විදේශීය රටවල් සමඟ සියලුම නාවික හා වෙළඳ සබඳතා නතර කර හුදකලා කෘෂි කලාපයක් ලෙස පැවතීම",
        "යැංසි ගංගාව අභ්‍යන්තර චීනය වෙරළබඩ ප්‍රධාන වෙළඳ වරායන් සමඟ සෘජුවම සම්බන්ධ කරයි."),
      q(t, "ශ්‍රී ලංකාවේ වී වගාව සිදු කරන ප්‍රධාන කන්න දෙක වන 'මහ කන්නය' හා 'යල කන්නය' ලැබෙන වර්ෂාපතන රටා මොනවාද?",
        "මහ කන්නය ඊසානදිග මෝසම හා දෙවන අන්තර් මෝසම මතත් යල කන්නය නිරිතදිග මෝසම හා වාරි ජලය මතත් රඳා පවතී",
        "මහ කන්නය නිරිතදිග මෝසමෙන් පමණක් වියළි කලාපයේත් යල කන්නය හිම දියවන ජලයෙන් උඩරටත් සිදු කෙරේ",
        "මහ හා යල යන කන්න දෙකම කිසිදු වර්ෂාපතනයක් හෝ වාරි ජලයක් නොමැතිව වියළි පසේ වගා කෙරේ",
        "වී වගාව සිදු කරනු ලබන්නේ වසර දෙකකට වරක් මාස දෙකක කාලයක් සඳහා පමණක් වීම විශේෂත්වයකි",
        "මහ කන්නය දිවයින පුරාම පුළුල්ව වගා කරන ප්‍රධාන වී කන්නය වන අතර වියළි කලාපයේ වැව් හා මහවැලි ජලය යලට උපකාරී වේ."),
      q(t, "ශ්‍රී ලංකාවේ පොල් වගාව ආශ්‍රිතව නිපදවන ප්‍රධාන අපනයන හා කාර්මික නිෂ්පාදන සමූහය කුමක්ද?",
        "දිසිඳි පොල්, පොල් තෙල්, පොල් කිරිපිටි, කොහු කෙඳි, කොහුබත් සහ පොල්කටු අඟුරු",
        "සාම්ප්‍රදායික ෂීට් රබර්, රබර් ටයර්, ශල්‍ය අත්වැසුම් හා ඉදිකිරීම් වානේ පොලු වර්ග",
        "වියළි හාල්මැස්සන්, ටින් කළ ටූනා මසුන්, ඉස්සන් සහ කලපු කකුළුවන් වැනි මුහුදු ආහාර",
        "පිඟන් මැටි බඳුන්, සිමෙන්ති, ෆොස්පේට් පොහොර සහ පිරිපහදු කළ ඛනිජ තෙල් නිෂ්පාදන",
        "පොල් ගසේ සෑම කොටසක්ම ආහාර හා කාර්මික අමුද්‍රව්‍ය ලෙස භාවිත වන නිසා එය කප්රුක ලෙස හැඳින්වේ."),
      q(t, "ශ්‍රී ලංකාවේ රබර් වගාවෙන් ලබාගන්නා ස්වාභාවික රබර් කිරි භාවිත කර නිපදවන ප්‍රධාන කාර්මික අපනයන මොනවාද?",
        "ඝන ටයර්, රබර් අත්වැසුම්, ෂීට් රබර්, ක්‍රේප් රබර් සහ කාර්මික රබර් භාණ්ඩ",
        "වියළි තේ කොළ, කුරුඳු තෙල්, ගම්මිරිස් සහ සුවඳැල් වී වැනි ආහාර නිෂ්පාදන",
        "කපු නූල්, පොලියෙස්ටර් රෙදිපිළි, ප්ලාස්ටික් පුටු සහ ඇලුමිනියම් වහල තහඩු",
        "සිමෙන්ති, පිඟන් භාණ්ඩ, වීදුරු බෝතල් සහ රත්නපුර කැපූ මැණික් වර්ග",
        "ශ්‍රී ලංකාව ලෝකයේ ප්‍රමුඛතම ඝන ටයර් හා උසස් තත්ත්වයේ ක්‍රේප් රබර් සැපයුම්කරුවෙකි."),
      q(t, "ශ්‍රී ලංකාවේ වියළි කලාපයේ මිරිදිය ධීවර කර්මාන්තය (Inland Fisheries) ප්‍රධාන ආර්ථික කටයුත්තක් වී ඇත්තේ ඇයි?",
        "අනුරාධපුරය, පොළොන්නරුව හා අම්පාර වාරි වැව් හා ජලාශවල මසුන් බෝ කර ග්‍රාමීය පෝෂණය හා ආදායම සැපයීම",
        "වියළි කලාපයේ කිසිදු වැවක් හෝ ජලාශයක් නොමැති නිසා භූගත ළිං තුළ පමණක් මසුන් ඇති කිරීම",
        "දිවයිනේ වෙරළබඩ ප්‍රදේශවල මුහුදු මසුන් ඇල්ලීම නීතියෙන් සම්පූර්ණයෙන්ම තහනම් කර ඇති බැවින්",
        "වියළි කලාපයේ සියලුම වැව්වල ජලය ඉතා අධික ලුණු රසයෙන් යුක්ත වී කලපු බවට පත්ව ඇති බැවින්",
        "මිරිදිය ජලාශවල තිලාපියා, රෝහු හා කැට්ලා වැනි මසුන් ග්‍රාමීය ප්‍රෝටීන් සැපයුමට ප්‍රධාන දායකත්වයක් දෙයි."),
      q(t, "ශ්‍රී ලංකාවේ සෙරමික් හා පිඟන් භාණ්ඩ කර්මාන්තය (Ceramic Industry) සාර්ථකව ස්ථානගත වීමට බලපෑ දේශීය ඛනිජ සම්පත් මොනවාද?",
        "බොරලැස්ගමුව හා මීටියාගොඩ කාඔලින් (පිඟන් මැටි), බෝල් මැටි, ෆෙල්ඩ්ස්පාර් සහ ක්වාට්ස් නිධි පැවතීම",
        "මන්නාරම හා පුත්තලම වෙරළ තීරයේ බහුලව ඇති ගල් අඟුරු, බොරතෙල් හා යකඩ ලෝපස් නිධි පැවතීම",
        "නුවරඑළිය හා බදුල්ල කඳුකරයේ වගා කරනු ලබන තේ හා එළවළු අපද්‍රව්‍ය අමුද්‍රව්‍ය ලෙස භාවිත කිරීම",
        "හම්බන්තොට ලුණු ලේවායන්ගෙන් ලබාගන්නා ලුණු හා මුහුදු බෙල්ලන් පමණක් කර්මාන්තශාලාවලට සැපයීම",
        "දංකොටුව හා මීගමුව ප්‍රදේශවල උසස් තත්ත්වයේ පෝසිලේන් පිඟන් භාණ්ඩ විදේශ වෙළඳපොළට අපනයනය කෙරේ."),
      q(t, "කුඩා හා මධ්‍ය පරිමාණ ව්‍යවසායන් (SMEs) රටක ආර්ථිකයේ වැදගත් කොටසක් ලෙස සලකන්නේ ඇයි?",
        "ප්‍රාදේශීය රැකියා විශාල ලෙස බිහි කරමින් දේශීය අමුද්‍රව්‍ය යොදා ආර්ථික වර්ධනයට දායක වීම",
        "විශාල බහුජාතික සමාගම් සියල්ල රටින් පිටමං කර විදේශීය ආයෝජන සම්පූර්ණයෙන් තහනම් කර දැමීම",
        "රටේ රැකියා ප්‍රමාණය අඩු කරමින් සියලුම භාණ්ඩ විදේශ රටවලින් පමණක් ආනයනය කිරීමට පෙළඹවීම",
        "ප්‍රාදේශීය නගරවල ව්‍යාපාර කටයුතු නතර කර සියලු කර්මාන්ත අගනුවරට පමණක් සීමා කර තැබීම",
        "සහනදායී ණය, තාක්ෂණික පුහුණුව හා වෙළඳපොළ සම්බන්ධතා කුඩා ව්‍යවසායන් ශක්තිමත් කිරීමට අත්‍යවශ්‍ය වේ."),
      q(t, "'සමුද්‍රීය සැපයුම් හා ප්‍රති-නැව්ගත කිරීමේ මධ්‍යස්ථානයක්' (Maritime Transshipment Hub) ලෙස කොළඹ වරාය (Colombo Port) කලාපීයව වැදගත් වන්නේ ඇයි?",
        "මලක්කා-සූවස් ප්‍රධාන නාවික මාර්ගයට ආසන්න නිසා මව් නැව්වල බහාලුම් කලාපීය වරායන් වෙත බෙදා හැරීමට හැකි වීම",
        "ශ්‍රී ලංකාවේ මධ්‍යම කඳුකර කෘෂි කලාපය මැදින් ගමන් කරන ගංගා ඔස්සේ කෙලින්ම තේ ප්‍රවාහනය කිරීමට හැකි වීම",
        "ලෝකයේ ගැඹුරුම අභ්‍යන්තර මිරිදිය ජලාශ පද්ධතිය තුළ පිහිටා තිබීම නිසා මගී බෝට්ටු පමණක් හැසිරවීමට හැකි වීම",
        "දකුණු ආසියාවේ සියලුම ධීවර යාත්‍රා සඳහා ඉන්ධන නොමිලේ ලබා දෙන කුඩා මසුන් ඇල්ලීමේ තොටුපළක් ලෙස ක්‍රියා කිරීම",
        "දකුණු ආසියාවේ ගැඹුරුතම හා කාර්යක්ෂමතම බහාලුම් පර්යන්ත අතර කොළඹ වරාය ප්‍රමුඛ ස්ථානයක් ගනී."),
      q(t, "'පරිසර හිතකාමී හා ප්‍රජා මූලික සංචාරක ව්‍යාපාරය' (Ecotourism & Community-Based Tourism) සාම්ප්‍රදායික මහා පරිමාණ සංචාරක ව්‍යාපාරයෙන් වෙනස් වන්නේ කෙසේද?",
        "පරිසරයට හා සංස්කෘතියට හානි නොකර සුළු පරිමාණයෙන් සංවිධානය කර ආදායම සෘජුවම ප්‍රාදේශීය ප්‍රජාවට ලැබීමට සැලැස්වීම",
        "වනාන්තර හා ජාතික උද්‍යාන මැද විශාල බහුමහල් කොන්ක්‍රීට් හෝටල් ඉදිකර විදේශීය සමාගම් වෙත පමණක් ආදායම යොමු කිරීම",
        "සංචාරකයන්ට ප්ලාස්ටික් අපද්‍රව්‍ය රක්ෂිත තුළ බැහැර කිරීමට ඉඩ දී ප්‍රාදේශීය ගැමි ප්‍රජාව සේවාවලින් සම්පූර්ණයෙන් බැහැර කිරීම",
        "සංවේදී කොරල්පර හා කඩොලාන කලාපවල අධිවේගී ජල ක්‍රීඩා හා ඝෝෂාකාරී රාත්‍රී සමාජ ශාලා බහුලව ව්‍යාප්ත කිරීම",
        "සිංහරාජය, මීමුරේ, නකල්ස්, කලපිටිය හා වනජීවී උද්‍යාන ආශ්‍රිතව මෙම ආකෘතිය ජනප්‍රිය වෙමින් පවතී."),
      q(t, "හම්බන්තොට ජාත්‍යන්තර වරාය ශ්‍රී ලංකාවේ ආර්ථික භූගෝල විද්‍යාව තුළ සුවිශේෂී වරායක් බවට පත්වීමට ප්‍රධාන වශයෙන් බලපා ඇති සේවාව කුමක්ද?",
        "විදේශීය වාහන ආනයන-අපනයන ප්‍රතිනැව්ගත කිරීම, නැව් ඉන්ධන සැපයීම හා තොග භාණ්ඩ හැසිරවීම",
        "උඩරට තේ වතු සඳහා අවශ්‍ය වාරි ජලය නළ මගින් සෘජුවම කඳුකරයට බෙදා හැරීම",
        "දිවයිනේ සියලුම අභ්‍යන්තර ගුවන් ගමන් පාලනය කිරීම සහ ගුවන් මගීන් හුවමාරු කිරීම",
        "කොළඹ නගරයේ මාර්ග තදබදය අවම කිරීම සඳහා දෛනික මගී දුම්රිය සේවා පැවැත්වීම",
        "දකුණු මුහුදු තීරයේ ප්‍රධාන නැව් මාර්ගයට ආසන්නව පිහිටීම නිසා මෙම වරාය Ro-Ro වාහන නැව් සේවා සඳහා ප්‍රචලිතය."),
      q(t, "ශ්‍රී ලංකාවේ වනජීවී පරිසර සංචාරක ව්‍යාපාරය (Wildlife Ecotourism) වැඩි වශයෙන් කේන්ද්‍රගත වී ඇති ප්‍රධාන ජාතික උද්‍යාන හා සමුද්‍ර කලාප මොනවාද?",
        "යාල, උඩවලව, මින්නේරිය හා විල්පත්තු ජාතික උද්‍යාන සමඟ මිරිස්ස හා ත්‍රිකුණාමලය තල්මසුන් නැරඹුම් මුහුදු තීරය",
        "කොළඹ, ගම්පහ හා කළුතර නාගරික කාර්මික ජනපද සහ ප්‍රධාන වාණිජ වරාය පර්යන්ත කලාප",
        "නුවරඑළිය, හැටන් හා තලවකැලේ උඩරට තේ වතු යායන් සහ ජල විදුලි ජලාශ ඉවුරු",
        "පුත්තලම, හම්බන්තොට හා අලිමංකඩ ලුණු ලේවායන් සහ සිමෙන්ති නිෂ්පාදන කර්මාන්තශාලා පරිශ්‍ර",
        "අලි ඇතුන්, දිවියන් හා නිල් තල්මසුන් නැරඹීම මෙරටට ඉහළ ආදායමක් උපයා දෙන සංචාරක ආකර්ෂණයකි."),
      q(t, "රටක ආර්ථික ප්‍රමාණය මැනීමේදී 'දළ දේශීය නිෂ්පාදිතය' (GDP) සහ 'දළ ජාතික ආදායම' (GNI) අතර ඇති ප්‍රධාන වෙනස කුමක්ද?",
        "GDP රටේ දේශසීමාව තුළ නිෂ්පාදනය මනින අතර GNI විදේශයන්ගෙන් ලැබෙන ශුද්ධ සාධක ආදායමද එකතු කරයි",
        "GDP මගින් කෘෂිකර්මය පමණක් මනින අතර GNI මගින් කාර්මික හා සේවා අංශ පමණක් මනිනු ලබයි",
        "GDP මගින් ජනගහන ඝනත්වය ගණනය කරන අතර GNI මගින් රටේ මුළු භූමි ප්‍රමාණය ගණනය කරයි",
        "GDP සෑම විටම විදේශ විනිමය ණය මනින අතර GNI රටේ වාර්ෂික වර්ෂාපතන සාමාන්‍යය මනී",
        "විදේශ ශ්‍රමික ප්‍රේෂණ වැඩි රටවල GNI අගය සැලකිය යුතු ලෙස ඉහළ මට්ටමක පැවතිය හැකිය."),
      q(t, "එක්සත් ජාතීන්ගේ 'මානව සංවර්ධන දර්ශකය' (HDI) ගණනය කිරීමේදී ඒක පුද්ගල ආදායමට අමතරව සැලකිල්ලට ගන්නා අනෙක් මාන දෙක මොනවාද?",
        "උපතේදී අපේක්ෂිත ආයු කාලය මගින් මනින සෞඛ්‍යය සහ පාසල් අධ්‍යාපන වසර ගණනින් මනින අධ්‍යාපනය",
        "නගරවල ඇති මෝටර් රථ සංඛ්‍යාව සහ රටේ ජාත්‍යන්තර ගුවන් තොටුපළවල් සංඛ්‍යාවේ එකතුව",
        "රටේ පවතින ස්වාභාවික වනාන්තර ප්‍රතිශතය සහ වාර්ෂිකව හාරනු ලබන ඛනිජ සම්පත් ප්‍රමාණය",
        "මහාමාර්ග ජාලයේ මුළු දිග ප්‍රමාණය සහ වාර්ෂිකව අපනයනය කරන කෘෂි භාණ්ඩවල බර ප්‍රමාණය",
        "ආර්ථික සංවර්ධනය යනු ආදායම පමණක් නොව මානව ජීවන තත්ත්වය ඉහළ යාම බව HDI මගින් පෙන්වයි."),
      q(t, "රටක ජනතාවගේ ජීවන තත්ත්වය මැනීමේදී 'ඒක පුද්ගල ආදායම' (Per Capita Income) යන දර්ශකය පමණක් භාවිත කිරීමේ ප්‍රධාන සීමාව කුමක්ද?",
        "එය සාමාන්‍ය අගයක් බැවින් සමාජයේ ධනවතුන් හා දුප්පතුන් අතර පවතින ආදායම් විෂමතාව නොපෙන්වයි",
        "එමගින් රටක ජීවත් වන මුළු ජනගහන සංඛ්‍යාව හෝ වයස් ව්‍යුහය නිවැරදිව ප්‍රකාශ කළ නොහැකිය",
        "රටේ අපනයන ආදායම වැඩි වූ විට ඒක පුද්ගල ආදායම් අගය ස්වයංක්‍රීයව ශූන්‍යය දක්වා පහත වැටේ",
        "කෘෂිකාර්මික නිෂ්පාදන වටිනාකම කිසිදු ආකාරයකින් ජාතික ආදායම් ගණනය කිරීම්වලට ඇතුළත් නොවේ",
        "සාමාන්‍ය අගය ඉහළ වුවද සුළු පිරිසක් අත ධනය කේන්ද්‍ර වී ඇත්නම් බහුතරය දුප්පත් විය හැකිය."),
      q(t, "ශ්‍රී ලංකාවේ ග්‍රාමීය ආර්ථිකයට දායක වන කජු සහ කිතුල් ආශ්‍රිත කර්මාන්ත වැඩි වශයෙන් ව්‍යාප්ත වී ඇත්තේ කුමන ප්‍රදේශවලද?",
        "පුත්තලම, වන්නි හා මඩකලපුව වියළි ප්‍රදේශවල කජු වගාවත් තෙත් කඳුකරයේ කිතුල් කර්මාන්තයත්",
        "නුවරඑළිය ඉහළ කඳුකර තැනිතලාවල කජු වගාවත් හම්බන්තොට වියළි වෙරළ තීරයේ කිතුල් කර්මාන්තයත්",
        "යාපනය කලපු ජල තීරයේ කජු වගාවත් මන්නාරම වැලි දූපත්වල කිතුල් පැණි නිෂ්පාදනයත්",
        "කොළඹ වරාය ආශ්‍රිත කාර්මික කලාපවල කජු වගාවත් කටුනායක නිදහස් වෙළඳ කලාපයේ කිතුල් කර්මාන්තයත්",
        "කජු මද සැකසීම හා කිතුල් හකුරු නිෂ්පාදනය ග්‍රාමීය පවුල්වලට අමතර ආදායම් සපයයි."),
      q(t, "ශ්‍රී ලංකාවේ 'ගොවිජන සේවා මධ්‍යස්ථාන' හා 'ගොවි සංවිධාන' ග්‍රාමීය කෘෂි ආර්ථිකයේදී ඉටු කරන ප්‍රධාන කාර්යභාරය කුමක්ද?",
        "වාරි ජලය බෙදා හැරීම, බීජ හා පොහොර සැපයීම, කෘෂි උපදේශනය හා වැව් නඩත්තුව සම්බන්ධීකරණය කිරීම",
        "නාගරික මහල් නිවාස සංකීර්ණ ඉදිකිරීම සහ අධිවේගී මාර්ග ගාස්තු එකතු කිරීම සංවිධානය කිරීම",
        "විදේශීය ගුවන් යානා හා නාවික බහාලුම් නැව් සඳහා රේගු බලපත්‍ර නිකුත් කිරීම සිදු කිරීම",
        "පෞද්ගලික වාණිජ බැංකු සඳහා කොටස් වෙළඳපොළ ආයෝජන උපදෙස් ලබා දීම සිදු කිරීම",
        "සාමූහික ගොවි සංවිධාන කුඩා ගොවීන්ගේ බෙදාහැරීමේ හා වාරි ගැටලු විසඳීමට උපකාරී වේ."),
      q(t, "ශ්‍රී ලංකාව වැනි දූපත් රාජ්‍යයකට තම අනන්‍ය ආර්ථික කලාපය (EEZ) ඔස්සේ 'නීල ආර්ථිකය' (Blue Economy) යටතේ සංවර්ධනය කළ හැකි ක්ෂේත්‍ර මොනවාද?",
        "තිරසාර ගැඹුරු මුහුදු ධීවර කර්මාන්තය, නාවික වරාය සේවා, සමුද්‍ර සංචාරක ව්‍යාපාරය හා අක්වෙරළ සුළං බලය",
        "මුහුදු ජලය සම්පූර්ණයෙන් ඉවත් කර ඒ මත කෘෂිකාර්මික කඳුකර තේ වතු ඉදිකිරීම",
        "සියලුම වෙරළබඩ කොරල් පර කඩා ඉවත් කර ඒ වෙනුවට ප්ලාස්ටික් අපද්‍රව්‍ය තැන්පත් කිරීම",
        "ගැඹුරු සාගර පතුලේ රථවාහන සඳහා කොන්ක්‍රීට් අධිවේගී මාර්ග පද්ධති ඉදිකිරීම",
        "ශ්‍රී ලංකාවේ ගොඩබිම් ප්‍රමාණය මෙන් හත් ගුණයකට ආසන්න සාගර කලාපයක් අප සතුය."),
      q(t, "ඩුබායි, දෝහා සහ සිංගප්පූරුව ලෝකයේ ප්‍රධානතම ජාත්‍යන්තර ගුවන් ගමන් හුවමාරු මධ්‍යස්ථාන (Aviation Hubs) බවට පත්වීමට බලපෑ භූගෝලීය සාධකය කුමක්ද?",
        "යුරෝපය, ආසියාව, අප්‍රිකාව හා ඕස්ට්‍රේලියාව කෙටි පියාසැරි කාලයකින් සම්බන්ධ කරන මධ්‍යගත පිහිටීම",
        "එම නගරවල ගුවන් යානා ඉන්ධන මිල අනෙක් සියලුම රටවලට වඩා කිහිප ගුණයකින් ඉහළ වීම",
        "විශාල ජනගහනයක් රහිත වුවද වෙනත් කිසිදු රටක ගුවන් තොටුපළවල් ඉදිකර නොතිබීම",
        "කඳුකර භූ විෂමතාව නිසා කුඩා ගුවන් යානාවලට පමණක් ගොඩබෑමේ පහසුකම් තිබීම",
        "මෙම නගර භූගෝලීය පිහිටීම උපයෝගී කර ගනිමින් සංචාරක හා ලොජිස්ටික්ස් ආර්ථිකයන් ගොඩනඟා ඇත."),
      q(t, "ඇමසන් වනයෙන් ආරම්භ වූ ස්වාභාවික රබර් වගාව අද ප්‍රධාන වශයෙන් අග්නිදිග හා දකුණු ආසියාවේ ව්‍යාප්ත වීමට හේතු වූ කරුණ කුමක්ද?",
        "ඇමසන් කලාපයේ පැතිරුණු කොළ අංගමාර දිලීර රෝගය ආසියාවේ නොතිබීමත් සුදුසු දේශගුණය හා ශ්‍රමය පැවතීමත්",
        "ආසියානු රටවල වසර පුරා අධික හිම පතනයක් පැවතීම නිසා රබර් කිරි වැඩිපුර ගලා යාම",
        "දකුණු ඇමෙරිකාවේ රබර් ශාකය වැවීම නීතියෙන් තහනම් කර තිබීම සහ ජලය නොමැති වීම",
        "ආසියාවේ සමතලා කාන්තාර පස තුළ රබර් ගස් ඉතා වේගයෙන් වර්ධනය වන බව සොයා ගැනීම",
        "තායිලන්තය, ඉන්දුනීසියාව, වියට්නාමය, මැලේසියාව හා ශ්‍රී ලංකාව ස්වාභාවික රබර් නිෂ්පාදනයේ ප්‍රමුඛයන් වේ."),
      q(t, "නිමි ඇඟලුම් හා රෙදිපිළි කර්මාන්තය බටහිර දියුණු රටවල සිට ආසියාවේ සංවර්ධනය වෙමින් පවතින රටවලට විස්ථාපනය වීමට ප්‍රධාන හේතුව කුමක්ද?",
        "ශ්‍රම-සූක්ෂ්ම කර්මාන්තයක් වන බැවින් අඩු නිෂ්පාදන පිරිවැය හා දක්ෂ ශ්‍රම බලකාය ආසියාවේ පැවතීම",
        "යුරෝපයේ හා උතුරු ඇමෙරිකාවේ ජනතාව නවීන ඇඳුම් පැළඳුම් භාවිතය සම්පූර්ණයෙන් නතර කිරීම",
        "ආසියානු රටවල කාර්මික විදුලි බලය සහ ප්‍රවාහන ගාස්තු සම්පූර්ණයෙන් නොමිලේ ලබා දීම",
        "බටහිර රටවල කිසිදු මහන යන්ත්‍රයක් හෝ රෙදි වියන යන්ත්‍රයක් නිෂ්පාදනය නොකිරීම",
        "ශ්‍රී ලංකාව, බංග්ලාදේශය, වියට්නාමය හා කාම්බෝජය ලෝක ඇඟලුම් සැපයුමේ ප්‍රධාන හවුල්කරුවන් වේ."),
      q(t, "වර්තමාන කාර්මික අපනයනකරුවන්ට සූර්ය බලය හා පිරිසිදු බලශක්තිය භාවිත කිරීම ආර්ථික වශයෙන් වැදගත් වන්නේ ඇයි?",
        "ඉන්ධන වියදම අඩු කර ගැනීමට මෙන්ම පරිසර හිතකාමී හරිත නිෂ්පාදන ඉල්ලා සිටින විදේශීය ගැනුම්කරුවන් ආකර්ෂණය කර ගැනීමට",
        "සූර්ය බලය භාවිත කළ විට කම්හල්වල නිෂ්පාදිත භාණ්ඩවල බර ප්‍රමාණය ඉබේම දෙගුණ වන නිසා",
        "පුනර්ජනනීය බලශක්තිය භාවිතයෙන් රේගු හා වරාය ගාස්තු සියල්ල රජය විසින් අවලංගු කරන නිසා",
        "විදුලි පද්ධතිය සම්පූර්ණයෙන් විසන්ධි කර අතින් පමණක් යන්ත්‍ර ක්‍රියාත්මක කිරීමට හැකි වන නිසා",
        "හරිත කර්මාන්තශාලා (Green Factories) සංකල්පය ශ්‍රී ලංකාවේ ඇඟලුම් අංශයේදී සාර්ථකව ක්‍රියාත්මක වේ."),
      q(t, "ජපානයේ ප්‍රධාන කාර්මික කලාප අතරින් 'කේහින් (ටෝකියෝ-යොකොහාමා)' සහ 'හන්ෂින් (ඔසාකා-කෝබේ)' කලාප වෙරළබඩව පිහිටා තිබීමේ වාසිය කුමක්ද?",
        "ආනයනික අමුද්‍රව්‍ය හා ඉන්ධන වරායෙන් සෘජුවම ලබාගෙන නිමි භාණ්ඩ නැව්ගත කිරීම පහසු වීම",
        "එම වෙරළ තීරයේ ලෝකයේ විශාලතම ස්වාභාවික යකඩ හා ගල් අඟුරු පතල් පිහිටා තිබීම",
        "මුහුදු ජලය පිරිපහදු නොකර සෘජුවම වානේ උණු කිරීමේ උදුන් සඳහා භාවිත කිරීමට හැකි වීම",
        "රටේ අභ්‍යන්තර කඳුකරයේ ජනගහනය 90% කට වඩා වැඩි ප්‍රතිශතයක් ජීවත් වීම",
        "වරාය ආශ්‍රිත කාර්මිකකරණය ජපානයේ සම්පත් හිඟය ජයගැනීමට ප්‍රධාන පිටිවහලක් විය."),
      q(t, "රටක ආහාර සුරක්ෂිතතාව (Food Security) තහවුරු කිරීම සඳහා දේශීය ධාන්‍ය හා අල බෝග වගාව ප්‍රවර්ධනය කිරීම වැදගත් වන්නේ ඇයි?",
        "ආනයනික ආහාර මිල ඉහළ යාම හෝ සැපයුම් බාධා ඇති වූ විට රටේ ජනතාවට ආහාර හිඟයක් ඇති නොවීමට",
        "සියලුම විදේශීය නාවික වරායන් හා ගුවන් තොටුපළවල් ස්ථිරවම වසා දැමීමට හැකි වන නිසා",
        "ගොවීන්ට නවීන කෘෂිකාර්මික යන්ත්‍රසූත්‍ර භාවිතය සම්පූර්ණයෙන් නතර කිරීමට ඉඩ ලැබෙන නිසා",
        "විදේශ විනිමය සම්පූර්ණයෙන්ම අවලංගු කර භාණ්ඩ හුවමාරු ක්‍රමය පමණක් භාවිත කිරීමට",
        "වී වගාවට අමතරව කුරක්කන්, මුං, කව්පි, බඩ ඉරිඟු හා මඤ්ඤොක්කා වගාව රටේ පෝෂණයට දායක වේ."),
      q(t, "ශ්‍රී ලංකාවේ වියළි කලාපයේ සාම්ප්‍රදායික හේන් ගොවිතැනේ සිට ස්ථිර වාරි කෘෂිකර්මය දක්වා මාරු වීමෙන් ලැබුණු ප්‍රධාන ප්‍රතිලාභය කුමක්ද?",
        "වනාන්තර එළිපෙහෙළි කිරීම අවම වී එකම ඉඩමකින් යල හා මහ කන්න දෙකෙහිම ඉහළ අස්වැන්නක් ලැබීම",
        "වියළි කලාපයේ සියලුම වැව් හා ඇළ මාර්ග ස්වයංක්‍රීයව වියළී යාම සිදු වීම",
        "ගොවි පවුල් වසර දෙකෙන් දෙකට නව ප්‍රදේශවලට සංක්‍රමණය වීමට සිදු වීම",
        "පසේ සාරවත්භාවය සම්පූර්ණයෙන් නැති වී වගා කටයුතු අතහැර දැමීමට සිදු වීම",
        "මහවැලි ව්‍යාපාරය හා වැව් ප්‍රතිසංස්කරණය වියළි කලාපයේ ස්ථිර ගොවි ජනාවාස ශක්තිමත් කළේය."),
      q(t, "ශ්‍රී ලංකාව තුළ විවිධ කෘෂි-දේශගුණික කලාප පැවතීම මෙරට කෘෂි ආර්ථිකයට වාසිදායක වන්නේ කෙසේද?",
        "උන්නතාංශය හා වර්ෂාපතනය අනුව උඩරට එළවළු, තේ, රබර්, පොල් හා වියළි කලාපීය ධාන්‍ය වැනි විවිධ බෝග වැවිය හැකි වීම",
        "දිවයිනේ ඕනෑම ප්‍රදේශයක වසර පුරාම එකම උෂ්ණත්වය හා වර්ෂාපතනය සමානව පවතින බැවින්",
        "වැසි ජලය නොමැතිව කාන්තාර ශාක පමණක් වගා කිරීමට සියලුම පළාත්වලට සිදු වන බැවින්",
        "සියලුම ගොවීන්ට වසරේ සෑම මාසයකම එකම තනි බෝග වර්ගය පමණක් වගා කිරීමට හැකි වන බැවින්",
        "මෙම පාරිසරික විවිධත්වය නිසා කුඩා දූපතක වුවද බහු බෝග නිෂ්පාදනයක් ලබාගත හැකිය."),
      q(t, "මහාමාර්ග, වරාය හෝ ජලාශ වැනි විශාල සංවර්ධන ව්‍යාපෘතියක් ආරම්භ කිරීමට පෙර පාරිසරික බලපෑම් ඇගයීමක් (EIA) සිදු කරන්නේ ඇයි?",
        "ව්‍යාපෘතියෙන් සිදුවිය හැකි පාරිසරික හා සමාජ හානි පූර්වයෙන් හඳුනාගෙන ඒවා අවම කිරීමේ පියවර ගැනීමට",
        "සංවර්ධන ව්‍යාපෘති සියල්ල කිසිදු හේතුවක් නොමැතිව ස්ථිරවම අවලංගු කර දැමීමට",
        "කර්මාන්තශාලා අපද්‍රව්‍ය අසල ඇති ගංගාවලට මුදා හැරීම සඳහා නීතිමය අවසරය ලබා ගැනීමට",
        "ව්‍යාපෘතියේ මූල්‍ය වියදම පමණක් ගණනය කර පාරිසරික සාධක සම්පූර්ණයෙන් නොසලකා හැරීමට",
        "තිරසාර සංවර්ධනය සඳහා ආර්ථික ප්‍රතිලාභ සමඟ පරිසර ආරක්ෂාවද තුලනය කළ යුතුය."),
      q(t, "සිංගප්පූරුවේ ජුරොං හා ඩුබායිහි ජෙබෙල් අලි වැනි 'වරාය ආශ්‍රිත නිදහස් වෙළඳ කලාප' (Port FTZs) සාර්ථක වීමට ප්‍රධාන හේතුව කුමක්ද?",
        "ආනයනික අමුද්‍රව්‍ය රේගු බදු රහිතව ගබඩා කර සකසා ගොඩබිම් ප්‍රවාහන වියදමකින් තොරව නැවත අපනයනය කිරීම",
        "එම කලාප තුළ පමණක් විශාල වී වගා බිම් හා කෘෂිකාර්මික ජලාශ පද්ධති පවත්වාගෙන යාම",
        "වරාය වෙත පැමිණෙන සියලුම විදේශීය භාණ්ඩ නැව් සඳහා දෙගුණයක ආනයන බදු අය කිරීම",
        "ගොඩබිම් මාර්ග හා විදුලි සම්බන්ධතා කිසිවක් නොමැතිව කුඩා බෝට්ටු පමණක් භාවිත කිරීම",
        "වරාය හා නිෂ්පාදන කලාපය එකම පරිශ්‍රයක පිහිටීම නිෂ්පාදන කාලය හා පිරිවැය අඩු කරයි."),
      q(t, "සැකසුමකින් තොර අමු තේ, කෝපි හෝ රබර් වැනි ප්‍රාථමික භාණ්ඩ අපනයනය මත පමණක් යැපෙන රටවල ආර්ථිකය අස්ථාවර වන්නේ ඇයි?",
        "ලෝක වෙළඳපොළේ ප්‍රාථමික භාණ්ඩ මිල නිතර වෙනස් වීම හා කාලගුණික හානිවලට ගොදුරු වීම නිසා",
        "කාර්මික නිමි භාණ්ඩවලට වඩා අමු කෘෂි භාණ්ඩවල මිල සෑම වසරකම ඉතා වේගයෙන් ඉහළ යන නිසා",
        "ලෝක වෙළඳපොළේ කිසිදු රටක් නිමි භාණ්ඩ හෝ තාක්ෂණික උපකරණ මිලදී නොගන්නා නිසා",
        "කාලගුණික විපර්යාස කිසිවිටෙක කෘෂිකාර්මික බෝග අස්වැන්න කෙරෙහි බලපෑමක් ඇති නොකරන නිසා",
        "අපනයන විවිධාංගීකරණය හා අගය එකතු කළ නිෂ්පාදන වෙත යොමු වීම මෙම අවදානම අඩු කරයි."),
      q(t, "ඩිජිටල් බැංකුකරණය හා ජංගම දුරකථන ගෙවීම් ක්‍රම ග්‍රාමීය වෙළඳාම හා කුඩා ව්‍යාපාර දියුණු කිරීමට උපකාරී වන්නේ කෙසේද?",
        "බැංකු ශාඛාවකට දුර ගමන් නොකර ක්ෂණිකව මුදල් හුවමාරු කර ගනිමින් ගනුදෙනු කාලය ඉතිරි කිරීම",
        "ග්‍රාමීය ජනතාවට මුදල් ඉතිරි කිරීම හා කුඩා ව්‍යාපාර සඳහා ණය ගැනීම සම්පූර්ණයෙන් තහනම් කිරීම",
        "නගරයේ පිහිටි සියලුම තොග වෙළඳසැල් වසා දමා වෙළඳාම ගමට පමණක් සීමා කර දැමීම",
        "භාණ්ඩ ප්‍රවාහන රථ හා කුරියර් සේවා භාවිතය අනවශ්‍ය බවට පත් කර ප්‍රවාහනය නතර කිරීම",
        "මූල්‍ය අන්තර්ග්‍රහණය (Financial Inclusion) ග්‍රාමීය ව්‍යවසායකත්වය ශක්තිමත් කිරීමට පිටිවහලකි."),
      q(t, "අග්නිදිග ආසියාවේ (මැලේසියාව හා ඉන්දුනීසියාව) 'තෙල් පොල්' (Oil Palm) වගාව ආර්ථික හා පාරිසරික වශයෙන් විවාදාත්මක වී ඇත්තේ ඇයි?",
        "එය ඉහළ එළවළු තෙල් අස්වැන්නක් හා ආදායමක් දුන්නද වගා බිම් සඳහා වැසි වනාන්තර එළිපෙහෙළි කෙරෙන බැවින්",
        "එම ශාකයෙන් කිසිදු ආහාරයට ගත හැකි තෙල් වර්ගයක් හෝ කාර්මික අමුද්‍රව්‍යයක් නොලැබෙන බැවින්",
        "තෙල් පොල් වගාව සම්පූර්ණයෙන්ම හිම වැටෙන ධ්‍රැවීය කලාපවල පමණක් සාර්ථකව වැවෙන බැවින්",
        "මෙම වගාව නිසා ගෝලීය කාබන්ඩයොක්සයිඩ් විමෝචනය සම්පූර්ණයෙන්ම ශූන්‍ය වී වනාන්තර වැඩි වන බැවින්",
        "තිරසාර වගා සහතිකකරණය මගින් නව වන විනාශයෙන් තොරව නිෂ්පාදනය පවත්වා ගැනීමට උත්සාහ කෙරේ."),
      q(t, "ගෝලීය ආර්ථික භූගෝල විද්‍යාවේදී 'මලක්කා සමුද්‍ර සන්ධිය' සහ 'හෝමුස් සමුද්‍ර සන්ධිය' තීරණාත්මක වන්නේ කුමන හේතුවක් නිසාද?",
        "ලෝක ඛනිජ තෙල් හා බහාලුම් නැව් ප්‍රවාහනයෙන් විශාල කොටසක් ගමන් ගන්නා ප්‍රධාන නාවික සන්ධිස්ථාන වීම",
        "ලෝකයේ විශාලතම මිරිදිය ජලාශ දෙක ලෙස පානීය ජලය පමණක් සපයන මාර්ග දෙකක් වීම",
        "සාගර මතුපිට අධික අයිස් තට්ටු පවතින බැවින් වසරේ මාස නවයක් නැව් ගමන් නැවතී තිබීම",
        "මහාද්වීප දෙකක් අතර පටු දුම්රිය පාලම් පමණක් ඉදිකර ඇති ගොඩබිම් මාර්ග වීම",
        "මෙම පටු මුහුදු මාර්ග අවහිර වුවහොත් ජාත්‍යන්තර ඉන්ධන හා භාණ්ඩ මිල වහාම ඉහළ යයි."),
      q(t, "සීනි කම්හල් උක් වගා බිම් අසලද යකඩ උණු කිරීමේ කම්හල් පතල් අසලද පිහිටුවීමට හේතු වන ආර්ථික සාධකය කුමක්ද?",
        "අමුද්‍රව්‍ය සැකසීමේදී බර විශාල ලෙස අඩු වන බැවින් බර අඩු නිමි භාණ්ඩය පමණක් ප්‍රවාහනය කිරීම",
        "පාරිභෝගික නිවාස ආසන්නයේ කිසිදු ඉඩමක් හෝ මාර්ග පහසුකමක් කර්මාන්ත සඳහා නොතිබීම",
        "නිමි භාණ්ඩයේ බර අමුද්‍රව්‍යයේ මුල් බරට වඩා කිහිප ගුණයකින් වැඩි වීම සිදු වීම",
        "ප්‍රවාහන වියදම අඩු කිරීම සඳහා බර අධික අපද්‍රව්‍ය නගර මධ්‍යයටම ගෙන යාම අවශ්‍ය වීම",
        "බර අඩුවන අමුද්‍රව්‍ය (Weight-losing) කර්මාන්ත අමුද්‍රව්‍ය ප්‍රභවය අසල ස්ථානගත වේ."),
      q(t, "පාවහන් හා සම් භාණ්ඩ නිෂ්පාදන කර්මාන්තය බොහෝ විට සත්ත්ව පාලන කලාප හෝ වරාය නගර ආසන්නයේ පිහිටුවන්නේ ඇයි?",
        "අමු සම් පහසුවෙන් ලබා ගැනීම, පිරිසැකසුම් ජල පහසුකම් හා දක්ෂ නිර්මාණ ශිල්පීන් වෙත ප්‍රවේශ වීමට",
        "පාවහන් නිපදවීම සඳහා ගල් අඟුරු පතල් හා යකඩ ලෝපස් නිධි අසලම පිහිටීම අනිවාර්ය වීම",
        "සම් භාණ්ඩ වියළීම සඳහා වසර පුරාම අධික හිම පතනයක් පැවතීම අත්‍යවශ්‍ය සාධකයක් වීම",
        "සමුද්‍ර ගැඹුර මීටර් දහසකට වඩා වැඩි නැව් තටාකාංගණ පාවහන් මැසීම සඳහා අවශ්‍ය වීම",
        "කැලිෆෝනියාව, ඉතාලිය, චීනය, ඉන්දියාව හා වියට්නාමය මෙම කර්මාන්තයේ ප්‍රධාන නිෂ්පාදකයෝ වෙති."),
      q(t, "ශ්‍රී ලංකාවේ ලුණු නිෂ්පාදන කර්මාන්තය පුත්තලම, හම්බන්තොට හා අලිමංකඩ වෙරළ තීරවල සාර්ථකව සිදු වීමට බලපාන භූගෝලීය සාධක මොනවාද?",
        "දැඩි සූර්ය තාපය, අඩු වර්ෂාපතනය, වේගවත් වාෂ්පීභවනය සිදු කරන සුළං හා නොගැඹුරු මැටි පසැති වෙරළ තැනිතලා",
        "වසර පුරාම පවතින අධික මෝසම් වර්ෂාපතනය සහ කඳු බෑවුම්වලින් ගලා එන ශීතල මිරිදිය ගංගා",
        "වෙරළ තීරයේ ගැඹුරු පාෂාණ කඳු ගැට පැවතීම සහ නිරන්තරයෙන් අහස වලාකුළින් වැසී තිබීම",
        "ගල් අඟුරු දහනය කර මුහුදු ජලය උණු කිරීමට අවශ්‍ය පතල් ලුණු ලේවායන් අසලම පිහිටීම",
        "සූර්ය තාපයෙන් ස්වාභාවිකව මුහුදු ජලය වාෂ්ප කර ලුණු නිපදවීම අඩු පිරිවැය ක්‍රමයකි."),
      q(t, "ශ්‍රී ලංකාවේ සිමෙන්ති නිෂ්පාදන කර්මාන්තය පුත්තලම (අරුවක්කාලු) හා කන්කසන්තුරේ ආශ්‍රිතව ව්‍යාප්ත වීමට ප්‍රධාන හේතුව කුමක්ද?",
        "මයෝසීන යුගයට අයත් විශාල හුණුගල් නිධි සහ මැටි පස් සම්පත් එම ප්‍රදේශවල පිහිටා තිබීම",
        "උඩරට කඳුකරයෙන් කැණීම් කරන ග්‍රැෆයිට් හා මැණික් පාෂාණ සිමෙන්ති සෑදීමට ප්‍රධාන අමුද්‍රව්‍ය වීම",
        "මුහුදු වැලි පමණක් තාපනය කර අනෙකුත් කිසිදු ඛනිජ ද්‍රව්‍යයකින් තොරව සිමෙන්ති නිපදවිය හැකි වීම",
        "අධික වර්ෂාපතනය නිසා සිමෙන්ති කුඩු කම්හල් තුළම තෙතමනය රඳවා ගැනීමට පහසු වීම",
        "හුණුගල් හා මැටි ප්‍රවාහනය මිල අධික බැවින් අමුද්‍රව්‍ය ආසන්නයේ සිමෙන්ති කම්හල් පිහිටුවයි."),
      q(t, "විශාල නගර මධ්‍යයේ පිහිටි පැරණි කර්මාන්තශාලා නගරයෙන් පිටත උප නාගරික කාර්මික කලාප වෙත ගෙන යාමට බලපාන හේතු මොනවාද?",
        "නගරයේ ඉඩම් කුලිය ඉහළ යාම, මාර්ග තදබදය, පුළුල් කිරීමට ඉඩ නොමැති වීම හා පරිසර නීති දැඩි වීම",
        "නාගරික ප්‍රදේශවල විදුලි සැපයුම සහ මහාමාර්ග පද්ධති ග්‍රාමීය ප්‍රදේශවලට වඩා ඉතා අඩු මට්ටමක පැවතීම",
        "පාරිභෝගිකයන් නගරවලින් සම්පූර්ණයෙන් ඉවත් වී ගැඹුරු වනාන්තර තුළ පදිංචි වීමට පටන් ගැනීම",
        "නගරයේ සේවක වැටුප් ශූන්‍ය මට්ටමක පැවතීම නිසා පුහුණු ශ්‍රමිකයන් සොයා ගැනීමට පහසු වීම",
        "මෙම ක්‍රියාවලිය මගින් ප්‍රධාන නගර වටා සැලසුම් කළ කාර්මික උද්‍යාන බිහි වේ."),
      q(t, "ශ්‍රී ලංකාවේ උතුරු හා නැගෙනහිර වෙරළබඩ ග්‍රාමීය ආර්ථිකයේදී 'තල් ගස' (Palmyrah Palm) බහු-ආර්ථික සම්පතක් ලෙස වැදගත් වන්නේ ඇයි?",
        "තල් හකුරු, පැණි, කිලංගු, තල් රෙදිපිළි කෙඳි, වට්ටි-පෙට්ටි හස්ත කර්මාන්ත හා දැව සපයන බැවින්",
        "තල් ගස් මුහුදු ජලය තුළ පමණක් වැඩෙමින් කොරල් පර නිර්මාණය කිරීමට දායක වන බැවින්",
        "තල් ඵලදාව මගින් රටට අවශ්‍ය සමස්ත ඉන්ධන හා ගෑස් අවශ්‍යතාව සම්පූර්ණයෙන් සපුරාලන බැවින්",
        "තල් ගස සීතල කඳුකරයේ පමණක් වැවෙන බැවින් උඩරට තේ වතු සඳහා සෙවණ සපයන බැවින්",
        "වියළි දේශගුණයට ඔරොත්තු දෙන තල් ශාකය යාපනය හා මන්නාරම ප්‍රදේශවල ජන ජීවිතය හා බැඳී පවතී."),
      q(t, "මහවැලි සංවර්ධන කලාප (H, B, C, G, L) ශ්‍රී ලංකාවේ කෘෂි ආර්ථික භූගෝල විද්‍යාව තුළ ඉටු කරන ප්‍රධාන කාර්යභාරය කුමක්ද?",
        "වාරි ජලය සපයා යල-මහ කන්න දෙකේම වී වගාවත් මිරිස්, ලොකු ලූනු හා බඩ ඉරිඟු වගාවත් දියුණු කිරීම",
        "උඩරට ඉහළ කඳුකරයේ තේ වගා කර්මාන්තශාලා සඳහා පමණක් දැව හා අඟුරු සැපයීම සිදු කිරීම",
        "දකුණු මුහුදු තීරයේ ගැඹුරු මුහුදු ධීවර වරායන් සඳහා අයිස් හා ඉන්ධන සැපයීම සිදු කිරීම",
        "නාගරික තොරතුරු තාක්ෂණ උද්‍යාන හා අභ්‍යවකාශ පර්යේෂණාගාර ඉදිකිරීම සඳහා ඉඩම් වෙන් කිරීම",
        "මහවැලි ගංගා ජලය වියළි කලාපයට හැරවීම මෙරට සහල් ස්වයංපෝෂිතභාවයට ප්‍රධාන හේතුවක් විය."),
      q(t, "උතුරු ඇමෙරිකාවේ ප්‍රේරි හා යුක්රේනයේ ස්ටෙප්ස් තෘණ බිම් ලොව ප්‍රධාන තිරිඟු නිෂ්පාදන කලාප බවට පත්වීමට පාංශුමය හේතුව කුමක්ද?",
        "හියුමස් බහුල අතිශය සාරවත් 'චර්නොසෙම්' (කළු පස) සමතලා තැනිතලා පුරා විහිදී පැවතීම",
        "වසර පුරා ගලා යන ලාවා මගින් දෛනිකව නව ගිනිකඳු අළු තට්ටු පස මත තැන්පත් වීම",
        "පස සම්පූර්ණයෙන්ම රළු තිරිවානා වැලිවලින් සෑදී ඇති බැවින් වතුර රැඳීමක් සිදු නොවීම",
        "අධික ලවණතාවෙන් යුත් වෙරළබඩ මඩ පස තිරිඟු ශාකයේ වර්ධනයට වඩාත් හිතකර වීම",
        "සමතලා භූමිය හා සාරවත් පස නිසා විශාල යන්ත්‍රසූත්‍ර යොදා මහා පරිමාණ වගාව කළ හැකිය."),
      q(t, "ප්‍රධාන ධාන්‍ය හා පොහොර අපනයන කලාපවල (උදා: කළු මුහුදු කලාපයේ) යුද ගැටුම් ඇති වූ විට ගෝලීය ආහාර මිල ඉහළ යන්නේ ඇයි?",
        "ලෝක තිරිඟු, සූරියකාන්ත තෙල් හා රසායනික පොහොර සැපයුමෙන් විශාල කොටසක් එම කලාපයෙන් නැව්ගත වන බැවින්",
        "වෙනත් කිසිදු මහාද්වීපයක වී, බඩ ඉරිඟු හෝ එළවළු වගා කිරීමට කිසිවෙකුට අවසර නොමැති බැවින්",
        "යුද ගැටුම් පවතින කාලයේදී ලෝකයේ සියලුම සාගරවල සුළං හා වර්ෂාව සම්පූර්ණයෙන් නතර වන බැවින්",
        "සෑම රටක්ම තම කෘෂිකාර්මික ඉඩම් සියල්ල වහාම කර්මාන්තශාලා බවට පරිවර්තනය කරන බැවින්",
        "භූ-දේශපාලනික අර්බුද ගෝලීය ආහාර සැපයුම් දාම හා පොහොර මිල කෙරෙහි ක්ෂණිකව බලපායි."),
      q(t, "ජපානයේ හොක්කයිඩෝ සහ කැනඩාවේ නිව්ෆවුන්ඩ්ලන්ඩ් (Grand Banks) අවට මුහුදු ප්‍රදේශ ලොව පොහොසත්ම මත්ස්‍ය කලාප බවට පත්ව ඇත්තේ ඇයි?",
        "උණුසුම් හා ශීතල සාගර දියවැල් හමුවීමෙන් ප්ලවාංග බහුල වන නොගැඹුරු මහාද්වීපික තටාක පිහිටීම",
        "එම මුහුදු ප්‍රදේශ සමකය ආසන්නයේ පිහිටි ඉතා ගැඹුරු උණුසුම් ජල තටාක වන බැවින්",
        "වසර පුරාම මුහුදු මතුපිට ඝන අයිස් තට්ටුවකින් වැසී ඇති බැවින් මසුන්ට ආරක්ෂාව සැලසීම",
        "ගොඩබිමෙන් ගලා එන කර්මාන්තශාලා රසායනික අපද්‍රව්‍ය මසුන්ගේ ප්‍රධාන ආහාරය බවට පත්ව ඇති බැවින්",
        "සාගර දියවැල් හමුවන ස්ථානවල පෝෂ්‍ය පදාර්ථ ඉහළට එසවී මත්ස්‍ය ගහනය ඉහළ නංවයි."),
      q(t, "ගල් අඟුරු, ධාන්‍ය හා ඛනිජ තෙල් වැනි බරින් වැඩි තොග භාණ්ඩ (Bulk Cargo) ප්‍රවාහනයට සාගර නාවික ප්‍රවාහනය හා දුම්රිය ප්‍රවාහනය වඩාත් සුදුසු වන්නේ ඇයි?",
        "ටොන්-කිලෝමීටරයකට වැය වන ඉන්ධන හා ප්‍රවාහන පිරිවැය ගුවන් හා මාර්ග ප්‍රවාහනයට වඩා අඩු බැවින්",
        "නාවික යාත්‍රා හා දුම්රිය ගුවන් යානාවලට වඩා කිහිප ගුණයකින් වේගවත් ගමනාගමනයක් සපයන බැවින්",
        "තොග භාණ්ඩ නැව් මගින් ගෙන යාමේදී කිසිදු වරායක ගබඩා පහසුකම් හෝ දොඹකර අවශ්‍ය නොවන බැවින්",
        "මහාමාර්ගවල ගමන් ගන්නා ලොරි රථවලට කිසිදු ඝන හෝ ද්‍රව භාණ්ඩයක් පැටවීම නීතියෙන් තහනම් බැවින්",
        "නාවික ප්‍රවාහනය මන්දගාමී වුවද විශාල පරිමාණ භාණ්ඩ අඩු වියදමකින් රටවල් අතර ගෙන යාමට උපකාරී වේ."),
      q(t, "ගුවන් භාණ්ඩ ප්‍රවාහනය (Air Cargo) ඉතා මිල අධික වුවද කැපූ මල්, ඖෂධ, මයික්‍රොචිප් හා නැවුම් මසුන් සඳහා බහුලව භාවිත කරන්නේ ඇයි?",
        "බරින් අඩු නමුත් ඉහළ වටිනාකමක් ඇති හෝ ඉක්මනින් නරක් වන භාණ්ඩ කඩිනමින් වෙළඳපොළට යැවීමට",
        "ගුවන් යානාවලින් ගඩොල්, වැලි, සිමෙන්ති හා ගල් අඟුරු ලාභදායී ලෙස ප්‍රවාහනය කළ හැකි බැවින්",
        "ගුවන් තොටුපළවල් සෑම ගමකම ඉදිකර ඇති බැවින් ගොවීන්ට සෘජුවම ගොවිපළේ සිට පැටවීමට හැකි බැවින්",
        "නැව් මගින් ප්‍රවාහනය කරන සෑම භාණ්ඩයක්ම රේගුව විසින් මුහුදේදී විනාශ කර දමන බැවින්",
        "ඉක්මනින් කල් ඉකුත් වන හා සුඛෝපභෝගී භාණ්ඩ සඳහා ගුවන් ප්‍රවාහනය ඉතා වැදගත් වේ."),
      q(t, "කලාපීය ආර්ථික ඒකාබද්ධතාවයේදී 'නිදහස් වෙළඳ ප්‍රදේශය' (FTA) සහ 'පොදු වෙළඳපොළ' (Common Market) අතර ඇති ප්‍රධාන වෙනස කුමක්ද?",
        "නිදහස් වෙළඳ ප්‍රදේශයේ තීරු බදු ඉවත් කරන අතර පොදු වෙළඳපොළේ ප්‍රාග්ධනය හා ශ්‍රමයද නිදහසේ සංචරණය වේ",
        "නිදහස් වෙළඳ ප්‍රදේශයේ සියලු දේශසීමා ඉවත් කරන අතර පොදු වෙළඳපොළේ වෙළඳාම තහනම් කරයි",
        "පොදු වෙළඳපොළ තුළ සාමාජික රටවල් අතර තීරු බදු දස ගුණයකින් ඉහළ නැංවීම අනිවාර්ය නීතියකි",
        "දෙකෙහිම කිසිදු වෙනසක් නොමැති අතර ඒවා කෘෂිකාර්මික ඉඩම් මැනීමේ මිනුම් දෙකක් පමණි",
        "යුරෝපා සංගමය යනු පොදු වෙළඳපොළක් හා පොදු මුදල් ඒකකයක් දක්වා වර්ධනය වූ කලාපීය සංවිධානයකි."),
      q(t, "ශ්‍රී ලංකාවේ සංචාරක ව්‍යාපාරයේ ඍතුමය බව (Seasonality) බටහිර-දකුණු වෙරළ හා නැගෙනහිර වෙරළ අතර වෙනස් වන්නේ කෙසේද?",
        "නොවැම්බර්–අප්‍රේල් කාලයේ දකුණු/බටහිර වෙරළද මැයි–සැප්තැම්බර් කාලයේ නැගෙනහිර වෙරළද වඩාත් හිතකර වීම",
        "වසරේ සෑම මාසයකම දිවයිනේ සියලුම වෙරළ තීරවල එකවර තද කුණාටු හා අධික වර්ෂාව පැවතීම",
        "නැගෙනහිර වෙරළට කිසිදු මෝසම් සුළඟක් නොලැබෙන බැවින් වසර පුරාම හිම පතනයක් සිදු වීම",
        "බටහිර වෙරළේ මුහුදු ජලය ශීත කාලයේදී සම්පූර්ණයෙන් මිදී යන බැවින් සංචාරකයන් නොපැමිණීම",
        "ද්වි-මෝසම් දේශගුණික රටාව නිසා ශ්‍රී ලංකාව වසර පුරාම සංචාරක ගමනාන්තයක් ලෙස පවතී."),
      q(t, "තලවකැලේ තේ, අගලවත්ත රබර් හා ලුණුවිල පොල් පර්යේෂණ ආයතන ශ්‍රී ලංකාවේ වැවිලි ආර්ථිකයට දායක වන්නේ කෙසේද?",
        "වැඩි අස්වනු ලබා දෙන, නියඟයට හා රෝගවලට ඔරොත්තු දෙන නව ප්‍රභේද බිහි කර වගා උපදෙස් ලබා දීමෙන්",
        "සියලුම පැරණි තේ, රබර් හා පොල් වගාවන් කපා ඉවත් කර ඒ වෙනුවට නගර ඉදිකිරීමට උපදෙස් දීමෙන්",
        "රසායනික පොහොර භාවිතය දස ගුණයකින් ඉහළ දමා පාංශු ඛාදනය වේගවත් කිරීමට කටයුතු කිරීමෙන්",
        "වැවිලි භෝග අපනයනය සම්පූර්ණයෙන් නතර කර දේශීය වෙළඳපොළේ පමණක් අලෙවි කිරීමට නීති සැකසීමෙන්",
        "විද්‍යාත්මක පර්යේෂණ මගින් අපනයන භෝගවල ගුණාත්මකභාවය හා තරඟකාරිත්වය ආරක්ෂා වේ."),
      q(t, "විදේශ රැකියාවල නියුතු ශ්‍රී ලාංකිකයන් මෙරටට එවන 'විදේශ ප්‍රේෂණ' (Workers' Remittances) ජාතික ආර්ථිකයට වැදගත් වන්නේ ඇයි?",
        "රටේ විදේශ විනිමය සංචිත ශක්තිමත් කර ආනයන වියදම් පියවීමට හා පවුල් ආදායම වැඩි කිරීමට උපකාරී වීම",
        "විදේශ මුදල් රටට ලැබීම නිසා දේශීය බැංකු පද්ධතියේ මුදල් සංසරණය සම්පූර්ණයෙන් නතර වන බැවින්",
        "විදේශ ප්‍රේෂණ මගින් රටේ තේ හා ඇඟලුම් අපනයන නිෂ්පාදන සියල්ල නොමිලේ විදේශයන්ට යැවෙන බැවින්",
        "ග්‍රාමීය ප්‍රදේශවල සියලුම පාසල් හා රෝහල් ස්ථිරවම වසා දැමීමට රජයට හැකියාව ලැබෙන බැවින්",
        "නුපුහුණු ශ්‍රමය වෙනුවට වෘත්තීය පුහුණුව ලත් නිපුණ ශ්‍රමිකයන් විදේශ රැකියාවලට යොමු කිරීම වඩා ලාභදායී වේ."),
      q(t, "දකුණු ආසියානු නගරවල වීදි වෙළඳාම හා දෛනික කුලී රැකියා වැනි 'අවිධිමත් ආර්ථික අංශය' විශාල වීමට ප්‍රධාන හේතුව කුමක්ද?",
        "විධිමත් කාර්මික හා කාර්යාල අංශයට සියලු නාගරික ශ්‍රමිකයන් අවශෝෂණය කර ගැනීමට නොහැකි වීම",
        "නගරයේ ජීවත් වන සියලුම පුරවැසියන්ට රජය විසින් ස්ථිර කාර්යාල රැකියා නීතියෙන් තහනම් කර තිබීම",
        "කර්මාන්තශාලා සියල්ල කඳු මුදුන්වලට ගෙන ගොස් ඇති බැවින් නගර තුළ කිසිදු ව්‍යාපාරයක් නොපැවතීම",
        "අවිධිමත් අංශයේ සෑම සේවකයෙකුටම විධිමත් අංශයට වඩා වැඩි විශ්‍රාම වැටුපක් හා රක්ෂණයක් ලැබීම",
        "නගරයට සංක්‍රමණය වන පිරිසට කුඩා ප්‍රාග්ධනයකින් ඉක්මන් ජීවනෝපායක් සොයා ගැනීමට මෙම අංශය උපකාරී වේ."),
      q(t, "ශ්‍රී ලංකාවේ බතික්, පිත්තල, වේවැල් හා බීරළු රේන්ද වැනි සාම්ප්‍රදායික හස්ත කර්මාන්ත ප්‍රවර්ධනය කිරීම වැදගත් වන්නේ ඇයි?",
        "දේශීය අමුද්‍රව්‍ය හා ශිල්පීය කුසලතා සංචාරක වෙළඳපොළට සම්බන්ධ කර ග්‍රාමීය පවුල් ආදායම වැඩි කිරීමට",
        "පාරම්පරික ශිල්පීය දැනුම සම්පූර්ණයෙන් අමතක කර ආනයනික ප්ලාස්ටික් භාණ්ඩ පමණක් ප්‍රචලිත කිරීමට",
        "මහා පරිමාණ වානේ හා රසායනික කම්හල් සියල්ල ග්‍රාමීය නිවාස තුළ ස්ථාපිත කිරීමට පියවර ගැනීමට",
        "අපනයන ආදායම අඩු කර ගනිමින් රටේ විදේශ විනිමය සංචිත සියල්ල වියදම් කර අවසන් කිරීමට",
        "පිළිමතලාවේ පිත්තල, ගාල්ලේ බීරළු රේන්ද හා මාතලේ බතික් මෙරට සංස්කෘතික කර්මාන්ත පොකුරු වේ."),
      q(t, "ශ්‍රී ලංකාවේ කෘෂි වෙළඳාමේදී 'දඹුල්ල විශේෂිත ආර්ථික මධ්‍යස්ථානය' ප්‍රධාන තොග මධ්‍යස්ථානයක් බවට පත්වීමට බලපෑ භූගෝලීය වාසිය කුමක්ද?",
        "දිවයිනේ මධ්‍යම පිහිටීම නිසා විවිධ කලාපවල එළවළු හා පලතුරු එක්රැස් කර රට පුරා බෙදා හැරීමට පහසු වීම",
        "දඹුල්ල ප්‍රදේශයේ විශාල ගැඹුරු සාගර වරායක් හා ජාත්‍යන්තර ගුවන් තොටුපළක් පිහිටා තිබීම",
        "මුළු දිවයිනේම එළවළු වගා කිරීම දඹුල්ල නගර සීමාව තුළ පමණක් නීතියෙන් අවසර දී තිබීම",
        "එහි ශීතාගාර නොමැති වුවද වසර පුරාම පොළොව මතුපිට හිම වැටී තිබීමෙන් අස්වැන්න නරක් නොවීම",
        "ගොවීන්ට හා වෙළෙන්දන්ට සෘජුවම හමුවීමෙන් අතරමැදි ප්‍රවාහන පිරිවැය අඩු කර ගත හැකිය."),
      q(t, "ජපානයේ ෂින්කන්සෙන් හා ප්‍රංශයේ TGV වැනි අධිවේගී දුම්රිය ජාල රටක ආර්ථික භූගෝල විද්‍යාවට බලපාන්නේ කෙසේද?",
        "ප්‍රධාන නගර අතර ගමන් කාලය කෙටි කර කලාපීය ව්‍යාපාර, සේවා හා ශ්‍රම වෙළඳපොළවල් ඒකාබද්ධ කිරීම",
        "ප්‍රාදේශීය නගර හුදකලා කර ජනතාවට එක් ප්‍රදේශයකින් තවත් ප්‍රදේශයකට ගමන් කිරීම අසීරු කිරීම",
        "ගුවන් යානා සහ මුහුදු නැව් මගින් සිදු කරන සියලුම ජාත්‍යන්තර භාණ්ඩ ආනයන සම්පූර්ණයෙන් නතර කිරීම",
        "මහාමාර්ග ජාලය අවලංගු කර කෘෂිකාර්මික ඉඩම් සියල්ල දුම්රිය ස්ථාන බවට පරිවර්තනය කිරීම",
        "අඩු කාබන් විමෝචනයකින් කෙටි හා මධ්‍යම දුර ගමන් සඳහා අධිවේගී දුම්රිය විශාල දායකත්වයක් සපයයි."),
      q(t, "ලෝක මෝටර් රථ නිෂ්පාදන කර්මාන්තයේ ප්‍රමුඛත්වය බටහිර රටවල සිට චීනය, ජපානය, දකුණු කොරියාව හා ඉන්දියාව වෙත යොමු වූයේ ඇයි?",
        "ආසියාවේ විශාල පාරිභෝගික වෙළඳපොළ, කාර්යක්ෂම සැපයුම් ජාල, නිපුණ ශ්‍රමය හා කාර්මික ප්‍රතිපත්ති නිසා",
        "යුරෝපයේ හා උතුරු ඇමෙරිකාවේ ජනතාව මෝටර් රථ වෙනුවට අශ්ව කරත්ත භාවිතයට ආපසු ගිය නිසා",
        "ආසියානු කලාපයේ මහාමාර්ග පද්ධතියක් නොතිබුණද නවීන වාහන අහසින් පියාසර කිරීමට හැකි වූ නිසා",
        "බටහිර රටවල වානේ, රබර් හා විදුලිය භාවිතය සම්පූර්ණයෙන්ම තහනම් කර තිබූ බැවින්",
        "වර්තමානයේ විදුලි වාහන හා බැටරි නිෂ්පාදනයේදීද නැගෙනහිර ආසියාව ප්‍රමුඛ ස්ථානයක් ගනී."),
      q(t, "ශ්‍රී ලංකාවේ දේශීය කිරි ගව පාලනය හා නැවුම් කිරි නිෂ්පාදනය වැඩි දියුණු කිරීමෙන් ලැබෙන ප්‍රධාන ආර්ථික වාසිය කුමක්ද?",
        "කිරිපිටි ආනයනයට වැය වන විදේශ විනිමය ඉතිරි කර ග්‍රාමීය ගොවි පවුල්වලට දෛනික ආදායමක් ලබා දීම",
        "විදේශ විනිමය සංචිත වේගයෙන් වැය කරමින් දේශීය ගොවීන් කෘෂිකර්මයෙන් සම්පූර්ණයෙන් ඉවත් කිරීම",
        "දිවයිනේ සියලුම තෘණ බිම් ඉවත් කර ඒ වෙනුවට කාර්මික කලාප හා මහල් නිවාස ගොඩනැගීම",
        "නැවුම් කිරි පරිභෝජනය සම්පූර්ණයෙන් නතර කර පිටරටින් ආනයනය කරන පාන වර්ග පමණක් ප්‍රචලිත කිරීම",
        "නුවරඑළිය, කුරුණෑගල, අනුරාධපුර හා අම්පාර දිස්ත්‍රික්ක දේශීය කිරි කර්මාන්තයේ වැදගත් කලාප වේ."),
      q(t, "ශ්‍රී ලංකාවේ රත්නපුර හා ඇළහැර මැණික් කර්මාන්තයේදී රළු මැණික් කපා ඔප දමා ස්වර්ණාභරණ ලෙස අපනයනය කිරීම වැදගත් වන්නේ ඇයි?",
        "අමු ගල් අපනයනයට වඩා ඉහළ අගයක් එකතු වීමෙන් වැඩි විදේශ විනිමය ප්‍රමාණයක් හා රැකියා උපයා ගත හැකි බැවින්",
        "කපා ඔප දැමූ මැණික් ගල්වල වටිනාකම අමු ගල්වල වටිනාකමට වඩා විශාල ලෙස පහත වැටෙන බැවින්",
        "රළු මැණික් කැපීමෙන් පසු ඒවායේ ස්වාභාවික වර්ණය හා දෘඪතාව සම්පූර්ණයෙන් නැති වී යන බැවින්",
        "මැණික් හා ස්වර්ණාභරණ කර්මාන්තය සඳහා කිසිදු ශිල්පීය පුහුණුවක් හෝ නිර්මාණ හැකියාවක් අවශ්‍ය නොවන බැවින්",
        "ශ්‍රී ලංකාවේ නිල් මැණික් ලෝක වෙළඳපොළේ ඉහළම කීර්තියක් හිමි ඛනිජ සම්පතකි."),
      q(t, "ජාත්‍යන්තර වෙළඳාමේදී 'ලෝක වෙළඳ සංවිධානය' (WTO) ඉටු කරන ප්‍රධාන කාර්යභාරය කුමක්ද?",
        "රටවල් අතර වෙළඳ නීති සම්පාදනය කිරීම, තීරු බදු බාධක අඩු කිරීමට සාකච්ඡා කිරීම හා ආරවුල් විසඳීම",
        "ලෝකයේ සියලුම සාගර නැව් හා ගුවන් යානාවල ටිකට් ගාස්තු හා මගී ගමන් වාර නියම කිරීම",
        "සාමාජික රටවල දේශසීමා අහෝසි කර සියලුම රටවලට එකම පොදු මුදල් ඒකකයක් හඳුන්වා දීම",
        "විදේශීය භාණ්ඩ ආනයනය හා අපනයනය සම්පූර්ණයෙන්ම තහනම් කර රටවල් හුදකලා කිරීම",
        "කෙසේ වෙතත් සංවර්ධනය වෙමින් පවතින රටවල කුඩා ගොවීන් ආරක්ෂා කිරීම සඳහා සාධාරණ වෙළඳ නීති අවශ්‍ය වේ."),
      q(t, "'ආනයන ආදේශන කර්මාන්තකරණය' හා 'අපනයනාභිමුඛ කර්මාන්තකරණය' අතර ඇති ප්‍රධාන ප්‍රතිපත්තිමය වෙනස කුමක්ද?",
        "ආනයන ආදේශනය රට තුළ භාණ්ඩ නිපදවා ආනයන අඩු කරන අතර අපනයනාභිමුඛ ක්‍රමය ගෝලීය වෙළඳපොළ ඉලක්ක කරයි",
        "ආනයන ආදේශනය සියලු භාණ්ඩ විදේශයෙන් මිලදී ගන්නා අතර අපනයනාභිමුඛ ක්‍රමය අපනයන නතර කරයි",
        "මෙම ක්‍රම දෙකම රටේ කර්මාන්තශාලා සියල්ල වසා දමා කෘෂිකර්මය පමණක් කිරීමට අවධාරණය කරයි",
        "ආනයන ආදේශනය තීරු බදු සම්පූර්ණයෙන් ඉවත් කරන අතර අපනයනාභිමුඛ ක්‍රමය රේගු බදු දෙගුණ කරයි",
        "නැගෙනහිර ආසියානු රටවල් අපනයනාභිමුඛ කාර්මික ප්‍රතිපත්තිය මගින් වේගවත් ආර්ථික වර්ධනයක් ලැබීය."),
      q(t, "ශ්‍රී ලංකාවේ වියළි කලාපීය ගොවිපළවල බිංදු ජල සම්පාදනය (Drip Irrigation) හා විසිරි ජල ක්‍රම භාවිත කිරීමේ ආර්ථික වාසිය කුමක්ද?",
        "ජල නාස්තිය අවම කර ශාක මුල් පද්ධතියට අවශ්‍ය තෙතමනය හා පොහොර කාර්යක්ෂමව ලබා දීම",
        "කුඹුරු හා එළවළු බිම් මුළුමනින්ම ජලයෙන් යට කර ගංවතුර තත්ත්වයක් කෘත්‍රිමව නිර්මාණය කිරීම",
        "ජල සම්පාදනය සඳහා වැය වන විදුලි හා ඉන්ධන වියදම දස ගුණයකින් ඉහළ නැංවීමට උපකාරී වීම",
        "පසේ ඇති සියලුම ඛනිජ පෝෂක සෝදා හැර වගා බිම් ඉක්මනින් නිසරු කිරීමට ක්‍රියා කිරීම",
        "ජල හිඟය පවතින කල්පිටිය, යාපනය හා පුත්තලම ප්‍රදේශවල මෙම ක්‍රම ඉතා සාර්ථකව භාවිත වේ."),
      q(t, "ශ්‍රී ලංකාවේ නිදහස් වෙළඳ කලාප හා තොරතුරු තාක්ෂණ උද්‍යාන බොහොමයක් කොළඹ-ගම්පහ කලාපය ආශ්‍රිතව පිහිටුවා ඇත්තේ ඇයි?",
        "වරාය, ජාත්‍යන්තර ගුවන් තොටුපළ, අධිවේගී මාර්ග, විදුලි පද්ධති හා පුහුණු ශ්‍රමයට පහසු ප්‍රවේශය නිසා",
        "දිවයිනේ අනෙකුත් කිසිදු පළාතක ඉඩම් හෝ මානව සම්පත් කර්මාන්ත සඳහා නොමැති බැවින්",
        "බස්නාහිර පළාතේ පමණක් විදුලි බලය හා අන්තර්ජාල පහසුකම් නිෂ්පාදනය කිරීම නීතියෙන් සීමා කර ඇති බැවින්",
        "එම කලාපයේ වැඩිම තේ, රබර් හා වී වගා බිම් ප්‍රමාණය සංකේන්ද්‍රණය වී තිබීම හේතුවෙන්",
        "කලාපීය සමතුලිතතාව සඳහා දැන් අනෙකුත් පළාත්වලද ප්‍රාදේශීය කාර්මික හා තාක්ෂණික උද්‍යාන ඉදි කෙරේ."),
      q(t, "රටක මුදල් ඒකකයේ විනිමය අනුපාතිකය අවප්‍රමාණය වීම විදේශ වෙළඳාමට බලපාන ආකාරය කුමක්ද?",
        "අපනයන භාණ්ඩ විදේශ වෙළඳපොළේ තරඟකාරී වුවද ආනයනික යන්ත්‍රසූත්‍ර, ඉන්ධන හා අමුද්‍රව්‍ය මිල ඉහළ යයි",
        "විනිමය අනුපාතිකය වෙනස් වීම කිසිදු ආකාරයකින් ආනයන හෝ අපනයන මිල කෙරෙහි බල නොපායි",
        "ආනයනික ඉන්ධන හා පොහොර මිල ඉතා විශාල ලෙස පහත වැටී ගොවීන්ට නොමිලේ ලැබීමට පටන් ගනී",
        "රටේ සියලුම අපනයන භාණ්ඩ විදේශ වෙළඳපොළේ අලෙවි කිරීම නීතියෙන් තහනම් කරනු ලැබේ",
        "සාර්ව ආර්ථික ස්ථාවරත්වය විදේශ ආයෝජන ආකර්ෂණය කර ගැනීමට ඉතා වැදගත් වේ."),
      q(t, "ග්‍රාමීය වී ගොවීන්ගෙන් අස්වැන්න මිලදී ගෙන ගබඩා කිරීම සඳහා රජයේ වී අලෙවි මණ්ඩලය හා ගබඩා පද්ධති පැවතීම වැදගත් වන්නේ ඇයි?",
        "අස්වනු නෙළන සමයේ මිල පහත වැටීමෙන් ගොවීන් ආරක්ෂා කර සහල් හිඟ කාලයට ආරක්ෂිත තොග තබා ගැනීමට",
        "අස්වැන්න නෙළා ගත් වහාම ගොවීන් ලවා සියලුම වී තොග විනාශ කර දැමීම සංවිධානය කිරීමට",
        "පෞද්ගලික අතරමැදියන්ට ඉතා අඩු මිලට ගොවීන්ගෙන් වී ලබා ගැනීමට නීතිමය පහසුකම් සැලසීමට",
        "වී වගාව සම්පූර්ණයෙන් නතර කර ඒ වෙනුවට සියලුම සහල් විදේශයෙන් ආනයනය කිරීම දිරිමත් කිරීමට",
        "නවීන ශීතාගාර හා වියළි ගබඩා පහසුකම් දියුණු කිරීමෙන් පසු-අස්වනු හානිය විශාල ලෙස අඩු කළ හැකිය."),
      q(t, "යුරෝපය හා ජපානය වැනි රටවලට ආහාර හා කුළුබඩු අපනයනය කිරීමේදී ISO හා HACCP වැනි ප්‍රමිති සහතික අවශ්‍ය වන්නේ ඇයි?",
        "ආහාර සුරක්ෂිතතාව, සනීපාරක්ෂාව හා කෘමිනාශක අවශේෂ සීමා සපුරා ඇති බව ගැනුම්කරුවන්ට තහවුරු කිරීමට",
        "තීරු බදු පමණක් ගෙවූ විට නිෂ්පාදනවල ගුණාත්මකභාවය හෝ පිරිසිදුකම කිසිවෙකු පරීක්ෂා නොකරන බැවින්",
        "අපනයන භාණ්ඩවල බර ප්‍රමාණය කෘත්‍රිමව වැඩි කර පෙන්වීම සඳහා රසායනික ද්‍රව්‍ය එකතු කිරීමට",
        "නිසි ඇසුරුම්වලින් තොරව විවෘත නැව් තට්ටු මත කුළුබඩු අපනයනය කිරීමට අවසර ලබා ගැනීමට",
        "ජාත්‍යන්තර ප්‍රමිති පවත්වා ගැනීම ශ්‍රී ලංකාවේ අපනයන සන්නාමය විශ්වාසනීයව ගොඩනගයි."),
      q(t, "කෘෂිකාර්මික ආර්ථිකයක සිට තාක්ෂණික හා සේවා ආර්ථිකයකට මාරු වීමේදී වෘත්තීය හා කාර්මික පුහුණු ආයතන (TVET) වැදගත් වන්නේ ඇයි?",
        "නවීන කර්මාන්ත හා විදේශ රැකියා වෙළඳපොළ ඉල්ලා සිටින තාක්ෂණික හා ඩිජිටල් කුසලතා තරුණයන්ට ලබා දීමට",
        "සියලුම තරුණ පරපුර සාම්ප්‍රදායික නුපුහුණු කම්කරු රැකියාවලට පමණක් සීමා කර තබා ගැනීමට",
        "පාසල් හා විශ්වවිද්‍යාල අධ්‍යාපනය තුළින් විද්‍යාව හා තාක්ෂණික විෂයන් සම්පූර්ණයෙන් ඉවත් කිරීමට",
        "කර්මාන්තශාලා තුළ නවීන යන්ත්‍රසූත්‍ර භාවිතය නතර කර අත් ආයුධ පමණක් භාවිත කිරීම ප්‍රචලිත කිරීමට",
        "නිපුණ මානව සම්පත නූතන ආර්ථික සංවර්ධනයේ වැදගත්ම ප්‍රාග්ධන සාධකය වේ."),
      q(t, "ශ්‍රී ලංකාවේ බඩ ඉරිඟු, කුකුළු පාලනය හා එළවළු අංශවල ක්‍රියාත්මක වන 'කොන්ත්‍රාත් ගොවිතැන' (Contract Farming) ක්‍රමයෙන් ගොවීන්ට ලැබෙන වාසිය කුමක්ද?",
        "සමාගමක් මගින් බීජ හා උපදෙස් සපයා පූර්ව එකඟ වූ මිලකට අස්වැන්න මිලදී ගැනීමෙන් වෙළඳපොළ අවදානම අඩු වීම",
        "ගොවීන්ගේ කෘෂිකාර්මික ඉඩම් සියල්ල සින්නක්කරවම විදේශීය සමාගම්වලට පවරා දීමට සිදු වීම",
        "අස්වැන්න නෙළීමෙන් පසු කිසිදු ගැනුම්කරුවෙකු නොමැතිව ගොවිපළ තුළම නරක් වීමට ඉඩ හැරීම",
        "ගොවීන්ට කිසිදු මුදල් ගෙවීමකින් තොරව සමාගමට අස්වැන්න නොමිලේ ලබා දීමට නීතියෙන් බැඳී සිටීම",
        "නිසි ගුණාත්මකභාවය පවත්වා ගනිමින් ස්ථාවර ආදායමක් ලබා ගැනීමට මෙම ක්‍රමය ගොවීන්ට උපකාරී වේ."),
      q(t, "ශ්‍රී ලංකාවේ 'ගැඹුරු මුහුදු බහුදින ධීවර යාත්‍රා' සහ 'වෙරළාසන්න සුළු පන්න යාත්‍රා' අතර ඇති ප්‍රධාන ආර්ථික වෙනස කුමක්ද?",
        "බහුදින යාත්‍රා සති ගණන් ගැඹුරු මුහුදේ අපනයන මසුන් අල්ලන අතර සුළු පන්න යාත්‍රා දෛනික වෙළඳපොළට සපයයි",
        "සුළු පන්න යාත්‍රා ඇන්ටාක්ටික් සාගරය දක්වා ගමන් කරන අතර බහුදින යාත්‍රා වැව්වල පමණක් ධීවර කටයුතු කරයි",
        "බහුදින යාත්‍රා මගින් කෘෂිකාර්මික පොහොර ප්‍රවාහනය කරන අතර සුළු පන්න යාත්‍රා මගීන් පමණක් ප්‍රවාහනය කරයි",
        "මෙම යාත්‍රා වර්ග දෙකම ශ්‍රී ලංකාවේ වරායන් තුළ ක්‍රියාත්මක කිරීම රජය විසින් ස්ථිරවම තහනම් කර ඇත",
        "දික්ඕවිට, ගාල්ල, බේරුවල, මීගමුව, ත්‍රිකුණාමලය හා තංගල්ල මෙරට ප්‍රධාන ධීවර වරායන් වේ."),
      q(t, "පුත්තලම, මීගමුව හා මඩකලපුව වැනි වෙරළබඩ කලපු හා කඩොලාන පද්ධති ග්‍රාමීය ආර්ථිකයට සෘජුවම දායක වන්නේ කෙසේද?",
        "ඉස්සන්, කකුළුවන් හා මසුන් බෝ වන තවාන් බිම් සැපයීම, කොහු පොඟවීම හා පරිසර සංචාරක යාත්‍රා සේවා මගින්",
        "ගැඹුරු පතල් හාරා ගල් අඟුරු හා යකඩ ලෝපස් නිෂ්පාදනය කර කාර්මික කලාපවලට බෙදා හැරීම මගින්",
        "උඩරට කඳුකරයේ තේ හා රබර් වගා කිරීමට අවශ්‍ය සීතල දේශගුණය හා ඛනිජ පස නිර්මාණය කිරීම මගින්",
        "සාගරයේ සිටින සියලුම විශාල මත්ස්‍යයන් වෙරළට ගොඩ ගසා ධීවර කර්මාන්තය අඩාල කිරීම මගින්",
        "කඩොලාන සංරක්ෂණය කිරීම වෙරළ ඛාදනය වැළැක්වීමට මෙන්ම ධීවර ජීවනෝපාය රැක ගැනීමටද ඉතා වැදගත්ය."),
      q(t, "තිරසාර කෘෂිකර්මයේදී 'ඒකාබද්ධ පළිබෝධ කළමනාකරණය' (IPM) භාවිත කිරීමෙන් ගොවීන්ට හා පරිසරයට ලැබෙන ප්‍රතිලාභය කුමක්ද?",
        "ජෛව පාලනය හා කාබනික ක්‍රම මගින් රසායනික කෘමිනාශක වියදමත් පාංශු-ජල දූෂණයත් අඩු කර ගැනීම",
        "වගා බිමේ සිටින සියලුම මී මැස්සන් හා හිතකර කෘමීන් විෂ රසායන ඉස සම්පූර්ණයෙන් විනාශ කර දැමීම",
        "කෘමිනාශක මිලදී ගැනීම සඳහා වැය වන මුදල තුන් ගුණයකින් ඉහළ දමා අස්වැන්න අඩු කර ගැනීම",
        "සෑම වගා කන්නයකම වනාන්තර කොටසක් ගිනි තබා අලුතින් හේන් ගොවිතැනක් ආරම්භ කිරීම",
        "සෞඛ්‍යාරක්ෂිත ආහාර නිෂ්පාදනය හා අපනයන ප්‍රමිති සපුරාලීම සඳහා IPM ක්‍රමය ඉතා යෝග්‍ය වේ."),
      q(t, "ශ්‍රී ලංකාවේ ආයුර්වේද සුවතා සේවා හා වෛද්‍ය සංචාරක ව්‍යාපාරය (Medical & Wellness Tourism) වර්ධනය වීමට හේතුව කුමක්ද?",
        "සාම්ප්‍රදායික හෙළ වෙදකම, ආයුර්වේද ප්‍රතිකාර, යෝගා හා සන්සුන් ස්වාභාවික පරිසරය සඳහා විදේශීය ඉල්ලුම",
        "ලෝකයේ අනෙකුත් සියලුම රටවල රෝහල් හා වෛද්‍ය මධ්‍යස්ථාන සම්පූර්ණයෙන්ම වසා දමා තිබීම",
        "ශ්‍රී ලංකාවේ සංචාරකයන් සඳහා කිසිදු නවාතැන් පහසුකමක් හෝ ගුවන් ප්‍රවාහන සේවාවක් නොපැවතීම",
        "බටහිර රටවලට වඩා කිහිප ගුණයකින් ඉහළ ගාස්තුවක් අය කර කිසිදු සේවාවක් ලබා නොදීම",
        "වැඩි කාලයක් රැඳී සිටින ඉහළ වියදම් දරන සංචාරකයන් ආකර්ෂණය කර ගැනීමට මෙය උපකාරී වේ."),
      q(t, "දකුණු ආසියානු කෘෂිකර්මයේදී 'ඉඩම් කැබලි වීම' (Land Fragmentation) ඵලදායිතාව අඩු කරන අතර එය ජය ගැනීමට ගන්නා ක්‍රියාමාර්ගය කුමක්ද?",
        "පරම්පරා ගණනකට ඉඩම් බෙදී කුඩා වීමෙන් යන්ත්‍ර භාවිතය අපහසු වන බැවින් සමුපකාර 'යාය වගා ක්‍රමය' යෙදීම",
        "සෑම වී කුඹුරක්ම තවත් කුඩා කොටස් දහයකට බෙදා වෙන් කර ගොඩනැගිලි ඉදිකිරීම සිදු කිරීම",
        "කුඩා ඉඩම්වල ට්‍රැක්ටර් හා අස්වනු නෙළන යන්ත්‍ර භාවිත කිරීම නීතියෙන් ස්ථිරවම තහනම් කිරීම",
        "කෘෂිකාර්මික ඉඩම් සියල්ල වගා නොකර අතහැර දමා නගරයේ කුලී රැකියා සොයා යාම",
        "කුඩා ඉඩම් ඒකාබද්ධව වගා කිරීමෙන් ජල කළමනාකරණය හා යාන්ත්‍රිකරණය පහසු වේ."),
      q(t, "ශ්‍රී ලංකාවේ කුකුළු පාලන කර්මාන්තය දේශීය ඉල්ලුමෙන් විශාල කොටසක් සපුරාලීමට සමත් වී ඇත්තේ කුමන නිෂ්පාදන ආකෘතිය නිසාද?",
        "වාණිජ සමාගම් හා ග්‍රාමීය කුඩා ගොවීන් ඒකාබද්ධ වූ 'අවුට්-ග්‍රෝවර්' පැටවුන් හා සැකසුම් ජාලය මගින්",
        "දේශීය කුකුළු ගොවිපළවල් සියල්ල වසා දමා 100% ක්ම බිත්තර හා මස් විදේශයෙන් ආනයනය කිරීමෙන්",
        "සත්ත්ව ආහාර නිෂ්පාදනය සම්පූර්ණයෙන් නතර කර කුකුළන්ට වනාන්තරවල නිදැල්ලේ ආහාර සෙවීමට හැරීමෙන්",
        "ශීතාගාර හා ප්‍රවාහන පහසුකම් භාවිත නොකර නිෂ්පාදන සියල්ල ගොවිපළ තුළම ගබඩා කර තැබීමෙන්",
        "කෙසේ වෙතත් බඩ ඉරිඟු හා සෝයා වැනි සත්ත්ව ආහාර මිල ඉහළ යාම මෙම කර්මාන්තයේ ප්‍රධාන අභියෝගයකි."),
      q(t, "රටකට විදේශ සෘජු ආයෝජන (FDI) ආකර්ෂණය කර ගැනීමට බලපාන ප්‍රධානතම ආයතනික හා යටිතල පහසුකම් සාධක මොනවාද?",
        "ප්‍රතිපත්ති ස්ථාවරත්වය, විනිවිද පෙනෙන නීති, නිපුණ ශ්‍රම බලකාය හා විශ්වසනීය විදුලි-ප්‍රවාහන පද්ධති",
        "සෑම මාස කිහිපයකට වරක් බදු හා වෙළඳ නීති හදිසියේ වෙනස් කර අවිනිශ්චිතතාවක් නිර්මාණය කිරීම",
        "විදුලි බලය නිතර විසන්ධි වීම සහ වරායන් හා මහාමාර්ගවල දැඩි ප්‍රවාහන තදබදය පැවතීම",
        "විදේශීය සමාගම්වලට නවීන තාක්ෂණය හෝ යන්ත්‍රසූත්‍ර රට තුළට ගෙන ඒම සම්පූර්ණයෙන් තහනම් කිරීම",
        "විදේශ ණය මත යැපෙනවාට වඩා තාක්ෂණය හා රැකියා රැගෙන එන ආයෝජන ආර්ථිකයට හිතකරය."),
      q(t, "19 වන සියවසේ ශ්‍රී ලංකාවේ කඳුකර කෝපි හා තේ වතු ආර්ථිකය ගොඩනැගීමේදී දකුණු ඉන්දියාවෙන් ශ්‍රමිකයන් ගෙන්වීමට හේතු වූයේ කුමක්ද?",
        "වතු තුළම පදිංචි වී වසර පුරා අඛණ්ඩව ශ්‍රමය සපයන ස්ථිර කුලී ශ්‍රම බලකායක් ලබා ගැනීමේ අවශ්‍යතාව",
        "කඳුකර ප්‍රදේශවල ගැඹුරු ගල් අඟුරු පතල් හා යකඩ ලෝපස් කර්මාන්තශාලා පවත්වාගෙන යාමේ අරමුණ",
        "මධ්‍යම කඳුකරයේ මුහුදු වරායන් හා නැව් තටාකාංගණ ඉදිකර බහාලුම් නැව් හැසිරවීම සිදු කිරීම",
        "දේශීය ගොවීන් තම වී කුඹුරු සියල්ල විකුණා නගරයේ බැංකු රැකියා සඳහා සම්පූර්ණයෙන් මාරු වී තිබීම",
        "වැවිලි ආර්ථිකයේ ආරම්භය ශ්‍රී ලංකාවේ ප්‍රවාහන ජාලය හා ජනගහන ව්‍යාප්තිය වෙනස් කළේය."),
      q(t, "ගෝලීයකරණය හමුවේ මැටි බඳුන්, අත් යන්ත්‍ර රෙදි හා සාම්ප්‍රදායික කර්මාන්තවලට එල්ල වන ප්‍රධාන තරඟකාරී අභියෝගය කුමක්ද?",
        "මහා පරිමාණ කම්හල්වල අඩු පිරිවැයට නිපදවන ප්ලාස්ටික් හා කෘත්‍රිම ආදේශක භාණ්ඩ සමඟ මිලෙන් තරඟ කිරීම",
        "විදේශීය කම්හල්වලින් නිපදවන සියලුම භාණ්ඩ සාම්ප්‍රදායික භාණ්ඩවලට වඩා දස ගුණයකින් මිල අධික වීම",
        "පාරිභෝගිකයන් ප්ලාස්ටික් හා යන්ත්‍රසූත්‍ර භාණ්ඩ මිලදී ගැනීම ලෝකය පුරා නීතියෙන් තහනම් කර තිබීම",
        "දේශීය ශිල්පීන්ට අවශ්‍ය මැටි හා නූල් අමුද්‍රව්‍ය සියල්ල රජය විසින් සම්පූර්ණයෙන් නොමිලේ ලබා දීම",
        "නවීන නිර්මාණකරණය හා සංචාරක වෙළඳපොළ සමඟ ඒකාබද්ධ වීම සාම්ප්‍රදායික කර්මාන්ත රැක ගැනීමට උපකාරී වේ."),
      q(t, "ඉඩම් හිඟ නාගරික ප්‍රදේශවල 'හරිතාගාර හා ජලරෝපිත කෘෂිකර්මය' (Hydroponics) භාවිත කිරීම ප්‍රායෝගික වන්නේ ඇයි?",
        "පස් නොමැතිව පෝෂක ද්‍රාවණ මගින් ඉතා කුඩා ඉඩමක අඩු ජලයකින් වසර පුරා නැවුම් එළවළු වැවිය හැකි බැවින්",
        "හරිතාගාර වගාව සඳහා විශාල නිවර්තන වැසි වනාන්තර කපා ඉඩම් හෙළි කිරීම අනිවාර්ය අවශ්‍යතාවක් බැවින්",
        "සාමාන්‍ය වගාවට වඩා කිහිප ගුණයකින් වැඩි ජල ප්‍රමාණයක් හා රසායනික කෘමිනාශක නාස්ති වන බැවින්",
        "ශාක වර්ධනය සඳහා සූර්යාලෝකය හෝ ජලය කිසිසේත් අවශ්‍ය නොවන බැවින් අඳුරු උමං තුළ පමණක් වැවිය හැකි බැවින්",
        "නෙදර්ලන්තය වැනි කුඩා රටවල් හරිතාගාර තාක්ෂණයෙන් ලොව ප්‍රමුඛ කෘෂි අපනයනකරුවන් බවට පත්ව ඇත."),
      q(t, "තේ, රබර්, පොල් වැනි ස්ථිර බෝග සහ වී, එළවළු වැනි වාර්ෂික බෝග අතර ආයෝජන හා අස්වනු කාලය වෙනස් වන්නේ කෙසේද?",
        "ස්ථිර බෝගවල අස්වැන්න ලැබීමට වසර කිහිපයක් බලා සිටිය යුතු අතර වාර්ෂික බෝගවලින් මාස කිහිපයකින් අස්වැන්න ලැබේ",
        "වී ගසකින් පළමු අස්වැන්න ලබා ගැනීමට අවම වශයෙන් වසර දහයක කාලයක් බලා සිටීමට ගොවීන්ට සිදු වේ",
        "පොල් හා රබර් පැළ සිටුවා සති දෙකක් ඇතුළත සම්පූර්ණ වාණිජ අස්වැන්න නෙළා ගැනීමට හැකියාව පවතී",
        "ස්ථිර බෝග හා වාර්ෂික බෝග අතර ප්‍රාග්ධන ආයෝජන කාලයේ හෝ අස්වනු චක්‍රයේ කිසිදු වෙනසක් නොමැත",
        "ස්ථිර බෝග වගා කරන කුඩා ගොවීන්ට මුල් වසර කිහිපයේදී දිගුකාලීන සහන ණය පහසුකම් අවශ්‍ය වේ."),
      q(t, "ශ්‍රී ලංකාවේ වෙළඳ හිඟය (Trade Deficit) ඉහළ යාමට බලපාන ප්‍රධාන ආනයන හා අපනයන ව්‍යුහමය හේතුව කුමක්ද?",
        "ඛනිජ තෙල්, යන්ත්‍රසූත්‍ර හා තිරිඟු වැනි අත්‍යවශ්‍ය ආනයන වියදම සාම්ප්‍රදායික අපනයන ආදායම ඉක්මවා යාම",
        "ශ්‍රී ලංකාවේ තේ හා ඇඟලුම් විදේශීය වෙළඳපොළවලට අලෙවි කිරීම සම්පූර්ණයෙන්ම තහනම් කර තිබීම",
        "දේශීය වෙළඳපොළ සඳහා ඛනිජ තෙල් හා ගල් අඟුරු අතිරික්ත ලෙස විදේශයන්ට අපනයනය කිරීම",
        "රට තුළ සියලුම මෝටර් රථ හා ගුවන් යානා දේශීය අමුද්‍රව්‍යවලින් පමණක් නිෂ්පාදනය කිරීම",
        "ඉහළ අගය එකතු කළ අපනයන වැඩි කිරීමෙන් හා බලශක්ති ආනයන අඩු කිරීමෙන් වෙළඳ හිඟය පාලනය කළ හැකිය."),
      q(t, "පොල් ආශ්‍රිත කර්මාන්ත අතර 'කපා වේලූ පොල් (Desiccated Coconut)' හා 'වර්ජින් පොල් තෙල්' අපනයනය ආර්ථිකමය වශයෙන් වැදගත් වන්නේ ඇයි?",
        "අමු පොල් ගෙඩි වශයෙන් විකිණීමට වඩා ඉහළ විදේශ විනිමයක් රැස් කිරීමට ඉන් හැකි වීම",
        "මෙම නිෂ්පාදන සැකසීමේදී පොල් ගසේ මුල් හා කඳන් සම්පූර්ණයෙන් කපා ඉවත් කරන බැවින්",
        "දේශීය ජනතාවගේ ආහාර පරිභෝජනය සඳහා පොල් භාවිත කිරීම නීතියෙන් සම්පූර්ණයෙන් තහනම් කර ඇති බැවින්",
        "කපා වේලූ පොල් නිපදවීම සඳහා පොල් වෙනුවට ආනයනික තිරිඟු පිටි පමණක් යොදා ගන්නා බැවින්",
        "කුරුණෑගල, පුත්තලම හා ගම්පහ පොල් ත්‍රිකෝණයේ පොල් මෝල් ජාලය ප්‍රධාන රැකියා මූලාශ්‍රයකි."),
      q(t, "පුල්මුඩේ ඛනිජ වැලි නිධියෙන් ලැබෙන ඉල්මනයිට්, රූටයිල් හා සර්කෝන් දේශීයව පිරිපහදු කිරීමෙන් ලැබෙන ආර්ථික ප්‍රතිලාභය කුමක්ද?",
        "අමු ඛනිජ වැලි අඩු මිලට විකිණීම වෙනුවට ටයිටේනියම් වර්ණක නිපදවා ඉහළ ආදායමක් ලැබීම",
        "නැගෙනහිර වෙරළ තීරයේ ධීවර කර්මාන්තය හා සංචාරක කටයුතු සම්පූර්ණයෙන් නතර කර දැමීමට හැකි වීම",
        "මුහුදු වැලි සියල්ල ගොඩනැගිලි කපරාරු සඳහා කොළඹ නගරයට ප්‍රවාහනය කර අලෙවි කිරීමට හැකි වීම",
        "ඉල්මනයිට් ඛනිජය දහනය කර දිවයිනේ සියලුම තාප විදුලි බලාගාර ක්‍රියාත්මක කරවීමට හැකි වීම",
        "ටයිටේනියම් ඩයොක්සයිඩ් තීන්ත, ප්ලාස්ටික්, කඩදාසි හා ගගනගාමී ලෝහ කර්මාන්ත සඳහා ඉහළ ඉල්ලුමක් ඇත."),
      q(t, "ශ්‍රී ලංකාවේ බෝගල හා කහටගහ පතල්වලින් ලැබෙන ඉහළ සංශුද්ධතාවයෙන් යුත් මිනිරන් (Vein Graphite) ලෝකයේ සුවිශේෂී වන්නේ ඇයි?",
        "ලිතියම්-අයන් බැටරි, ලිහිසි තෙල් හා විශේෂිත කර්මාන්ත උඳුන් සඳහා ඉහළ ඉල්ලුමක් පැවතීම",
        "එය ඉතා මෘදු බැවින් ගොඩනැගිලි අත්තිවාරම් බැඳීම සඳහා කළුගල් වෙනුවට යොදා ගන්නා බැවින්",
        "ලංකාවේ මිනිරන් ජලයේ දියවී කෘෂිකාර්මික පොහොර නිපදවීමට පමණක් භාවිත කෙරෙන බැවින්",
        "විද්‍යුත් ධාරාව සන්නයනය කිරීමට කිසිසේත්ම නොහැකි පරිවාරක ඛනිජයක් ලෙස භාවිත වන බැවින්",
        "අමු මිනිරන් අගය එකතු කළ ග්‍රැෆීන් හා බැටරි ඇනෝඩ ද්‍රව්‍ය බවට පත් කිරීමෙන් විශාල ආදායමක් ලැබේ."),
      q(t, "එප්පාවල රොක් පොස්පේට් නිධිය ආශ්‍රිත කර්මාන්තය දේශීය කෘෂි ආර්ථිකයට ඉතා වැදගත් වන්නේ කුමන හේතුව නිසාද?",
        "වැවිලි හා වී වගාවට අවශ්‍ය පොස්පේට් පොහොර දේශීයව නිපදවා විදේශ විනිමය ඉතිරි කර ගැනීම",
        "රජරට ප්‍රදේශයේ සියලුම වැව්වල ජලය පිරිසිදු කිරීමේ රසායනිකයක් ලෙස යොදා ගන්නා බැවින්",
        "රොක් පොස්පේට් පාෂාණ කැබලි සිමෙන්ති නිෂ්පාදනයේ ප්‍රධාන ඉන්ධනය ලෙස දහනය කරන බැවින්",
        "කෘෂිකාර්මික ඉඩම්වල පස සම්පූර්ණයෙන් නිසරු කර වල් පැළෑටි පාලනයට යොදා ගන්නා බැවින්",
        "තනි සුපර් පොස්පේට් නිෂ්පාදනය දියුණු කිරීමෙන් කෙටි කාලීන බෝග සඳහාද එය සුදුසු කළ හැකිය."),
      q(t, "සෙවනගල, පැල්වත්ත හා හිඟුරාන උක් කර්මාන්තශාලා ආශ්‍රිතව උක් ගස්වලින් සීනි නිෂ්පාදනයට අමතරව ලබා ගන්නා අතුරු ආර්ථික ප්‍රතිලාභය කුමක්ද?",
        "උක් රොඩු (Bagasse) දහනයෙන් විදුලිය නිපදවීමත් මොලෑසස් මගින් කාර්මික එතනෝල් නිපදවීමත්",
        "උක් පත්‍ර මගින් වාහන ටයර් හා ප්ලාස්ටික් නල මහා පරිමාණයෙන් නිෂ්පාදනය කිරීමත්",
        "උක් යුෂ භාවිතයෙන් ලෝහ කර්මාන්ත සඳහා යකඩ හා වානේ උණු කිරීමට ශක්තිය ලබා ගැනීමත්",
        "උක් වගා බිම්වල වසර පුරා මිරිදිය ධීවර කර්මාන්තය හා ලුණු ලේවා පවත්වාගෙන යාමත්",
        "කෘෂි අපද්‍රව්‍ය බලශක්තිය බවට පත් කිරීම චක්‍රීය ආර්ථික කළමනාකරණයට හොඳ නිදසුනකි."),
      q(t, "හම්බන්තොට, මොණරාගල හා මඩකලපුව වැනි වියළි කලාපීය දිස්ත්‍රික්කවල මී ගව පාලනය හා 'මී කිරි' කර්මාන්තය වර්ධනය වී ඇත්තේ ඇයි?",
        "වැව් පිටි හා පුළුල් තෘණ බිම් පැවතීමත් උණුසුම් දේශගුණයට මී ගවයන් හොඳින් ඔරොත්තු දීමත්",
        "එම දිස්ත්‍රික්කවල වසර පුරා සීතල මිදුණු ටුන්ඩ්‍රා දේශගුණයක් හා හිම පතනයක් පවතින බැවින්",
        "වියළි කලාපයේ මී ගවයන් සඳහා ආනයනික ඇල්ප්ස් තෘණ වර්ග පමණක් ගුවනින් ගෙන්වන බැවින්",
        "සාම්ප්‍රදායිකව මී කිරි නිෂ්පාදනය මුහුදු වෙරළේ ලවණ ජලය භාවිතයෙන් පමණක් සිදු කරන බැවින්",
        "රුහුණු මී කිරි මැටි හට්ටි කර්මාන්තය හා ග්‍රාමීය පවුල් ආදායම සමඟ තදින් බැඳී පවතී."),
      q(t, "කුරුඳු හා ගම්මිරිස් අමු කුළුබඩු ලෙස අපනයනය කරනවාට වඩා 'කුළුබඩු තෙල් හා ඔලියොරෙසින්' නිස්සාරණය කිරීම වාසිදායක වන්නේ ඇයි?",
        "ඖෂධ, සුවඳ විලවුන් හා ආහාර කර්මාන්තවලට සෘජුව අලෙවි කර ඉහළ ඒකක අගයක් ලැබීම",
        "නිස්සාරණය කරන ලද තෙල් වර්ගවල බර අමු කුළුබඩු බරට වඩා සිය ගුණයකින් වැඩි වන බැවින්",
        "නිස්සාරණයෙන් පසු ඉතිරි වන කුළුබඩු රොඩු ආහාර ලෙස සෑම රටකටම අපනයනය කළ හැකි බැවින්",
        "කුළුබඩු තෙල් නිපදවීම සඳහා කිසිදු යන්ත්‍රෝපකරණයක් හෝ තාක්ෂණික දැනුමක් අවශ්‍ය නොවන බැවින්",
        "ශ්‍රී ලංකාවේ කුරුඳු කොළ තෙල් හා පොතු තෙල් ජාත්‍යන්තර වෙළඳපොළේ ඉහළ මිලක් ලබයි."),
      q(t, "නුවරඑළිය, ගම්පහ හා කුරුණෑගල දිස්ත්‍රික්කවල වාණිජ මල් හා විසිතුරු පත්‍ර වගාව (Floriculture) ව්‍යාප්ත වීමට බලපෑ ප්‍රධාන සාධකය කුමක්ද?",
        "විවිධ දේශගුණික තත්ත්වයන් පැවතීම හා කටුනායක ගුවන් තොටුපළට පහසුවෙන් ළඟා විය හැකි වීම",
        "විසිතුරු මල් සියල්ල වියළි කලාපයේ විශාල වැව් තුළ පමණක් ස්වාභාවිකව වැවෙන බැවින්",
        "මෙම මල් වර්ග කල් ඉකුත් නොවී මාස ගණනක් නැව් මගින් මුහුදු ප්‍රවාහනය කළ හැකි බැවින්",
        "මල් වගාව සඳහා ජලය හා හිරු එළිය කිසිසේත්ම අවශ්‍ය නොවන බැවින්",
        "නැවුම් කැපූ මල් හා පැළ වර්ග ජපානය, යුරෝපය හා මැදපෙරදිග රටවලට ගුවන් මගින් අපනයනය කෙරේ."),
      q(t, "ශ්‍රී ලංකාවේ 'විසිතුරු මසුන් අභිජනන හා අපනයන කර්මාන්තය' (Ornamental Fish Industry) ග්‍රාමීය හා අර්ධ-නාගරික ප්‍රදේශවල සාර්ථක වී ඇත්තේ කෙසේද?",
        "කුඩා බිම් කඩක අඩු ප්‍රාග්ධනයකින් පවත්වා ගත හැකි වීමත් ඉහළ විදේශ ඉල්ලුමක් පැවතීමත්",
        "විසිතුරු මසුන් සෑම විටම ගැඹුරු මුහුදේ බහුදින යාත්‍රා මගින් පමණක් අල්ලා ගන්නා බැවින්",
        "සියලුම විසිතුරු මසුන් දේශීය ජලාශවලට මුදා හැරීමෙන් විදේශ විනිමය සෘජුවම ලැබෙන බැවින්",
        "මසුන් ප්‍රවාහනය සඳහා ඔක්සිජන් හෝ ජලය අඩංගු ඇසුරුම් කිසිසේත්ම භාවිත නොකරන බැවින්",
        "ගම්පහ හා කුරුණෑගල දිස්ත්‍රික්කවල මිරිදිය විසිතුරු මසුන් ඇති කිරීම ප්‍රධාන ස්වයං රැකියාවකි."),
      q(t, "කොළඹ, මීගමුව හා ගාල්ල ආශ්‍රිතව 'බෝට්ටු නිෂ්පාදන හා නාවික අලුත්වැඩියා කර්මාන්තය' දියුණු වීමට බලපෑ සාධක මොනවාද?",
        "දේශීය ධීවර කර්මාන්තයේ ඉල්ලුම, නාවික මාර්ග පිහිටීම හා පුහුණු කාර්මික ශිල්පීන් සිටීම",
        "දිවයිනේ මධ්‍යම කඳුකරයේ ගංගාවල විශාල බහාලුම් නැව් යාත්‍රා කිරීම සඳහා ඉල්ලුම පැවතීම",
        "බෝට්ටු නිපදවීමට අවශ්‍ය සියලුම ෆයිබර්ග්ලාස් අමුද්‍රව්‍ය දේශීය වනාන්තරවලින් නොමිලේ ලැබීම",
        "ගොඩබිම් මහාමාර්ග පද්ධතිය සම්පූර්ණයෙන්ම අහෝසි කර බෝට්ටු පමණක් භාවිත කිරීම",
        "ශ්‍රී ලංකාවේ නිෂ්පාදිත ෆයිබර්ග්ලාස් ධීවර හා සංචාරක බෝට්ටු අප්‍රිකානු හා ආසියානු රටවලටද අපනයනය කෙරේ."),
      q(t, "ස්වාභාවික රබර් අමුද්‍රව්‍යයක් ලෙස භාවිත කරමින් 'ඝන ටයර් (Solid Tires)' නිපදවා අපනයනය කිරීම ශ්‍රී ලංකාවට වැදගත් වන්නේ ඇයි?",
        "අමු රබර් ෂීට් අපනයනයට වඩා වැඩි අගයක් එක් කරමින් ගෝලීය කාර්මික වෙළඳපොළ ජය ගැනීම",
        "සියලුම ඝන ටයර් වර්ග ලංකාවේ පාපැදි සඳහා පමණක් දේශීයව භාවිත කෙරෙන බැවින්",
        "ටයර් නිෂ්පාදනයේදී රබර් කිරි වෙනුවට සිමෙන්ති හා වැලි පමණක් ප්‍රධාන ලෙස යොදා ගන්නා බැවින්",
        "එම කම්හල් පිහිටුවීම සඳහා රබර් වගාවෙන් තොර ඉහළ කඳුකර ප්‍රදේශ පමණක් තෝරා ගන්නා බැවින්",
        "ෆෝක්ලිෆ්ට් හා ඉදිකිරීම් යන්ත්‍ර සඳහා ඝන ටයර් සැපයීමේදී ශ්‍රී ලංකාව ලොව ප්‍රමුඛ රටකි."),
      q(t, "උණ බම්බු, පන් හා පුවක් කොළ ආශ්‍රිතව 'පරිසර හිතකාමී ඇසුරුම් නිෂ්පාදන' බිහිවීම සංචාරක හා ග්‍රාමීය ආර්ථිකයට දායක වන්නේ කෙසේද?",
        "එක්වරක් භාවිත කරන ප්ලාස්ටික් ආදේශ කරමින් ග්‍රාමීය ශිල්පීන්ට නව හරිත වෙළඳපොළක් විවෘත කිරීම",
        "සියලුම දේශීය කෘෂිකාර්මික ඉඩම් හෙළි කර ඒවායේ ප්ලාස්ටික් කර්මාන්තශාලා පමණක් ඉදිකිරීම",
        "පුවක් කොළ පිඟන් නිෂ්පාදනය සඳහා විදේශයන්ගෙන් මිල අධික රසායනික ද්‍රව්‍ය ආනයනය කිරීම",
        "ග්‍රාමීය ශිල්පීන්ගේ නිෂ්පාදන වෙළඳපොළට යැවීම සම්පූර්ණයෙන්ම තහනම් කර තැබීම",
        "පාරිසරික සංචාරක හෝටල් හා විදේශීය කාබනික වෙළඳපොළවල මෙම දිරාපත් වන ඇසුරුම්වලට ඉහළ ඉල්ලුමක් ඇත."),
      q(t, "නැගෙනහිර වෙරළේ පිහිටි 'ත්‍රිකුණාමලය වරායේ' ප්‍රධාන ස්වාභාවික භූගෝලීය වාසිය කුමක්ද?",
        "ලොව විශාලතම ස්වාභාවික ගැඹුරු වරායන්ගෙන් එකක් වීම හා බෙංගාල බොක්කට සෘජු ප්‍රවේශය තිබීම",
        "මුහුදු ජලය කිසිසේත්ම නොමැති වියළි ගොඩබිම් නිම්නයක් තුළ පිහිටා තිබීම",
        "වසරේ මාස හයක් පුරාම ඝන අයිස් තට්ටුවකින් වැසී නැව් ගමනාගමනය නතර වී තිබීම",
        "මහවැලි ගංගාවේ මුදුන් කඳුකර මූලාශ්‍රය ආසන්නයේ මුහුදු මට්ටමේ සිට ඉතා ඉහළින් පිහිටීම",
        "ගැඹුරු දිය හාරා නඩත්තු කිරීමේ වියදම අඩු වීම තොග භාණ්ඩ හා බලශක්ති කේන්ද්‍රයක් ලෙස එහි අගය වැඩි කරයි."),
      q(t, "දක්ෂිණ අධිවේගී මාර්ගය හා කොළඹ-කටුනායක අධිවේගී මාර්ගය ශ්‍රී ලංකාවේ ආර්ථික භූගෝලයට බලපෑවේ කෙසේද?",
        "ගමන් කාලය හා ප්‍රවාහන පිරිවැය අඩු කරමින් දකුණු සංචාරක කලාපය හා වරාය/ගුවන් තොටුපළ යා කිරීම",
        "රටේ සියලුම දුම්රිය මාර්ග ගලවා ඉවත් කර භාණ්ඩ ප්‍රවාහනය සම්පූර්ණයෙන් නතර කර දැමීම",
        "ගාල්ල හා මාතර නගරවල කෘෂිකාර්මික ඉඩම් හා ධීවර වරායන් සියල්ල වසා දැමීම",
        "විදේශීය සංචාරකයන්ට දකුණු පළාතට ඇතුළු වීම සඳහා තීරු බදු පැනවීමට හේතු වීම",
        "කාර්යක්ෂම මාර්ග සම්බන්ධතා ප්‍රාදේශීය නගරවල ඉඩම් අගය හා සේවා කර්මාන්ත වර්ධනයට ඉවහල් වේ."),
      q(t, "බර භාණ්ඩ හා මගීන් දිගු දුර ප්‍රවාහනයේදී මහාමාර්ගවලට වඩා දුම්රිය ප්‍රවාහනය ආර්ථික වශයෙන් ලාභදායී වන්නේ ඇයි?",
        "එක් වරකට විශාල බර ප්‍රමාණයක් අඩු ඉන්ධන පිරිවැයකින් හා මාර්ග තදබදයෙන් තොරව ගෙන යා හැකි බැවින්",
        "දුම්රිය මාර්ග සෑම නිවසකම දොරකඩ දක්වාම පහසුවෙන් ඉදිකර ඇති බැවින්",
        "දුම්රිය එන්ජින් ධාවනය සඳහා කිසිදු ඩීසල් හෝ විදුලි බලශක්තියක් අවශ්‍ය නොවන බැවින්",
        "දුම්රිය මගින් භාණ්ඩ ප්‍රවාහනයේදී ඒවායේ බර අනුව ගාස්තු අය නොකරන බැවින්",
        "කෙසේ වෙතත් නිවසින් නිවසට බෙදා හැරීමේදී (Door-to-door delivery) මහාමාර්ග ප්‍රවාහනය වඩා නම්‍යශීලී වේ."),
      q(t, "මන්නාරමේ 'තම්බපවනි සුළං විදුලි උද්‍යානය' හා සියඹලාණ්ඩුව සූර්ය බලාගාර ව්‍යාපෘති ජාතික ආර්ථිකයට වැදගත් වන්නේ ඇයි?",
        "ආනයනික ඛනිජ තෙල් හා ගල් අඟුරු මත යැපීම අඩු කර පිරිසිදු විදුලිය නිපදවා විදේශ විනිමය ඉතිරි කිරීම",
        "සුළං හා සූර්ය ශක්තිය මගින් වියළි කලාපයේ වර්ෂාපතනය සම්පූර්ණයෙන්ම නතර කර දැමීම",
        "විදුලි බලය නිපදවීම සඳහා ගල් අඟුරු ආනයනය දස ගුණයකින් ඉහළ නැංවීමට උපකාරී වීම",
        "මන්නාරමේ සාම්ප්‍රදායික ධීවර කර්මාන්තය හා ලුණු නිෂ්පාදනය සම්පූර්ණයෙන් නතර කිරීම",
        "මන්නාරම් වෙරළ තීරයේ නිරන්තර තද සුළං ප්‍රවාහය සුළං ටර්බයින ක්‍රියාත්මක කිරීමට ඉතා යෝග්‍ය වේ."),
      q(t, "මහවැලි හා ලක්ෂපාන ජල විදුලි බලාගාර පද්ධති ශ්‍රී ලංකාවේ කාර්මික ක්ෂේත්‍රයට ශක්තියක් වී ඇත්තේ කෙසේද?",
        "අඩු මෙහෙයුම් පිරිවැයකින් විශ්වසනීය විදුලි බලය සපයමින් රටේ කර්මාන්තශාලා ජාලය පවත්වා ගැනීමෙන්",
        "සියලුම කඳුකර ගංගාවල ජලය කර්මාන්තශාලා තුළට හරවා යන්ත්‍ර සේදීමට යොදා ගැනීමෙන්",
        "නියං කාලවලදී පමණක් උපරිම ජල විදුලිය නිපදවා වැසි කාලයේ බලාගාර වසා දැමීමෙන්",
        "ගල් අඟුරු හා ඩීසල් යොදා ජල විදුලි ටර්බයින කරකැවීමට විශාල පිරිවැයක් දැරීමෙන්",
        "කෙසේ වෙතත් නියං කාලයේ ජලාශ සිඳී යාමේදී තාප හා පුනර්ජනනීය බලශක්ති මිශ්‍රණයක් අවශ්‍ය වේ."),
      q(t, "බියගම හා රත්මලාන කාර්මික කලාපවල 'මධ්‍යගත අපජල පවිත්‍රාගාර' (CETPs) පිහිටුවීම තිරසාර කාර්මික සංවර්ධනයට අත්‍යවශ්‍ය වන්නේ ඇයි?",
        "කර්මාන්තශාලා අපද්‍රව්‍ය හා ඩයි වර්ග ගංගාවලට බැහැර කිරීමෙන් සිදුවන ජල දූෂණය වැළැක්වීම සඳහා",
        "කර්මාන්තශාලාවල නිපදවන භාණ්ඩවල ප්‍රමාණය හා බර ඉහළ නැංවීම සඳහා ජලය එකතු කිරීමට",
        "ගංගාවල ජල මට්ටම ඉහළ දමා කාර්මික කලාපවලට ගංවතුර ගැලීම වේගවත් කිරීම සඳහා",
        "අපිරිසිදු රසායනික ජලය පිරිපහදු නොකරම සෘජුවම පානීය ජල නල පද්ධතියට මුදා හැරීම සඳහා",
        "පාරිසරික ප්‍රමිතීන් සපුරාලීම යුරෝපා හා ඇමෙරිකානු ගැනුම්කරුවන්ගෙන් අපනයන ඇණවුම් ලබා ගැනීමටද කොන්දේසියකි."),
      q(t, "ශ්‍රී ලංකාවේ ඇඟලුම් කර්මාන්තශාලා 'සදාචාරාත්මක නිෂ්පාදන ප්‍රමිතීන්' (Ethical Manufacturing & Fair Wages) රැක ගැනීම වැදගත් වන්නේ ඇයි?",
        "කම්කරු අයිතීන් හා ආරක්ෂාව තහවුරු කිරීමෙන් ගෝලීය ප්‍රධාන සන්නාමවල විශ්වාසය හා ඇණවුම් දිනා ගැනීම",
        "සේවකයන්ගේ සේවා කාලය දිනකට පැය විස්සක් දක්වා ඉහළ නංවා වැටුප් කප්පාදු කිරීමට",
        "කම්හල් තුළ ආරක්ෂක හා වාතාශ්‍ර පහසුකම් ඉවත් කර නිෂ්පාදන වියදම පහළ හෙළීමට",
        "ළමා ශ්‍රමය බහුලව යොදා ගනිමින් අපනයන නිෂ්පාදනවල මිල අඩු කිරීමට උත්සාහ ගැනීම",
        "Garments Without Guilt වැඩසටහන හරහා ශ්‍රී ලංකාව ජාත්‍යන්තරව ඉහළ කීර්තියක් අත්කර ගෙන ඇත."),
      q(t, "ග්‍රාමීය ප්‍රදේශවල 'සුළු පරිමාණ ස්වයං රැකියා හා ක්ෂුද්‍ර ව්‍යවසාය' (Micro-enterprises) ප්‍රවර්ධනය කිරීමෙන් දරිද්‍රතාව අඩු වන්නේ කෙසේද?",
        "පවුල් මට්ටමින් අතිරේක ආදායම් මාර්ග බිහි වී කාන්තාවන් හා තරුණයන් ආර්ථිකව සවිබල ගැන්වීමෙන්",
        "ගමේ සියලුම පවුල් ගොවිතැන හා නිෂ්පාදනය අතහැර විදේශ රටවලට පදිංචියට යාමෙන්",
        "විශාල බහුජාතික සමාගම්වලට ගමේ සියලුම ඉඩම් නොමිලේ පවරා දීමට කටයුතු කිරීමෙන්",
        "ග්‍රාමීය බැංකු පද්ධතිය වසා දමා මුදල් හුවමාරුව සම්පූර්ණයෙන්ම තහනම් කර දැමීමෙන්",
        "සුළු ණය පහසුකම්, තාක්ෂණික පුහුණුව හා වෙළඳපොළ සම්බන්ධතා මෙම ව්‍යාපාර සාර්ථක කරයි."),
      q(t, "ශ්‍රී ලංකාවේ ආර්ථික ක්‍රියාකාරකම් තුළ කාන්තා ශ්‍රම දායකත්වය ප්‍රධාන වශයෙන් කැපී පෙනෙන අංශ මොනවාද?",
        "වතු කර්මාන්තයේ තේ දළු නෙළීම, ඇඟලුම් කම්හල් සේවය, විදේශ රැකියා හා ක්ෂුද්‍ර ව්‍යවසාය",
        "ගැඹුරු මුහුදේ බහුදින ධීවර කටයුතු හා ගල් කොරි පිපිරවීම් කටයුතු පමණක් වීම",
        "විදේශීය ගුවන් යානා නඩත්තුව හා බර යකඩ වානේ උණු කිරීමේ කම්හල් පමණක් වීම",
        "කිසිදු ආර්ථික ක්ෂේත්‍රයක කාන්තා දායකත්වයක් ශ්‍රී ලංකාව තුළ වාර්තා නොවීම",
        "විදේශ විනිමය උපයන ප්‍රධාන ක්ෂේත්‍ර තුනෙහිම කාන්තා ශ්‍රම බලකාය තීරණාත්මක කාර්යභාරයක් ඉටු කරයි."),
      q(t, "ග්‍රාමීය ප්‍රදේශවල 'පාරිභෝගික හා සණස/සමුපකාර සමිති' පැවතීම සාමාන්‍ය ජන ජීවිතයට ආර්ථික සහනයක් වන්නේ කෙසේද?",
        "සාධාරණ මිලට අත්‍යවශ්‍ය ආහාර සැපයීමත් අඩු පොලී ඉතුරුම් හා ණය සේවා ලබා දීමත්",
        "අත්‍යවශ්‍ය ආහාර ද්‍රව්‍ය සියල්ල වෙළඳපොළෙන් සඟවා මිල දෙගුණයකින් ඉහළ දැමීමත්",
        "සාමාජිකයන්ගෙන් අධික පොලී අය කර විදේශීය කොටස් වෙළඳපොළවල පමණක් ආයෝජනය කිරීමත්",
        "සියලුම සිල්ලර වෙළඳසැල් වසා දමා භාණ්ඩ හුවමාරුව පමණක් ක්‍රියාත්මක කිරීමත්",
        "ලාභය සාමාජිකයන් අතර බෙදා ගැනීම සමුපකාර ව්‍යාපාරයේ මූලික ප්‍රජා ආර්ථික ලක්ෂණයයි."),
      q(t, "ශ්‍රී ලංකාවේ බස්නාහිර පළාත හා අනෙකුත් පළාත් අතර සේවා අංශයේ ව්‍යාප්තියේ දක්නට ලැබෙන ප්‍රාදේශීය විෂමතාව කුමක්ද?",
        "මූල්‍ය, තොරතුරු තාක්ෂණ හා වාණිජ සේවා බස්නාහිර පළාතේ කේන්ද්‍රගත වී අනෙකුත් පළාත්වල කෘෂිකර්මය ප්‍රමුඛ වීම",
        "උතුරු මැද හා ඌව පළාත්වල පමණක් බැංකු මූලස්ථාන හා කොටස් වෙළඳපොළ පිහිටා තිබීම",
        "බස්නාහිර පළාතේ ජනගහනයෙන් සියයට අනූවක්ම හේන් ගොවිතැන හා මිරිදිය ධීවර කර්මාන්තයේ යෙදීම",
        "සෑම දිස්ත්‍රික්කයකම ජාතික ආදායම් දායකත්වය කිසිදු වෙනසකින් තොරව සමානව බෙදී පැවතීම",
        "ප්‍රාදේශීය ආර්ථික මධ්‍යස්ථාන හා කාර්මික උද්‍යාන බිහි කිරීම මෙම අසමතුලිතතාව අඩු කිරීමට උපකාරී වේ."),
      q(t, "රාජ්‍ය ආයතනවල 'ඩිජිටල්කරණය හා ඊ-රාජ්‍ය සේවා' (E-Government Services) ආර්ථික කටයුතු වේගවත් කිරීමට බලපාන්නේ කෙසේද?",
        "ව්‍යාපාර ලියාපදිංචිය, බදු ගෙවීම හා බලපත්‍ර ලබා ගැනීම මාර්ගගතව ඉටු කර කාලය හා පිරිවැය අඩු කිරීම",
        "සෑම පුරවැසියෙකුම කුඩා ලිපි ලේඛන සඳහාත් දින ගණනක් කොළඹ කාර්යාලවල රැඳී සිටීමට සැලැස්වීම",
        "ව්‍යාපාරිකයන්ට කිසිදු බලපත්‍රයක් හෝ බදු වාර්තාවක් ලබා ගැනීමට අවසර නොදී සිටීම",
        "බැංකු හා රාජ්‍ය ආයතන අතර සියලුම සන්නිවේදන කටයුතු තැපැල් කාර්යාල හරහා පමණක් සීමා කිරීම",
        "කඩදාසි භාවිතය අඩු වීම හා විනිවිදභාවය ඉහළ යාම ව්‍යාපාර පරිසරය ශක්තිමත් කරයි."),
      q(t, "ශ්‍රී ලංකාවේ තැනිතලා වියළි කලාපය හා මධ්‍යම කඳුකරය අතර ප්‍රවාහන මාර්ග ජාලයේ ඝනත්වය වෙනස් වන්නේ ඇයි?",
        "සමතලා භූමියේ මාර්ග ඉදිකිරීම පහසු වන අතර දැඩි බෑවුම් සහිත කඳුකරයේ වංගු හා පිරිවැය අධික වීම",
        "මධ්‍යම කඳුකරයේ කිසිදු නගරයක් හෝ ආර්ථික කටයුත්තක් නොපවතින බැවින් මාර්ග අවශ්‍ය නොවීම",
        "තැනිතලා ප්‍රදේශවල පස ඉතා මෘදු බැවින් කිසිදු මහාමාර්ගයක් ඉදිකිරීමට නොහැකි වීම",
        "කඳුකර ප්‍රදේශවල පමණක් ගුවන් යානා භාවිත කරන බැවින් ගොඩබිම් මාර්ග සම්පූර්ණයෙන් තහනම් වීම",
        "කඳුකර මාර්ග ඉදිකිරීමේදී බෑවුම් ස්ථායිකරණය හා නායයාම් ආරක්ෂණ පියවර සඳහා විශාල වියදමක් දැරීමට සිදුවේ."),
      q(t, "ශ්‍රී ලංකාව වැනි සංවර්ධනය වෙමින් පවතින ආර්ථිකයකට 'අපනයන විවිධාංගීකරණය' (Export Diversification) අත්‍යවශ්‍ය වන්නේ ඇයි?",
        "තේ හා ඇඟලුම් මත පමණක් යැපීම වෙනුවට තොරතුරු තාක්ෂණ, කුළුබඩු, රබර් භාණ්ඩ හා නාවික සේවා වර්ධනය කිරීම",
        "දැනට ලෝක වෙළඳපොළේ හොඳින් අලෙවි වන තේ හා ඇඟලුම් අපනයනය සම්පූර්ණයෙන් නතර කර දැමීම",
        "රට තුළ නිපදවන සියලුම භාණ්ඩ අපනයනය නොකර ගබඩාවල රැස් කර තබා ගැනීම",
        "ලෝකයේ තනි රටකට පමණක් එක් වර්ගයක භාණ්ඩයක් පමණක් අලෙවි කිරීමේ ගිවිසුම්වලට එළඹීම",
        "විවිධ ක්ෂේත්‍ර හරහා ආදායම් ලැබීම ගෝලීය ආර්ථික අර්බුදවලදී රටේ ආර්ථික ස්ථාවරත්වය ආරක්ෂා කරයි."),
      q(t, "මැණික් පතල් හා ගල් කොරි කර්මාන්තයේදී 'පතල් වළවල් පුනරුත්ථාපනය හා බලපත්‍ර නියාමනය' අත්‍යවශ්‍ය වන්නේ ඇයි?",
        "ආර්ථික ප්‍රතිලාභ ලබන අතරම පාංශු ඛාදනය, ඉවුරු කඩා වැටීම හා මදුරුවන් බෝවීම වැළැක්වීම සඳහා",
        "සියලුම මැණික් පතල් හා ගල් කොරි වසර සියයක් පුරාම ජලයෙන් පුරවා විවෘතව තැබීම සඳහා",
        "පතල් කැණීමෙන් ලැබෙන මැණික් හා කළුගල් නැවත පොළොව යට වළ දැමීම නීතිගත කිරීම සඳහා",
        "මැණික් හා ඛනිජ සම්පත් හඳුනා ගැනීමේ භූ විද්‍යාත්මක කටයුතු සම්පූර්ණයෙන්ම තහනම් කිරීම සඳහා",
        "තිරසාර ඛනිජ කළමනාකරණය අනාගත පරපුරටත් පරිසරයත් ආර්ථික සම්පත්ද ඉතිරි කරයි."),
      q(t, "ගෝලීය නාවික සැපයුම් දාමවල ඇතිවන අර්බුද (උදා: වරාය තදබදය හෝ නැව් ගාස්තු ඉහළ යාම) දූපත් රාජ්‍ය ආර්ථිකවලට බලපාන්නේ කෙසේද?",
        "ආනයනික ආහාර, ඉන්ධන හා අමුද්‍රව්‍ය මිල ඉහළ ගොස් අපනයන භාණ්ඩ ප්‍රමාද වීමෙන් උද්ධමනය ඇති වීම",
        "දූපත් රාජ්‍යවල සියලුම භාණ්ඩ අසල්වැසි රටවලට ගොඩබිම් දුම්රියෙන් පමණක් පහසුවෙන් යැවීමට හැකි වීම",
        "නැව් ගාස්තු ඉහළ යාම හේතුවෙන් ආනයනික භාණ්ඩවල වෙළඳපොළ මිල ඉතා වේගයෙන් පහත වැටීම",
        "සමුද්‍ර වෙළඳාම නතර වූ විට දූපත් රාජ්‍යවල කාර්මික නිෂ්පාදනය කිසිදු බාධාවකින් තොරව දෙගුණ වීම",
        "එබැවින් අත්‍යවශ්‍ය ආහාර හා ඖෂධ සඳහා උපායමාර්ගික ආරක්ෂිත තොග හා දේශීය නිෂ්පාදන පවත්වා ගැනීම වැදගත්ය."),
      q(t, "කොළඹ හා හම්බන්තොට වරායන් ආශ්‍රිතව 'නැව් තෙල් සැපයීම (Maritime Bunkering) හා නැව් සේවා' ප්‍රවර්ධනය කිරීම ලාභදායී වන්නේ ඇයි?",
        "ප්‍රධාන නැගෙනහිර-බටහිර සාගර මාර්ගයේ ගමන් ගන්නා නැව්වලට ගමන් මගින් බැහැර නොවී සේවා ලබා ගත හැකි බැවින්",
        "මෙම වරායන් වෙත පැමිණෙන සියලුම වෙළඳ නැව්වලට ඉන්ධන හා ජලය නොමිලේ ලබා දිය යුතු බැවින්",
        "ඉන්දියානු සාගරයේ වෙළඳ නැව් ගමනාගමනය වෙනුවට ධීවර ඔරු පමණක් යාත්‍රා කරන බැවින්",
        "මෙම සේවාවන් සැපයීම සඳහා වරාය ජලය සම්පූර්ණයෙන් ඉවත් කර ගොඩබිම් මධ්‍යස්ථාන පිහිටුවන බැවින්",
        "නැව් කාර්ය මණ්ඩල මාරු කිරීම්, ජලය හා ආහාර සැපයීම වැනි සේවා සෘජු විදේශ විනිමය ගෙන එයි."),
      q(t, "වියළි කලාපීය වැව් ගම්මානවල දේශගුණික විපර්යාසවලට මුහුණ දීම සඳහා 'ඔරොත්තු දෙන බෝග විවිධාංගීකරණය' වැදගත් වන්නේ කෙසේද?",
        "වී වගාවට ජලය මදි කන්නවලදී කුරක්කන්, මුං, තල හා බඩ ඉරිඟු වගා කර ගොවි ආදායම රැක ගැනීම",
        "සියලුම වැව් හිස් කර එහි අධික ජලය ඉල්ලන නිවර්තන මල් වර්ග හා කෙසෙල් පමණක් වගා කිරීම",
        "වැසි අඩු කාලවලදී ගොවිබිම් සම්පූර්ණයෙන් අතහැර වගා කටයුතු වසර ගණනාවක් නතර කර දැමීම",
        "දේශීය ධාන්‍ය වර්ග වගාව නීතියෙන් තහනම් කර ආනයනික සුඛෝපභෝගී පලතුරු පමණක් වගා කිරීම",
        "අඩු ජල අවශ්‍යතාවක් ඇති අතිරේක ආහාර බෝග ග්‍රාමීය පෝෂණය හා ජීවනෝපාය සුරක්ෂිතතාව තහවුරු කරයි.")
    )
  }
}
